INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('3cdb9e54-1e9d-5703-a531-d6b47649ecc6', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 7, 7, 'In the third month they began to lay the foundation of the heaps, and finished them in the seventh month.'),
  ('58aba4f3-0b1a-5b0c-aad1-d874d1b5aac8', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 8, 8, 'When Hezekiah and the princes came and saw the heaps, they blessed Yahweh, and his people Israel.'),
  ('7c3c72a1-5012-58ad-a294-06f8d4a4cc70', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 9, 9, 'Then Hezekiah questioned the priests and the Levites concerning the heaps.'),
  ('301c985a-5bf2-57f8-abd4-af4f4b27e903', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 10, 10, 'Azariah the chief priest, of the house of Zadok, answered him and said, "Since people began to bring the offerings into the house of Yahweh, we have eaten and had enough, and have left plenty: for Yahweh has blessed his people; and that which is left is this great store."'),
  ('a41416c1-5cad-56f8-a7d8-019dc3b1c31d', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 11, 11, 'Then Hezekiah commanded them to prepare rooms in the house of Yahweh; and they prepared them.'),
  ('6811b579-26a4-5e34-a6f3-19dfb704df9d', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 12, 12, 'They brought in the offerings and the tithes and the dedicated things faithfully: and over them Conaniah the Levite was ruler, and Shimei his brother was second.'),
  ('d1b35a69-d1c4-5469-a7cb-1f97953eb60e', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 13, 13, 'Jehiel, and Azaziah, and Nahath, and Asahel, and Jerimoth, and Jozabad, and Eliel, and Ismachiah, and Mahath, and Benaiah, were overseers under the hand of Conaniah and Shimei his brother, by the appointment of Hezekiah the king, and Azariah the ruler of the house of God.'),
  ('065c1129-b0e7-5ca0-a201-7646df2db484', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 14, 14, 'Kore the son of Imnah the Levite, the porter at the east [gate], was over the freewill offerings of God, to distribute the offerings of Yahweh, and the most holy things.'),
  ('c391638e-895e-5f89-a36c-209e3767c7da', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 15, 15, 'Under him were Eden, and Miniamin, and Jeshua, and Shemaiah, Amariah, and Shecaniah, in the cities of the priests, in their office of trust, to give to their brothers by divisions, as well to the great as to the small:'),
  ('d7e126a1-1173-51bc-a402-20f1223476c1', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 16, 16, 'besides those who were reckoned by genealogy of males, from three years old and upward, even everyone who entered into the house of Yahweh, as the duty of every day required, for their service in their offices according to their divisions;'),
  ('6b97f0d3-dcfe-51c1-ada7-30843d32fdef', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 17, 17, 'and those who were reckoned by genealogy of the priests by their fathers'' houses, and the Levites from twenty years old and upward, in their offices by their divisions;'),
  ('fc50432d-b229-5196-a99c-3072c66215ab', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 18, 18, 'and those who were reckoned by genealogy of all their little ones, their wives, and their sons, and their daughters, through all the congregation: for in their office of trust they sanctified themselves in holiness.'),
  ('bd980332-6b7d-55f2-a6c0-bb3ae8ddf2ca', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 19, 19, 'Also for the sons of Aaron the priests, who were in the fields of the suburbs of their cities, in every city, there were men who were mentioned by name, to give portions to all the males among the priests, and to all who were reckoned by genealogy among the Levites.'),
  ('e257c885-cbb3-5f15-aa0d-49b1670076bb', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 20, 20, 'Hezekiah did so throughout all Judah; and he worked that which was good and right and faithful before Yahweh his God.'),
  ('a3fd0b40-2670-5e00-ad2b-559ebdea9888', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 21, 21, 'In every work that he began in the service of the house of God, and in the law, and in the commandments, to seek his God, he did it with all his heart, and prospered.'),
  ('08e8b1db-a6dc-53c2-a7e5-32731c891f88', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 1, 1, 'After these things, and this faithfulness, Sennacherib king of Assyria came, and entered into Judah, and encamped against the fortified cities, and thought to win them for himself.'),
  ('32210b5d-2c7f-5376-a736-006a55721e04', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 2, 2, 'When Hezekiah saw that Sennacherib was come, and that he was purposed to fight against Jerusalem,'),
  ('5accaa4a-75a4-5f73-a47a-f4f6250c9bcb', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 3, 3, 'he took counsel with his princes and his mighty men to stop the waters of the springs which were outside of the city; and they helped him.'),
  ('55a31af7-e9c2-5f73-a401-5da1c57c66b0', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 4, 4, 'So many people gathered together, and they stopped all the springs, and the brook that flowed through the midst of the land, saying, "Why should the kings of Assyria come, and find much water?"'),
  ('60a23060-c7cc-5f50-aec0-2c242b641cfc', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 5, 5, 'He took courage, and built up all the wall that was broken down, and raised [it] up to the towers, and the other wall outside, and strengthened Millo [in] the city of David, and made weapons and shields in abundance.'),
  ('dace6970-137e-57d5-a557-ddfdf3163bbd', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 6, 6, 'He set captains of war over the people, and gathered them together to him in the broad place at the gate of the city, and spoke comfortably to them, saying,'),
  ('9f9fb810-b1e8-5501-ab2a-286ff7ca7abe', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 7, 7, '"Be strong and courageous, don''t be afraid nor dismayed for the king of Assyria, nor for all the multitude who is with him; for there is a greater with us than with him.'),
  ('df9a20e4-ab2f-5fc3-a9d3-4a68b649f076', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 8, 8, 'With him is an arm of flesh; but with us is Yahweh our God to help us, and to fight our battles." The people rested themselves on the words of Hezekiah king of Judah.'),
  ('d6e075f5-a54c-5cac-a8a3-bc0eadfb240f', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 9, 9, 'After this did Sennacherib king of Assyria send his servants to Jerusalem, (now he was before Lachish, and all his power with him), to Hezekiah king of Judah, and to all Judah who were at Jerusalem, saying,'),
  ('bdfd7b04-f684-5080-a2ee-5bf519f8f424', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 10, 10, 'Thus says Sennacherib king of Assyria, "In whom do you trust, that you remain under siege in Jerusalem?'),
  ('f033d555-d48a-5a43-a552-9bee8ab823cc', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 11, 11, 'Doesn''t Hezekiah persuade you, to give you over to die by famine and by thirst, saying, ''Yahweh our God will deliver us out of the hand of the king of Assyria?'''),
  ('3fe6d526-1cee-5187-a9b7-a4fa85422c4c', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 12, 12, 'Hasn''t the same Hezekiah taken away his high places and his altars, and commanded Judah and Jerusalem, saying, ''You shall worship before one altar, and on it you shall burn incense?'''),
  ('e0f2fa5d-96bf-5008-ad48-79f5b2f281ca', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 13, 13, 'Don''t you know what I and my fathers have done to all the peoples of the lands? Were the gods of the nations of the lands in any way able to deliver their land out of my hand?'),
  ('af03ca67-485f-533e-a420-e6707cb5c788', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 14, 14, 'Who was there among all the gods of those nations which my fathers utterly destroyed, that could deliver his people out of my hand, that your God should be able to deliver you out of my hand?'),
  ('2c1cbe56-f438-5c83-a7b7-2f2e5f7f12c2', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 15, 15, 'Now therefore don''t let Hezekiah deceive you, nor persuade you in this way, neither believe him; for no god of any nation or kingdom was able to deliver his people out of my hand, and out of the hand of my fathers. How much less will your God deliver you out of my hand?"'),
  ('f4fbb535-ebfd-57e1-a545-b45e514fb82b', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 16, 16, 'His servants spoke yet more against Yahweh God, and against his servant Hezekiah.'),
  ('08050595-9014-5700-a1a9-c6bd059e9eaa', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 17, 17, 'He also wrote letters insulting Yahweh, the God of Israel, and to speak against him, saying, "As the gods of the nations of the lands, which have not delivered their people out of my hand, so shall the God of Hezekiah not deliver his people out of my hand."'),
  ('66e9ebf8-8cbb-5a68-ad3b-12ffdc521427', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 18, 18, 'They cried with a loud voice in the Jews'' language to the people of Jerusalem who were on the wall, to frighten them, and to trouble them; that they might take the city.'),
  ('83dc59ae-8b76-5ff4-ab67-3c4442cd6308', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 19, 19, 'They spoke of the God of Jerusalem, as of the gods of the peoples of the earth, which are the work of men''s hands.'),
  ('7eb55548-5ba9-5363-a0a1-9fa3cfc996fa', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 20, 20, 'Hezekiah the king, and Isaiah the prophet the son of Amoz, prayed because of this, and cried to heaven.'),
  ('d5b8c1ce-8e1d-5209-a39f-29f68f0cc9e5', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 21, 21, 'Yahweh sent an angel, who cut off all the mighty men of valor, and the leaders and captains, in the camp of the king of Assyria. So he returned with shame of face to his own land. When he had come into the house of his god, those who came forth from his own bowels killed him there with the sword.'),
  ('19ea3f98-79af-5d39-a5df-8f602f2b4c06', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 22, 22, 'Thus Yahweh saved Hezekiah and the inhabitants of Jerusalem from the hand of Sennacherib the king of Assyria, and from the hand of all [others], and guided them on every side.'),
  ('29b64dcd-c8fc-5b8b-a6c7-65908cfd220a', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 23, 23, 'Many brought gifts to Yahweh to Jerusalem, and precious things to Hezekiah king of Judah; so that he was exalted in the sight of all nations from thenceforth.'),
  ('d51d362e-0b60-5592-adc4-db6ed13c7ead', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 24, 24, 'In those days Hezekiah was sick even to death: and he prayed to Yahweh; and he spoke to him, and gave him a sign.'),
  ('3e94a955-fe61-5221-ac83-358caf1ba630', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 25, 25, 'But Hezekiah didn''t render again according to the benefit done to him; for his heart was lifted up: therefore there was wrath on him, and on Judah and Jerusalem.'),
  ('148a94a5-2121-584c-a164-b3c8f501eda4', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 26, 26, 'Notwithstanding Hezekiah humbled himself for the pride of his heart, both he and the inhabitants of Jerusalem, so that the wrath of Yahweh didn''t come on them in the days of Hezekiah.'),
  ('7326ed0e-c4ef-55af-a6c0-d9a5c2cc2e4a', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 27, 27, 'Hezekiah had exceeding much riches and honor: and he provided him treasuries for silver, and for gold, and for precious stones, and for spices, and for shields, and for all kinds of goodly vessels;'),
  ('5ccae82b-85d7-565e-aaed-b62996901af3', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 28, 28, 'storehouses also for the increase of grain and new wine and oil; and stalls for all kinds of animals, and flocks in folds.'),
  ('aae08b19-3586-5804-a05a-0110e2ea191a', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 29, 29, 'Moreover he provided him cities, and possessions of flocks and herds in abundance; for God had given him very much substance.'),
  ('173e1e54-0c0b-5150-a80e-137f9a5a2b09', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 30, 30, 'This same Hezekiah also stopped the upper spring of the waters of Gihon, and brought them straight down on the west side of the city of David. Hezekiah prospered in all his works.'),
  ('8717232a-2682-5b94-a589-6f5cbfc2fc2e', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 31, 31, 'However in [the business of] the ambassadors of the princes of Babylon, who sent to him to inquire of the wonder that was done in the land, God left him, to try him, that he might know all that was in his heart.'),
  ('c359a325-5795-5795-a0d4-0c7b6e3a3083', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 32, 32, 'Now the rest of the acts of Hezekiah, and his good deeds, behold, they are written in the vision of Isaiah the prophet the son of Amoz, in the book of the kings of Judah and Israel.'),
  ('080e6484-738f-5f0c-ad97-defa98e2e6a1', '661d9252-8b7f-5ad7-afa8-6956c782d6d7', NULL, 33, 33, 'Hezekiah slept with his fathers, and they buried him in the ascent of the tombs of the sons of David: and all Judah and the inhabitants of Jerusalem did him honor at his death. Manasseh his son reigned in his place.'),
  ('8f316077-b2b2-5d8d-a7e5-a870e306a505', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 1, 1, 'Manasseh was twelve years old when he began to reign; and he reigned fifty-five years in Jerusalem.'),
  ('175e0dd8-d2e7-5a42-a75d-d89e8c7678d6', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 2, 2, 'He did that which was evil in the sight of Yahweh, after the abominations of the nations whom Yahweh cast out before the children of Israel.'),
  ('c8195cdc-625d-5962-a593-3c8d6ffa41e8', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 3, 3, 'For he built again the high places which Hezekiah his father had broken down; and he reared up altars for the Baals, and made Asheroth, and worshiped all the army of the sky, and served them.'),
  ('0848731a-54b1-5bea-a541-5562b6c9ef89', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 4, 4, 'He built altars in the house of Yahweh, of which Yahweh said, "My name shall be in Jerusalem forever."'),
  ('4201c229-8be3-5194-ab74-4de088c95dd9', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 5, 5, 'He built altars for all the army of the sky in the two courts of the house of Yahweh.'),
  ('64d5a294-9ba6-5093-a8ec-118302ec9f92', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 6, 6, 'He also made his children to pass through the fire in the valley of the son of Hinnom; and he practiced sorcery, and used enchantments, and practiced sorcery, and dealt with those who had familiar spirits, and with wizards: he worked much evil in the sight of Yahweh, to provoke him to anger.'),
  ('efe55149-d33a-5c1e-aa46-7a82f7272171', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 7, 7, 'He set the engraved image of the idol, which he had made, in the house of God, of which God said to David and to Solomon his son, "In this house, and in Jerusalem, which I have chosen out of all the tribes of Israel, will I put my name forever:'),
  ('5f16853e-6d45-55c9-a08a-e7c159d8e8a9', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 8, 8, 'neither will I any more remove the foot of Israel from off the land which I have appointed for your fathers, if only they will observe to do all that I have commanded them, even all the law and the statutes and the ordinances given by Moses."'),
  ('f5fab89c-c3e2-5be3-aae6-c9f74ddf06d0', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 9, 9, 'Manasseh seduced Judah and the inhabitants of Jerusalem, so that they did evil more than did the nations whom Yahweh destroyed before the children of Israel.'),
  ('eb817864-2534-5630-a22a-9fad62f06a70', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 10, 10, 'Yahweh spoke to Manasseh, and to his people; but they gave no heed.'),
  ('dc051610-1dfe-5658-a90b-3069940e7ae0', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 11, 11, 'Therefore Yahweh brought on them the captains of the army of the king of Assyria, who took Manasseh in chains, and bound him with fetters, and carried him to Babylon.'),
  ('b513651d-77c6-5d9a-a510-cd5117c2f8e1', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 12, 12, 'When he was in distress, he begged Yahweh his God, and humbled himself greatly before the God of his fathers.'),
  ('c771606c-677a-5158-abcf-e805befb2872', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 13, 13, 'He prayed to him; and he was entreated by him, and heard his supplication, and brought him again to Jerusalem into his kingdom. Then Manasseh knew that Yahweh was God.'),
  ('d1d6b597-6223-5e1c-ac63-57020eff0b0c', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 14, 14, 'Now after this he built an outer wall to the city of David, on the west side of Gihon, in the valley, even to the entrance at the fish gate; and he encircled Ophel [with it], and raised it up to a very great height: and he put valiant captains in all the fortified cities of Judah.'),
  ('80c16462-27c2-59da-a109-54b2159d40bf', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 15, 15, 'He took away the foreign gods, and the idol out of the house of Yahweh, and all the altars that he had built in the mountain of the house of Yahweh, and in Jerusalem, and cast them out of the city.'),
  ('359a318e-ca20-59e1-a293-42feb9abfdae', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 16, 16, 'He built up the altar of Yahweh, and offered thereon sacrifices of peace offerings and of thanksgiving, and commanded Judah to serve Yahweh, the God of Israel.'),
  ('1b4742e8-5e35-531f-a890-507473b20147', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 17, 17, 'Nevertheless the people sacrificed still in the high places, but only to Yahweh their God.'),
  ('6976baad-1b77-5d1d-a57f-11d6db92ae65', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 18, 18, 'Now the rest of the acts of Manasseh, and his prayer to his God, and the words of the seers who spoke to him in the name of Yahweh, the God of Israel, behold, they are written among the acts of the kings of Israel.'),
  ('50d1c808-5597-52bd-a318-2993674673a0', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 19, 19, 'His prayer also, and how [God] was entreated of him, and all his sin and his trespass, and the places in which he built high places, and set up the Asherim and the engraved images, before he humbled himself: behold, they are written in the history of Hozai.'),
  ('cd7225e4-f449-5b53-a0f2-4d4589f189e6', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 20, 20, 'So Manasseh slept with his fathers, and they buried him in his own house: and Amon his son reigned in his place.'),
  ('3f5e13eb-ae3b-56c4-a813-254c10cc9136', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 21, 21, 'Amon was twenty-two years old when he began to reign; and he reigned two years in Jerusalem.'),
  ('a1e76f2d-fbc3-53d7-a822-3641a5cbf497', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 22, 22, 'He did that which was evil in the sight of Yahweh, as did Manasseh his father; and Amon sacrificed to all the engraved images which Manasseh his father had made, and served them.'),
  ('1eb6e9c2-46a2-50e1-a75c-40838248b8db', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 23, 23, 'He didn''t humble himself before Yahweh, as Manasseh his father had humbled himself; but this same Amon trespassed more and more.'),
  ('e5410df4-8b17-5544-adcf-a9a4ce18dd4a', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 24, 24, 'His servants conspired against him, and put him to death in his own house.'),
  ('e54a202f-c3fb-57ed-ad00-1098685b1753', 'f36a152e-aa78-5016-a802-5ce4354f5d8a', NULL, 25, 25, 'But the people of the land killed all those who had conspired against king Amon; and the people of the land made Josiah his son king in his place.'),
  ('dc9fcbe7-9e49-50ef-a78b-3e63ebd8d7bd', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 1, 1, 'Josiah was eight years old when he began to reign; and he reigned thirty-one years in Jerusalem.'),
  ('2fd9c5d5-9d64-5991-ad68-d99c030f3f4e', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 2, 2, 'He did that which was right in the eyes of Yahweh, and walked in the ways of David his father, and didn''t turn aside to the right hand or to the left.'),
  ('ed3ff296-6229-5938-a13a-9c16665317eb', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 3, 3, 'For in the eighth year of his reign, while he was yet young, he began to seek after the God of David his father; and in the twelfth year he began to purge Judah and Jerusalem from the high places, and the Asherim, and the engraved images, and the molten images.'),
  ('af0de8e8-ac46-5f38-a911-915c457a6d2a', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 4, 4, 'They broke down the altars of the Baals in his presence; and the incense altars that were on high above them he cut down; and the Asherim, and the engraved images, and the molten images, he broke in pieces, and made dust of them, and strewed it on the graves [of those] who had sacrificed to them.'),
  ('fe10015c-471b-56ec-ab7d-28b0b5a55d94', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 5, 5, 'He burnt the bones of the priests on their altars, and purged Judah and Jerusalem.'),
  ('68c09655-d92c-5938-a296-1fe2184f5b44', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 6, 6, '[So did he] in the cities of Manasseh and Ephraim and Simeon, even to Naphtali, around in their ruins.'),
  ('da42dd5a-8e75-53de-ab8a-c8d8e9066a1b', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 7, 7, 'He broke down the altars, and beat the Asherim and the engraved images into powder, and cut down all the incense altars throughout all the land of Israel, and returned to Jerusalem.'),
  ('87401e4d-0174-52f7-a49a-3cad6bbb3e3c', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 8, 8, 'Now in the eighteenth year of his reign, when he had purged the land and the house, he sent Shaphan the son of Azaliah, and Maaseiah the governor of the city, and Joah the son of Joahaz the recorder, to repair the house of Yahweh his God.'),
  ('325187c5-c925-5d9f-abaa-56dd5f6bada1', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 9, 9, 'They came to Hilkiah the high priest, and delivered the money that was brought into the house of God, which the Levites, the keepers of the threshold, had gathered of the hand of Manasseh and Ephraim, and of all the remnant of Israel, and of all Judah and Benjamin, and of the inhabitants of Jerusalem.'),
  ('f550960a-ca2b-52e4-aba3-ca662604d5b3', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 10, 10, 'They delivered it into the hand of the workmen who had the oversight of the house of Yahweh; and the workmen who labored in the house of Yahweh gave it to mend and repair the house;'),
  ('eba8015a-4f8b-5620-a132-99b6111e2d4f', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 11, 11, 'even to the carpenters and to the builders gave they it, to buy cut stone, and timber for couplings, and to make beams for the houses which the kings of Judah had destroyed.'),
  ('6b62c949-0330-502d-adbd-ef9c5d6ce182', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 12, 12, 'The men did the work faithfully: and the overseers of them were Jahath and Obadiah, the Levites, of the sons of Merari; and Zechariah and Meshullam, of the sons of the Kohathites, to set it forward; and [others of] the Levites, all who were skillful with instruments of music.'),
  ('be635eaf-beaa-5705-aa1a-a576be11c192', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 13, 13, 'Also they were over the bearers of burdens, and set forward all who did the work in every kind of service: and of the Levites there were scribes, and officers, and porters.'),
  ('3314f22e-2dbc-52ea-a3c9-3257dd443873', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 14, 14, 'When they brought out the money that was brought into the house of Yahweh, Hilkiah the priest found the book of the law of Yahweh [given] by Moses.'),
  ('56a3939c-a12c-58c3-a4fa-94fff72c4b8a', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 15, 15, 'Hilkiah answered Shaphan the scribe, "I have found the book of the law in the house of Yahweh." Hilkiah delivered the book to Shaphan.'),
  ('8d0a42e9-56e7-5599-ab85-245ae044aab5', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 16, 16, 'Shaphan carried the book to the king, and moreover brought back word to the king, saying, "All that was committed to your servants, they are doing.'),
  ('4399f809-cdae-5e35-a528-00782c2fb254', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 17, 17, 'They have emptied out the money that was found in the house of Yahweh, and have delivered it into the hand of the overseers, and into the hand of the workmen."'),
  ('c561c428-462d-5994-a253-526f165322ea', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 18, 18, 'Shaphan the scribe told the king, saying, "Hilkiah the priest has delivered me a book." Shaphan read therein before the king.'),
  ('72e6ba4f-2488-583e-a88c-614e9cfff94a', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 19, 19, 'It happened, when the king had heard the words of the law, that he tore his clothes.'),
  ('652482d4-12dd-5d96-accd-2e70bc87346f', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 20, 20, 'The king commanded Hilkiah, and Ahikam the son of Shaphan, and Abdon the son of Micah, and Shaphan the scribe, and Asaiah the king''s servant, saying,'),
  ('351d25d4-c833-5aff-a118-151f1fb3ce63', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 21, 21, '"Go inquire of Yahweh for me, and for those who are left in Israel and in Judah, concerning the words of the book that is found; for great is the wrath of Yahweh that is poured out on us, because our fathers have not kept the word of Yahweh, to do according to all that is written in this book."'),
  ('de09ac73-a56a-5754-add4-cc90d6737f78', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 22, 22, 'So Hilkiah, and they whom the king [had commanded], went to Huldah the prophetess, the wife of Shallum the son of Tokhath, the son of Hasrah, keeper of the wardrobe; (now she lived in Jerusalem in the second quarter;) and they spoke to her to that effect.'),
  ('bb4e9bab-26f8-506f-a48b-ec4a21f8ec0d', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 23, 23, 'She said to them, "Thus says Yahweh, the God of Israel: ''Tell the man who sent you to me,'),
  ('ac943d2c-bb47-5d64-ac5e-4298c5f4ad73', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 24, 24, '"Thus says Yahweh, ''Behold, I will bring evil on this place, and on its inhabitants, even all the curses that are written in the book which they have read before the king of Judah.'),
  ('1fac4c3d-e374-5649-af18-3db0fc4cd39e', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 25, 25, 'Because they have forsaken me, and have burned incense to other gods, that they might provoke me to anger with all the works of their hands; therefore is my wrath poured out on this place, and it shall not be quenched.''"'''),
  ('792cb400-1fd9-5519-a2fd-a1b0f4d85474', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 26, 26, 'But to the king of Judah, who sent you to inquire of Yahweh, thus you shall tell him, ''Thus says Yahweh, the God of Israel: "As touching the words which you have heard,'),
  ('a034208e-23be-5e71-aca2-4e6b378c1670', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 27, 27, 'because your heart was tender, and you humbled yourself before God, when you heard his words against this place, and against its inhabitants, and have humbled yourself before me, and have torn your clothes, and wept before me; I also have heard you," says Yahweh.'),
  ('0d361f9b-b399-536c-a58e-7e75264a45b7', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 28, 28, '"Behold, I will gather you to your fathers, and you shall be gathered to your grave in peace, neither shall your eyes see all the evil that I will bring on this place, and on its inhabitants."''" They brought back word to the king.'),
  ('b96bd334-2d65-55bb-aa3f-815c65617479', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 29, 29, 'Then the king sent and gathered together all the elders of Judah and Jerusalem.'),
  ('74a6f8cd-154b-59ce-a92a-c36537d5e7a6', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 30, 30, 'The king went up to the house of Yahweh, and all the men of Judah and the inhabitants of Jerusalem, and the priests, and the Levites, and all the people, both great and small: and he read in their ears all the words of the book of the covenant that was found in the house of Yahweh.'),
  ('4a9448d9-62b7-52e8-a4af-81e5b648d9c6', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 31, 31, 'The king stood in his place, and made a covenant before Yahweh, to walk after Yahweh, and to keep his commandments, and his testimonies, and his statutes, with all his heart, and with all his soul, to perform the words of the covenant that were written in this book.'),
  ('85b1b0e4-a93f-588c-a541-37edcfdf9062', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 32, 32, 'He caused all who were found in Jerusalem and Benjamin to stand [to it]. The inhabitants of Jerusalem did according to the covenant of God, the God of their fathers.'),
  ('c9f59247-d036-5cb4-ac2d-24eb16e607b2', '2bc97ec7-4b44-5325-a995-69874c2cfab7', NULL, 33, 33, 'Josiah took away all the abominations out of all the countries that pertained to the children of Israel, and made all who were found in Israel to serve, even to serve Yahweh their God. All his days they didn''t depart from following Yahweh, the God of their fathers.'),
  ('657badd9-8fa4-5902-a2f5-cd509ffea822', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 1, 1, 'Josiah kept a Passover to Yahweh in Jerusalem: and they killed the Passover on the fourteenth [day] of the first month.'),
  ('793fd41c-46f8-5c75-a45f-de548371ca56', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 2, 2, 'He set the priests in their offices, and encouraged them to the service of the house of Yahweh.'),
  ('28ce6ceb-ccfd-55cb-ae59-9cf251ab6e5a', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 3, 3, 'He said to the Levites who taught all Israel, who were holy to Yahweh, "Put the holy ark in the house which Solomon the son of David king of Israel built. There shall no more be a burden on your shoulders. Now serve Yahweh your God, and his people Israel.'),
  ('6477f9c6-d3d5-580a-aa27-3cb1ec820a97', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 4, 4, 'Prepare yourselves after your fathers'' houses by your divisions, according to the writing of David king of Israel, and according to the writing of Solomon his son.'),
  ('3698bc4e-b8ca-514e-a044-5bae1032a8bf', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 5, 5, 'Stand in the holy place according to the divisions of the fathers'' houses of your brothers the children of the people, and [let there be for each] a portion of a fathers'' house of the Levites.'),
  ('8ee68777-4522-5ecd-a3bd-45af1feb607c', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 6, 6, 'Kill the Passover, and sanctify yourselves, and prepare for your brothers, to do according to the word of Yahweh by Moses."'),
  ('2cf0bff7-9ab8-59fc-a682-5eea9c18bc34', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 7, 7, 'Josiah gave to the children of the people, of the flock, lambs and young goats, all of them for the Passover offerings, to all who were present, to the number of thirty thousand, and three thousand bulls: these were of the king''s substance.'),
  ('8a0c3c0a-d04d-5169-a8d6-d2d774235371', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 8, 8, 'His princes gave for a freewill offering to the people, to the priests, and to the Levites. Hilkiah and Zechariah and Jehiel, the rulers of the house of God, gave to the priests for the Passover offerings two thousand and six hundred [small livestock], and three hundred head of cattle.'),
  ('fe709d9c-eef6-5668-a6de-d35b80db4c41', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 9, 9, 'Conaniah also, and Shemaiah and Nethanel, his brothers, and Hashabiah and Jeiel and Jozabad, the chiefs of the Levites, gave to the Levites for the Passover offerings five thousand [small livestock], and five hundred head of cattle.'),
  ('23c1af63-2c47-582d-afeb-15c16f382300', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 10, 10, 'So the service was prepared, and the priests stood in their place, and the Levites by their divisions, according to the king''s commandment.'),
  ('5991836c-9feb-5779-a70d-f0c7fca0c0fc', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 11, 11, 'They killed the Passover, and the priests sprinkled [the blood which they received] of their hand, and the Levites flayed them.'),
  ('54bed567-2811-54bb-accc-39600e74db7e', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 12, 12, 'They removed the burnt offerings, that they might give them according to the divisions of the fathers'' houses of the children of the people, to offer to Yahweh, as it is written in the book of Moses. So did they with the cattle.'),
  ('2f09770e-4faa-56cf-acc5-ab7a77458eac', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 13, 13, 'They roasted the Passover with fire according to the ordinance: and the holy offerings boiled they in pots, and in caldrons, and in pans, and carried them quickly to all the children of the people.'),
  ('60a26892-2dbc-5bc5-ad24-f14ee67812fa', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 14, 14, 'Afterward they prepared for themselves, and for the priests, because the priests the sons of Aaron [were busied] in offering the burnt offerings and the fat until night: therefore the Levites prepared for themselves, and for the priests the sons of Aaron.'),
  ('1eb9eaa0-a6f2-577a-a8d1-019e0861130a', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 15, 15, 'The singers the sons of Asaph were in their place, according to the commandment of David, and Asaph, and Heman, and Jeduthun the king''s seer; and the porters were at every gate: they didn''t need to depart from their service; for their brothers the Levites prepared for them.'),
  ('16ffffb3-8692-5636-a9cf-4715245cca5c', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 16, 16, 'So all the service of Yahweh was prepared the same day, to keep the Passover, and to offer burnt offerings on the altar of Yahweh, according to the commandment of king Josiah.'),
  ('402d4278-42c3-5696-a6d9-92f3f6335573', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 17, 17, 'The children of Israel who were present kept the Passover at that time, and the feast of unleavened bread seven days.'),
  ('5b327f15-39aa-597f-a806-ec5a85ac4514', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 18, 18, 'There was no Passover like that kept in Israel from the days of Samuel the prophet; neither did any of the kings of Israel keep such a Passover as Josiah kept, and the priests, and the Levites, and all Judah and Israel who were present, and the inhabitants of Jerusalem.'),
  ('f258a924-84ff-51ba-a7ce-005cd7b28eb9', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 19, 19, 'In the eighteenth year of the reign of Josiah was this Passover kept.'),
  ('782083ef-ad9c-5eb6-a029-29d4b6dc3265', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 20, 20, 'After all this, when Josiah had prepared the temple, Neco king of Egypt went up to fight against Carchemish by the Euphrates: and Josiah went out against him.'),
  ('f0e4d344-2829-55c5-afa7-14018e9c5d22', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 21, 21, 'But he sent ambassadors to him, saying, "What have I to do with you, you king of Judah? I come not against you this day, but against the house with which I have war. God has commanded me to make haste. Beware that it is God who is with me, that he not destroy you."'),
  ('211d7fe4-87a2-5eda-afc1-214eb82cbaa9', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 22, 22, 'Nevertheless Josiah would not turn his face from him, but disguised himself, that he might fight with him, and didn''t listen to the words of Neco from the mouth of God, and came to fight in the valley of Megiddo.'),
  ('83a713e3-bc91-5847-a670-a74ca8868857', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 23, 23, 'The archers shot at king Josiah; and the king said to his servants, "Take me away, because I am seriously wounded!"'),
  ('fc9bb57c-b6d3-5bdb-a989-b550b8cf03e0', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 24, 24, 'So his servants took him out of the chariot, and put him in the second chariot that he had, and brought him to Jerusalem; and he died, and was buried in the tombs of his fathers. All Judah and Jerusalem mourned for Josiah.'),
  ('f54acc43-f41f-5180-a331-318acf36f850', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 25, 25, 'Jeremiah lamented for Josiah: and all the singing men and singing women spoke of Josiah in their lamentations to this day; and they made them an ordinance in Israel: and behold, they are written in the lamentations.'),
  ('aee0a6fa-ac89-55ac-a626-829caa891b0f', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 26, 26, 'Now the rest of the acts of Josiah, and his good deeds, according to that which is written in the law of Yahweh,'),
  ('39df1a1a-59f6-5e47-a3a8-d97be5fa0aae', '63df34d2-a4d9-5bf5-a3e7-a6986c484434', NULL, 27, 27, 'and his acts, first and last, behold, they are written in the book of the kings of Israel and Judah.'),
  ('f4c2dc17-3028-596a-a2d0-bf4d54a621a4', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 1, 1, 'Then the people of the land took Jehoahaz the son of Josiah, and made him king in his father''s place in Jerusalem.'),
  ('7a33177a-93af-5542-acc8-b5e483e9771f', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 2, 2, 'Joahaz was twenty-three years old when he began to reign; and he reigned three months in Jerusalem.'),
  ('23d2cac9-419b-5016-a781-e20056604517', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 3, 3, 'The king of Egypt deposed him at Jerusalem, and fined the land one hundred talents of silver and a talent of gold.'),
  ('4b601c24-ce4e-5e40-a5bf-4eb9d0adab2f', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 4, 4, 'The king of Egypt made Eliakim his brother king over Judah and Jerusalem, and changed his name to Jehoiakim. Neco took Joahaz his brother, and carried him to Egypt.'),
  ('9cced238-0552-5091-aa0c-2611b0452ebf', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 5, 5, 'Jehoiakim was Twenty-five years old when he began to reign; and he reigned eleven years in Jerusalem: and he did that which was evil in the sight of Yahweh his God.'),
  ('ac8ba27a-c1ab-528b-a505-06cc82daeda2', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 6, 6, 'Against him came up Nebuchadnezzar king of Babylon, and bound him in fetters, to carry him to Babylon.'),
  ('91adddd6-2bd0-586f-af0c-7e951761112f', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 7, 7, 'Nebuchadnezzar also carried of the vessels of the house of Yahweh to Babylon, and put them in his temple at Babylon.'),
  ('a3e9f1c6-64c4-5ada-aff3-980a5aa70b06', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 8, 8, 'Now the rest of the acts of Jehoiakim, and his abominations which he did, and that which was found in him, behold, they are written in the book of the kings of Israel and Judah: and Jehoiachin his son reigned in his place.'),
  ('de4d1942-766b-5b71-a9c1-1d6e6a274245', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 9, 9, 'Jehoiachin was eight years old when he began to reign; and he reigned three months and ten days in Jerusalem: and he did that which was evil in the sight of Yahweh.'),
  ('1533b1d7-fdfc-55bb-ae8f-07125911c5bd', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 10, 10, 'At the return of the year king Nebuchadnezzar sent, and brought him to Babylon, with the goodly vessels of the house of Yahweh, and made Zedekiah his brother king over Judah and Jerusalem.'),
  ('7242ea25-f75e-5aef-ab55-86854753ef5c', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 11, 11, 'Zedekiah was twenty-one years old when he began to reign; and he reigned eleven years in Jerusalem:'),
  ('04d41845-8b3c-50ea-a14d-840f198dda1a', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 12, 12, 'and he did that which was evil in the sight of Yahweh his God; he didn''t humble himself before Jeremiah the prophet [speaking] from the mouth of Yahweh.'),
  ('0bd1d039-a998-5cb8-a711-681e1a359112', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 13, 13, 'He also rebelled against king Nebuchadnezzar, who had made him swear by God: but he stiffened his neck, and hardened his heart against turning to Yahweh, the God of Israel.'),
  ('c7643257-540b-54e1-aa67-4d3d9e731531', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 14, 14, 'Moreover all the chiefs of the priests, and the people, trespassed very greatly after all the abominations of the nations; and they polluted the house of Yahweh which he had made holy in Jerusalem.'),
  ('1b628606-bf77-5d5d-a666-fccfb9e084bb', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 15, 15, 'Yahweh, the God of their fathers, sent to them by his messengers, rising up early and sending, because he had compassion on his people, and on his dwelling place:'),
  ('03a7c7ef-3a18-5ffe-ac64-786383fc3e34', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 16, 16, 'but they mocked the messengers of God, and despised his words, and scoffed at his prophets, until the wrath of Yahweh arose against his people, until there was no remedy.'),
  ('b6383433-4e0b-59f0-aa6d-a5fcc6e099d1', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 17, 17, 'Therefore he brought on them the king of the Chaldeans, who killed their young men with the sword in the house of their sanctuary, and had no compassion on young man or virgin, old man or gray-headed: he gave them all into his hand.'),
  ('c5aaf4d8-c245-5939-afae-df7b0d680796', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 18, 18, 'All the vessels of the house of God, great and small, and the treasures of the house of Yahweh, and the treasures of the king, and of his princes, all these he brought to Babylon.'),
  ('578f8fac-1026-5b8c-a076-74d280eaff38', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 19, 19, 'They burnt the house of God, and broke down the wall of Jerusalem, and burnt all its palaces with fire, and destroyed all the goodly vessels of it.'),
  ('e10839d6-e45e-5729-a044-6257cef8fa39', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 20, 20, 'He carried those who had escaped from the sword away to Babylon; and they were servants to him and his sons until the reign of the kingdom of Persia:'),
  ('bfba3828-0302-5c8a-a271-fdf49eaf1162', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 21, 21, 'to fulfill the word of Yahweh by the mouth of Jeremiah, until the land had enjoyed its Sabbaths: [for] as long as it lay desolate it kept Sabbath, to fulfill seventy years.'),
  ('6face1ee-fe72-5e2c-afd2-27c2a772be7c', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 22, 22, 'Now in the first year of Cyrus king of Persia, that the word of Yahweh by the mouth of Jeremiah might be accomplished, Yahweh stirred up the spirit of Cyrus king of Persia, so that he made a proclamation throughout all his kingdom, and [put it] also in writing, saying,'),
  ('72267616-dffd-5ac7-a388-3dfb3e4b1bd5', '274ac00c-fc32-53b5-a797-47e3490e3626', NULL, 23, 23, '"Thus says Cyrus king of Persia, ''Yahweh, the God of heaven, has given all the kingdoms of the earth to me; and he has commanded me to build him a house in Jerusalem, which is in Judah. Whoever there is among you of all his people, Yahweh his God be with him, and let him go up.''"'),
  ('ebf49b0d-ae4e-59dd-a36b-6834af0388cd', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 1, 1, 'Now in the first year of Cyrus king of Persia, that the word of Yahweh by the mouth of Jeremiah might be accomplished, Yahweh stirred up the spirit of Cyrus king of Persia, so that he made a proclamation throughout all his kingdom, and [put it] also in writing, saying,'),
  ('2a89d48b-5a32-572c-a3b5-5a958ff76c25', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 2, 2, '"Thus says Cyrus king of Persia, ''Yahweh, the God of heaven, has given me all the kingdoms of the earth; and he has commanded me to build him a house in Jerusalem, which is in Judah.'),
  ('7ce59891-9e61-5b93-abb4-eb789cea8c00', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 3, 3, 'Whoever there is among you of all his people, may his God be with him, and let him go up to Jerusalem, which is in Judah, and build the house of Yahweh, the God of Israel (he is God), which is in Jerusalem.'),
  ('63fa217e-4df3-5fee-a9f6-c0ebc1e4c676', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 4, 4, 'Whoever is left, in any place where he lives, let the men of his place help him with silver, with gold, with goods, and with animals, besides the freewill offering for the house of God which is in Jerusalem.''"'),
  ('9356c24a-998a-5e3c-a558-bbe98fe854c1', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 5, 5, 'Then the heads of fathers'' [houses] of Judah and Benjamin, and the priests, and the Levites, even all whose spirit God had stirred to go up rose up to build the house of Yahweh which is in Jerusalem.'),
  ('db8501f9-f9a3-5785-a78b-9519f5e7d96d', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 6, 6, 'All those who were around them strengthened their hands with vessels of silver, with gold, with goods, and with animals, and with precious things, besides all that was willingly offered.'),
  ('4e05b2c9-c277-511a-a8ba-e1508bd31ef6', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 7, 7, 'Also Cyrus the king brought forth the vessels of the house of Yahweh, which Nebuchadnezzar had brought forth out of Jerusalem, and had put in the house of his gods;'),
  ('692a9096-0fa7-5508-a53f-12d74fb96f54', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 8, 8, 'even those did Cyrus king of Persia bring forth by the hand of Mithredath the treasurer, and numbered them to Sheshbazzar, the prince of Judah.'),
  ('3127623a-4d68-5655-ae6f-809b6681d3e2', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 9, 9, 'This is the number of them: thirty platters of gold, one thousand platters of silver, twenty-nine knives,'),
  ('eee5aa72-117a-5d8f-abd3-f9c09e4e0b58', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 10, 10, 'thirty bowls of gold, silver bowls of a second sort four hundred and ten, and other vessels one thousand.'),
  ('9e4cd8aa-3a48-59fa-ab02-e1d4f905f76b', 'a3b2320f-9c51-5b6d-a465-dd3d86728cbb', NULL, 11, 11, 'All the vessels of gold and of silver were five thousand and four hundred. All these did Sheshbazzar bring up, when they of the captivity were brought up from Babylon to Jerusalem.'),
  ('70d8c423-3a09-583e-ae20-f7e423ba2ee5', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 1, 1, 'Now these are the children of the province, who went up out of the captivity of those who had been carried away, whom Nebuchadnezzar the king of Babylon had carried away to Babylon, and who returned to Jerusalem and Judah, everyone to his city;'),
  ('60a8f3e5-1b1f-5923-a09d-48a40a85f1ce', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 2, 2, 'who came with Zerubbabel, Jeshua, Nehemiah, Seraiah, Reelaiah, Mordecai, Bilshan, Mispar, Bigvai, Rehum, Baanah. The number of the men of the people of Israel:'),
  ('f6f5df38-33d9-58e3-ac1b-53d49468779a', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 3, 3, 'The children of Parosh, two thousand one hundred seventy-two.'),
  ('234d5aba-0e82-5061-a053-20306263fc20', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 4, 4, 'The children of Shephatiah, three hundred seventy-two.'),
  ('61a3af23-e5b6-5926-a10a-863e1b9b672c', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 5, 5, 'The children of Arah, seven hundred seventy-five.'),
  ('0e65b676-c553-555c-af79-4338187ec3b8', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 6, 6, 'The children of Pahathmoab, of the children of Jeshua [and] Joab, two thousand eight hundred twelve.'),
  ('95e1d06d-dd18-51cd-a4e9-6a64147f2353', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 7, 7, 'The children of Elam, one thousand two hundred fifty-four.'),
  ('52eefb08-24f3-54b2-a559-cb77a1f54b6c', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 8, 8, 'The children of Zattu, nine hundred forty-five.'),
  ('1d7f7eb6-280b-5925-a1e3-726deebe255d', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 9, 9, 'The children of Zaccai, seven hundred sixty.'),
  ('cb7ee5d7-b70a-57a6-a3fb-065cfbb45cc0', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 10, 10, 'The children of Bani, six hundred forty-two.'),
  ('6eef3038-ba2c-52e8-a7ef-ca5f60284f6c', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 11, 11, 'The children of Bebai, six hundred twenty-three.'),
  ('f2ecd5b9-62d4-5e4f-ad8d-3c3324343a11', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 12, 12, 'The children of Azgad, one thousand two hundred twenty-two.'),
  ('2f1ccafb-5d91-586e-a551-536954e343af', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 13, 13, 'The children of Adonikam, six hundred sixty-six.'),
  ('813758db-3ed8-5179-a2c3-af6006ee3b89', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 14, 14, 'The children of Bigvai, two thousand fifty-six.'),
  ('74ca0124-58f5-5dbe-a06a-6bf7d64f40a8', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 15, 15, 'The children of Adin, four hundred fifty-four.'),
  ('9dbf026b-b719-57e2-a141-33041d1f9823', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 16, 16, 'The children of Ater, of Hezekiah, ninety-eight.'),
  ('18ce5a79-b4ee-5e59-aafd-e8b8cbd3239a', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 17, 17, 'The children of Bezai, three hundred twenty-three.'),
  ('f377e17e-e797-5db8-a70e-c7831a0c9d89', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 18, 18, 'The children of Jorah, one hundred twelve.'),
  ('18adbe4b-1d03-5711-a441-97985b6ecac1', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 19, 19, 'The children of Hashum, two hundred Twenty-three.'),
  ('248d5372-7169-5bcd-a285-09cb7a502c3b', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 20, 20, 'The children of Gibbar, ninety-five.'),
  ('b579130d-f4ae-57c5-a6f3-aee249d5fed2', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 21, 21, 'The children of Bethlehem, one hundred twenty-three.'),
  ('bb072b6f-29a2-5f7d-ae27-81dd87ecb220', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 22, 22, 'The men of Netophah, fifty-six.'),
  ('98482011-85ad-5285-a231-fa2c59d6f1f0', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 23, 23, 'The men of Anathoth, one hundred twenty-eight.'),
  ('4ab27ecf-a6a9-50b7-af95-e8875b89f928', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 24, 24, 'The children of Azmaveth, forty-two.'),
  ('835a0828-e539-5751-a098-91f7aac513c5', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 25, 25, 'The children of Kiriath Arim, Chephirah, and Beeroth, seven hundred forty-three.'),
  ('943dbb61-45a2-554a-a273-8d81ba36bd88', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 26, 26, 'The children of Ramah and Geba, six hundred twenty-one.'),
  ('84860b27-cd29-5433-a039-9a8320d16ff4', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 27, 27, 'The men of Michmas, one hundred twenty-two.'),
  ('b527d15e-5aa1-54b1-a2ad-ac3331f3b55f', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 28, 28, 'The men of Bethel and Ai, two hundred twenty-three.'),
  ('01e1412e-74fb-5f9c-a0a1-d87bd33b6bb7', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 29, 29, 'The children of Nebo, fifty-two.'),
  ('c711ca87-0607-557c-a059-5b1a691ef363', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 30, 30, 'The children of Magbish, one hundred fifty-six.'),
  ('d6986e95-d731-53c2-ac9d-fa464537ee03', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 31, 31, 'The children of the other Elam, one thousand two hundred fifty-four.'),
  ('f77cc56e-a9ac-524d-ab10-756c6978f16b', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 32, 32, 'The children of Harim, three hundred twenty.'),
  ('53aaa039-e44f-5735-a492-886e974d39ff', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 33, 33, 'The children of Lod, Hadid, and Ono, seven hundred twenty-five.'),
  ('99fa3cdd-0656-5c5d-a209-54b97d704101', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 34, 34, 'The children of Jericho, three hundred forty-five.'),
  ('19578c0b-4c2e-502f-aced-a0d5cb63bfc4', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 35, 35, 'The children of Senaah, three thousand six hundred thirty.'),
  ('f71f0e57-74c1-5d07-aff8-7d14985c61ea', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 36, 36, 'The priests: the children of Jedaiah, of the house of Jeshua, nine hundred seventy-three.'),
  ('f99d6b5d-37d4-508e-a506-8017cafa9524', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 37, 37, 'The children of Immer, one thousand fifty-two.'),
  ('4e5b8b7b-a751-59e2-a723-4ea1a6fdaf34', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 38, 38, 'The children of Pashhur, one thousand two hundred forty-seven.'),
  ('d4accca5-a75d-5f03-a70c-250a01246ea0', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 39, 39, 'The children of Harim, one thousand seventeen.'),
  ('b8414bfe-db20-554c-a114-c41ceb6e2036', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 40, 40, 'The Levites: the children of Jeshua and Kadmiel, of the children of Hodaviah, seventy-four.'),
  ('08c855b9-a8c1-5a8a-a741-2a77dead8481', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 41, 41, 'The singers: the children of Asaph, one hundred twenty-eight.'),
  ('950a193a-12fe-5e7e-a0bb-dc73895eec5a', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 42, 42, 'The children of the porters: the children of Shallum, the children of Ater, the children of Talmon, the children of Akkub, the children of Hatita, the children of Shobai, in all one hundred thirty-nine.'),
  ('ae272555-44a2-5f24-a44f-9ba858398616', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 43, 43, 'The Nethinim: the children of Ziha, the children of Hasupha, the children of Tabbaoth,'),
  ('2991a1fe-bba9-5ac2-aa92-02f4e9a4adbc', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 44, 44, 'the children of Keros, the children of Siaha, the children of Padon,'),
  ('d7bbbbb5-af5b-5af2-a631-2cbd5160bb90', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 45, 45, 'the children of Lebanah, the children of Hagabah, the children of Akkub,'),
  ('0180183f-70cd-5f29-a058-b1badf28f69b', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 46, 46, 'the children of Hagab, the children of Shamlai, the children of Hanan,'),
  ('3b981969-6d22-5af1-aef1-45ef059b288e', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 47, 47, 'the children of Giddel, the children of Gahar, the children of Reaiah,'),
  ('d7477fa5-7fa6-5d9a-a7ed-38b8425c5697', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 48, 48, 'the children of Rezin, the children of Nekoda, the children of Gazzam,'),
  ('1ce6bcea-09f6-5ebb-a243-9e002e350df6', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 49, 49, 'the children of Uzza, the children of Paseah, the children of Besai,'),
  ('c754ea29-34f2-566a-aee3-0c36d3a1ec14', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 50, 50, 'the children of Asnah, the children of Meunim, the children of Nephisim,'),
  ('9fa2b6cb-942f-5f6a-ac15-5085dbf0a0ee', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 51, 51, 'the children of Bakbuk, the children of Hakupha, the children of Harhur,'),
  ('6052be46-5b8f-5608-a7c3-c0cc58eda96b', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 52, 52, 'the children of Bazluth, the children of Mehida, the children of Harsha,'),
  ('e4782950-a955-5495-a358-9b51d1e21c56', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 53, 53, 'the children of Barkos, the children of Sisera, the children of Temah,'),
  ('12a9e836-5d5b-53c4-aa4a-d2712737ddf4', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 54, 54, 'the children of Neziah, the children of Hatipha.'),
  ('31227d38-2005-5481-a26b-445167f122d6', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 55, 55, 'The children of Solomon''s servants: the children of Sotai, the children of Hassophereth, the children of Peruda,'),
  ('4dda5e64-5c18-55ca-afa7-5d8bcaf88a36', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 56, 56, 'the children of Jaalah, the children of Darkon, the children of Giddel,'),
  ('c7659e88-a74b-5b77-a568-88bc8add4965', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 57, 57, 'the children of Shephatiah, the children of Hattil, the children of Pochereth Hazzebaim, the children of Ami.'),
  ('e34bbd84-2e5d-55a0-a636-17d14d0e811c', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 58, 58, 'All the Nethinim, and the children of Solomon''s servants, were three hundred ninety-two.'),
  ('60a048e2-5694-5e65-a0a8-c29781bfbdd1', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 59, 59, 'These were those who went up from Tel Melah, Tel Harsha, Cherub, Addan, [and] Immer; but they could not show their fathers'' houses, and their seed, whether they were of Israel:'),
  ('caee1e95-a1f3-5966-a36d-0909988e4052', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 60, 60, 'the children of Delaiah, the children of Tobiah, the children of Nekoda, six hundred fifty-two.'),
  ('8a32798a-5dc7-5f86-adf8-e97fba96cea9', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 61, 61, 'Of the children of the priests: the children of Habaiah, the children of Hakkoz, the children of Barzillai, who took a wife of the daughters of Barzillai the Gileadite, and was called after their name.'),
  ('33c5a7ea-0eb4-501f-aecb-a61160a6083d', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 62, 62, 'These sought their register [among] those who were reckoned by genealogy, but they were not found: therefore were they deemed polluted and put from the priesthood.'),
  ('68fd5a05-b8a9-5a8e-a638-78c03e9d5e51', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 63, 63, 'The governor said to them, that they should not eat of the most holy things, until there stood up a priest with Urim and with Thummim.'),
  ('4006d8b4-cb53-50ac-afe3-658803496eae', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 64, 64, 'The whole assembly together was forty-two thousand three hundred sixty,'),
  ('02bc0fe4-4f4c-5f06-ad2a-99db9ce53a9d', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 65, 65, 'besides their male servants and their female servants, of whom there were seven thousand three hundred thirty-seven: and they had two hundred singing men and singing women.'),
  ('f9604cdf-2723-5fa3-ac7a-a79680595672', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 66, 66, 'Their horses were seven hundred thirty-six; their mules, two hundred forty-five;'),
  ('8b085501-66f4-518b-a006-4277ffd5b077', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 67, 67, 'their camels, four hundred thirty-five; [their] donkeys, six thousand seven hundred and twenty.'),
  ('36855940-b9ed-5cb5-a7ba-6621d7615205', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 68, 68, 'Some of the heads of fathers'' [houses], when they came to the house of Yahweh which is in Jerusalem, offered willingly for the house of God to set it up in its place:'),
  ('348bf5dd-4c92-51a1-acda-fbbd912e8ed2', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 69, 69, 'they gave after their ability into the treasury of the work sixty-one thousand darics of gold, and five thousand minas of silver, and one hundred priests'' garments.'),
  ('74a08f11-e51a-5053-a526-b02386520360', '5b857ba7-51cb-5870-adc2-2d09aa192d2b', NULL, 70, 70, 'So the priests, and the Levites, and some of the people, and the singers, and the porters, and the Nethinim, lived in their cities, and all Israel in their cities.'),
  ('50cfe966-7d3d-51f5-a009-5124842c3998', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 1, 1, 'When the seventh month was come, and the children of Israel were in the cities, the people gathered themselves together as one man to Jerusalem.'),
  ('da68b327-f969-548b-aac6-74642e2aa659', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 2, 2, 'Then stood up Jeshua the son of Jozadak, and his brothers the priests, and Zerubbabel the son of Shealtiel, and his brothers, and built the altar of the God of Israel, to offer burnt offerings thereon, as it is written in the law of Moses the man of God.'),
  ('466a9a9f-2661-5f40-a65d-d5a988fe6302', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 3, 3, 'They set the altar on its base; for fear was on them because of the peoples of the countries: and they offered burnt offerings thereon to Yahweh, even burnt offerings morning and evening.'),
  ('114beaad-048b-51d0-abe3-05498113a291', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 4, 4, 'They kept the feast of tents, as it is written, and [offered] the daily burnt offerings by number, according to the ordinance, as the duty of every day required;'),
  ('57227503-ae76-580d-aa2c-d82f90449401', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 5, 5, 'and afterward the continual burnt offering, and [the offerings] of the new moons, and of all the set feasts of Yahweh that were consecrated, and of everyone who willingly offered a freewill offering to Yahweh.'),
  ('5e466343-09e3-58c1-a35d-488de4003cc4', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 6, 6, 'From the first day of the seventh month began they to offer burnt offerings to Yahweh: but the foundation of the temple of Yahweh was not yet laid.'),
  ('fb013f23-2b24-5afd-a45f-76ae4a291b2d', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 7, 7, 'They gave money also to the masons, and to the carpenters; and food, and drink, and oil, to them of Sidon, and to them of Tyre, to bring cedar trees from Lebanon to the sea, to Joppa, according to the grant that they had of Cyrus king of Persia.'),
  ('06f1d9ac-94bb-5cb1-af36-603884e3b7ec', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 8, 8, 'Now in the second year of their coming to the house of God at Jerusalem, in the second month, began Zerubbabel the son of Shealtiel, and Jeshua the son of Jozadak, and the rest of their brothers the priests and the Levites, and all those who were come out of the captivity to Jerusalem, and appointed the Levites, from twenty years old and upward, to have the oversight of the work of the house of Yahweh.'),
  ('a2808342-cee7-5158-ab91-ed780988cd89', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 9, 9, 'Then stood Jeshua with his sons and his brothers, Kadmiel and his sons, the sons of Judah, together, to have the oversight of the workmen in the house of God: the sons of Henadad, with their sons and their brothers the Levites.'),
  ('08e533ce-29aa-55fc-acb4-e10630d5e56c', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 10, 10, 'When the builders laid the foundation of the temple of Yahweh, they set the priests in their clothing with trumpets, and the Levites the sons of Asaph with cymbals, to praise Yahweh, after the order of David king of Israel.'),
  ('a24bb940-46ec-5eee-aefc-c9b96f21c688', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 11, 11, 'They sang one to another in praising and giving thanks to Yahweh, "For he is good, for his loving kindness endures forever toward Israel." All the people shouted with a great shout, when they praised Yahweh, because the foundation of the house of Yahweh was laid.'),
  ('b866077d-6eec-51fb-a2b5-c8e88ab2c276', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 12, 12, 'But many of the priests and Levites and heads of fathers'' [houses], the old men who had seen the first house, when the foundation of this house was laid before their eyes, wept with a loud voice; and many shouted aloud for joy:'),
  ('c6bd73ca-aa0c-52ed-aa6b-81d791e2e323', 'b44d9ccb-8e81-5eaa-a702-25ebe326ecc7', NULL, 13, 13, 'so that the people could not discern the noise of the shout of joy from the noise of the weeping of the people; for the people shouted with a loud shout, and the noise was heard afar off.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2dc6eacd-1e3e-5034-abd0-6c953e17324c', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 1, 1, 'Now when the adversaries of Judah and Benjamin heard that the children of the captivity were building a temple to Yahweh, the God of Israel;'),
  ('911c136a-ddee-5066-a35a-81c9aca394e7', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 2, 2, 'then they drew near to Zerubbabel, and to the heads of fathers'' [houses], and said to them, "Let us build with you; for we seek your God, as you do; and we sacrifice to him since the days of Esar Haddon king of Assyria, who brought us up here."'),
  ('357faf1f-4088-55fa-af3e-3e0ab1309c35', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 3, 3, 'But Zerubbabel, and Jeshua, and the rest of the heads of fathers'' [houses] of Israel, said to them, "You have nothing to do with us in building a house to our God; but we ourselves together will build to Yahweh, the God of Israel, as king Cyrus the king of Persia has commanded us."'),
  ('87d43604-9f1d-58d5-a230-7d171c09e46c', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 4, 4, 'Then the people of the land weakened the hands of the people of Judah, and troubled them in building,'),
  ('21d4e4e4-8786-5cc6-a0ab-96101f46829a', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 5, 5, 'and hired counselors against them, to frustrate their purpose, all the days of Cyrus king of Persia, even until the reign of Darius king of Persia.'),
  ('6ea94783-3003-5f49-adb1-afe09b4d78b5', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 6, 6, 'In the reign of Ahasuerus, in the beginning of his reign, wrote they an accusation against the inhabitants of Judah and Jerusalem.'),
  ('a78d9034-c09a-52f6-a792-3ab81a47f158', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 7, 7, 'In the days of Artaxerxes wrote Bishlam, Mithredath, Tabeel, and the rest of his companions, to Artaxerxes king of Persia; and the writing of the letter was written in the Syrian [character], and set forth in the Syrian [language].'),
  ('043ba378-fe2f-5110-a8a4-d4351c5af7d4', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 8, 8, 'Rehum the chancellor and Shimshai the scribe wrote a letter against Jerusalem to Artaxerxes the king in this sort:'),
  ('4429dc28-bc85-5d36-a434-8147d849a31b', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 9, 9, 'then [wrote] Rehum the chancellor, and Shimshai the scribe, and the rest of their companions, the Dinaites, and the Apharsathchites, the Tarpelites, the Apharsites, the Archevites, the Babylonians, the Shushanchites, the Dehaites, the Elamites,'),
  ('b067ff6e-d265-5bf0-a038-51b4ab3712e3', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 10, 10, 'and the rest of the nations whom the great and noble Osnappar brought over, and set in the city of Samaria, and in the rest [of the country] beyond the River, and so forth.'),
  ('67b55bbc-d4a3-5a9f-ac5b-5b483831d939', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 11, 11, 'This is the copy of the letter that they sent to Artaxerxes the king: Your servants the men beyond the River, and so forth.'),
  ('ea989cbf-7265-5a21-a2ce-b939ddcb4854', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 12, 12, 'Be it known to the king, that the Jews who came up from you are come to us to Jerusalem; they are building the rebellious and the bad city, and have finished the walls, and repaired the foundations.'),
  ('51ef4d46-9072-5549-ae27-29d429034329', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 13, 13, 'Be it known now to the king that if this city is built, and the walls finished, they will not pay tribute, custom, or toll, and in the end it will be hurtful to the kings.'),
  ('397163c7-47f0-5ba7-a646-87a471354722', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 14, 14, 'Now because we eat the salt of the palace, and it is not appropriate for us to see the king''s dishonor, therefore have we sent and informed the king;'),
  ('e73c299a-910f-5e45-ab31-88b68b583cf8', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 15, 15, 'that search may be made in the book of the records of your fathers: so you shall find in the book of the records, and know that this city is a rebellious city, and hurtful to kings and provinces, and that they have moved sedition within the same of old time; for which cause was this city laid waste.'),
  ('33018d9d-96c4-56ec-a33d-836a9ce5aae2', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 16, 16, 'We inform the king that, if this city be built, and the walls finished, by this means you shall have no portion beyond the River.'),
  ('8e696b7b-4cc3-5f0b-a06e-1b3ead44eecf', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 17, 17, '[Then] sent the king an answer to Rehum the chancellor, and to Shimshai the scribe, and to the rest of their companions who dwell in Samaria, and in the rest [of the country] beyond the River: Peace, and so forth.'),
  ('294ecf6f-57ca-51b4-a5e8-91317ebfe60f', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 18, 18, 'The letter which you sent to us has been plainly read before me.'),
  ('c23bd83f-25c4-5e4f-a413-665a041b54b2', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 19, 19, 'I decreed, and search has been made, and it is found that this city of old time has made insurrection against kings, and that rebellion and sedition have been made therein.'),
  ('1e2c58ee-711d-5b28-aec7-0edb3879663e', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 20, 20, 'There have been mighty kings also over Jerusalem, who have ruled over all [the country] beyond the River; and tribute, custom, and toll, was paid to them.'),
  ('0c038e88-677a-5655-aaf1-3f77600c0e99', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 21, 21, 'Make a decree now to cause these men to cease, and that this city not be built, until a decree shall be made by me.'),
  ('a8945917-20e9-562f-a641-09c5b08b9928', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 22, 22, 'Take heed that you not be slack herein: why should damage grow to the hurt of the kings?'),
  ('182465b1-61cf-5c55-a382-ad56a4687cba', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 23, 23, 'Then when the copy of king Artaxerxes'' letter was read before Rehum, and Shimshai the scribe, and their companions, they went in haste to Jerusalem to the Jews, and made them to cease by force and power.'),
  ('5258700f-e31b-56d6-abae-2eec8870354b', '9d12873d-2e0a-5133-a733-fee99e9176ae', NULL, 24, 24, 'Then ceased the work of the house of God which is at Jerusalem; and it ceased until the second year of the reign of Darius king of Persia.'),
  ('e7f38c06-65e5-5a7b-a652-22c83d07bc42', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 1, 1, 'Now the prophets, Haggai the prophet, and Zechariah the son of Iddo, prophesied to the Jews who were in Judah and Jerusalem; in the name of the God of Israel [prophesied they] to them.'),
  ('c52ed6b6-69ad-51fc-a937-2bc3e5912db0', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 2, 2, 'Then rose up Zerubbabel the son of Shealtiel, and Jeshua the son of Jozadak, and began to build the house of God which is at Jerusalem; and with them were the prophets of God, helping them.'),
  ('50c2f701-0e0c-55e7-a14b-e56c48582746', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 3, 3, 'At the same time came to them Tattenai, the governor beyond the River, and Shetharbozenai, and their companions, and said thus to them, "Who gave you a decree to build this house, and to finish this wall?"'),
  ('fb332d40-414e-50cd-a262-782f8e40f574', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 4, 4, 'Then we told them in this way, what the names of the men were who were making this building.'),
  ('5342320c-a4d2-5b96-a440-71759ea24816', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 5, 5, 'But the eye of their God was on the elders of the Jews, and they did not make them cease, until the matter should come to Darius, and then answer should be returned by letter concerning it.'),
  ('d619f9fe-2148-50d8-a3f4-86473cc965f3', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 6, 6, 'The copy of the letter that Tattenai, the governor beyond the River, and Shetharbozenai, and his companions the Apharsachites, who were beyond the River, sent to Darius the king;'),
  ('240c48a3-2884-572b-a083-4c270e140852', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 7, 7, 'they sent a letter to him, in which was written thus: To Darius the king, all peace.'),
  ('c12c01e4-01c8-519c-a3ec-69fb12ee7a94', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 8, 8, 'Be it known to the king, that we went into the province of Judah, to the house of the great God, which is built with great stones, and timber is laid in the walls; and this work goes on with diligence and prospers in their hands.'),
  ('48ad1403-6820-5ee5-a81d-b36b77f22792', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 9, 9, 'Then we asked those elders, and said to them thus, "Who gave you a decree to build this house, and to finish this wall?"'),
  ('fe52e593-acfa-531d-a299-50f3078b6262', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 10, 10, 'We asked them their names also, to inform you that we might write the names of the men who were at the head of them.'),
  ('4c1bab83-72d9-545d-aa3a-70d446230121', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 11, 11, 'Thus they returned us answer, saying, "We are the servants of the God of heaven and earth, and are building the house that was built these many years ago, which a great king of Israel built and finished.'),
  ('af49d71d-a0c9-5b58-a4bb-bfb6abb4079e', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 12, 12, 'But after that our fathers had provoked the God of heaven to wrath, he gave them into the hand of Nebuchadnezzar king of Babylon, the Chaldean, who destroyed this house, and carried the people away into Babylon.'),
  ('22a8df22-a3f7-520c-a23f-d12e568b81c8', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 13, 13, 'But in the first year of Cyrus king of Babylon, Cyrus the king made a decree to build this house of God.'),
  ('61e5a0c7-dff6-568a-a5ba-f96090bd32d1', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 14, 14, 'The gold and silver vessels also of the house of God, which Nebuchadnezzar took out of the temple that was in Jerusalem, and brought into the temple of Babylon, those Cyrus the king took out of the temple of Babylon, and they were delivered to one whose name was Sheshbazzar, whom he had made governor;'),
  ('82f9c24c-e771-5917-ac16-90f6834548cb', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 15, 15, 'and he said to him, ''Take these vessels, go, put them in the temple that is in Jerusalem, and let the house of God be built in its place.'''),
  ('067e4769-933f-57d7-a325-a41ea919d6e8', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 16, 16, 'Then the same Sheshbazzar came, and laid the foundations of the house of God which is in Jerusalem: and since that time even until now has it been in building, and yet it is not completed.'),
  ('406ae2ae-937c-53b3-a521-5f2934723e48', 'bb63ce1e-2174-5e11-a79a-40f3640ad139', NULL, 17, 17, 'Now therefore, if it seem good to the king, let there be search made in the king''s treasure house, which is there at Babylon, whether it be so, that a decree was made of Cyrus the king to build this house of God at Jerusalem; and let the king send his pleasure to us concerning this matter."'),
  ('a663f000-024a-58b1-a0f8-2c6a88d14628', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 1, 1, 'Then Darius the king made a decree, and search was made in the house of the archives, where the treasures were laid up in Babylon.'),
  ('f9bf2e17-d94b-5e04-a2d8-8d3618a1f180', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 2, 2, 'There was found at Achmetha, in the palace that is in the province of Media, a scroll, and therein was thus written for a record:'),
  ('eda179a6-2690-5fbe-a074-67eecea18511', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 3, 3, 'In the first year of Cyrus the king, Cyrus the king made a decree: Concerning the house of God at Jerusalem, let the house be built, the place where they offer sacrifices, and let its foundations be strongly laid; its height sixty cubits, and its breadth sixty cubits;'),
  ('459408e8-d14d-59aa-adfc-4765476b4c44', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 4, 4, 'with three courses of great stones, and a course of new timber: and let the expenses be given out of the king''s house.'),
  ('a235c0a7-487a-590a-a1cf-c78dd664ba56', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 5, 5, 'Also let the gold and silver vessels of the house of God, which Nebuchadnezzar took forth out of the temple which is at Jerusalem, and brought to Babylon, be restored, and brought again to the temple which is at Jerusalem, everyone to its place; and you shall put them in the house of God.'),
  ('b009374b-39d6-54a9-af55-afee0d28e736', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 6, 6, 'Now therefore, Tattenai, governor beyond the River, Shetharbozenai, and your companions the Apharsachites, who are beyond the River, you must stay far from there.'),
  ('e71d7bc5-4ce1-567c-aa48-5c8614afb91a', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 7, 7, 'Leave the work of this house of God alone; let the governor of the Jews and the elders of the Jews build this house of God in its place.'),
  ('6fc35b09-dfa7-5721-a9b6-a56c74ba1fa9', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 8, 8, 'Moreover I make a decree what you shall do to these elders of the Jews for the building of this house of God: that of the king''s goods, even of the tribute beyond the River, expenses be given with all diligence to these men, that they be not hindered.'),
  ('03905b53-1510-56f3-a4bb-efb378c85db0', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 9, 9, 'That which they have need of, both young bulls, and rams, and lambs, for burnt offerings to the God of heaven; [also] wheat, salt, wine, and oil, according to the word of the priests who are at Jerusalem, let it be given them day by day without fail;'),
  ('53a442ce-70cf-5bbd-ac84-cd736025a7ee', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 10, 10, 'that they may offer sacrifices of pleasant aroma to the God of heaven, and pray for the life of the king, and of his sons.'),
  ('f524da1d-91e6-5d73-ac37-5bb793c7d0fb', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 11, 11, 'Also I have made a decree, that whoever shall alter this word, let a beam be pulled out from his house, and let him be lifted up and fastened thereon; and let his house be made a dunghill for this:'),
  ('0a1cc8a9-4e05-5fe7-a01f-67260ca94730', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 12, 12, 'and the God who has caused his name to dwell there overthrow all kings and peoples who shall put forth their hand to alter [the same], to destroy this house of God which is at Jerusalem. I Darius have made a decree; let it be done with all diligence.'),
  ('e62df893-10d0-5f8b-abb3-9250fa938b53', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 13, 13, 'Then Tattenai, the governor beyond the River, Shetharbozenai, and their companions, because that Darius the king had sent, did accordingly with all diligence.'),
  ('7236380f-6af3-5445-a755-d0bbb1c3a641', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 14, 14, 'The elders of the Jews built and prospered, through the prophesying of Haggai the prophet and Zechariah the son of Iddo. They built and finished it, according to the commandment of the God of Israel, and according to the decree of Cyrus, and Darius, and Artaxerxes king of Persia.'),
  ('e8c8cfef-90b5-5514-a462-a0e4ce048b21', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 15, 15, 'This house was finished on the third day of the month Adar, which was in the sixth year of the reign of Darius the king.'),
  ('12a0c07c-98fb-5aee-ac70-affc17a7d0cc', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 16, 16, 'The children of Israel, the priests, and the Levites, and the rest of the children of the captivity, kept the dedication of this house of God with joy.'),
  ('60f209ec-bc52-5626-a9c2-a07bc230fa0d', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 17, 17, 'They offered at the dedication of this house of God one hundred bulls, two hundred rams, four hundred lambs; and for a sin offering for all Israel, twelve male goats, according to the number of the tribes of Israel.'),
  ('2f5a13d0-0314-5cdf-a361-c7b8050b0a20', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 18, 18, 'They set the priests in their divisions, and the Levites in their courses, for the service of God, which is at Jerusalem; as it is written in the book of Moses.'),
  ('2010dca5-786f-5d50-a2b9-70836c7368f1', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 19, 19, 'The children of the captivity kept the Passover on the fourteenth [day] of the first month.'),
  ('b1893fc4-d39c-58c5-a0b0-dba904edab55', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 20, 20, 'For the priests and the Levites had purified themselves together; all of them were pure: and they killed the Passover for all the children of the captivity, and for their brothers the priests, and for themselves.'),
  ('380b5e21-435e-529f-acc1-40ba8f70413b', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 21, 21, 'The children of Israel who had come again out of the captivity, and all such as had separated themselves to them from the filthiness of the nations of the land, to seek Yahweh, the God of Israel, ate,'),
  ('8741fcac-cc28-5c13-a07e-e22f57ddd79e', 'ee8447c9-47e7-5a57-a611-cf3f1e52ce58', NULL, 22, 22, 'and kept the feast of unleavened bread seven days with joy: for Yahweh had made them joyful, and had turned the heart of the king of Assyria to them, to strengthen their hands in the work of the house of God, the God of Israel.'),
  ('45fbf361-b5ce-593b-a3a8-1e2bdfcc3ee7', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 1, 1, 'Now after these things, in the reign of Artaxerxes king of Persia, Ezra the son of Seraiah, the son of Azariah, the son of Hilkiah,'),
  ('157fd126-9b12-558b-a467-87a7a444b00e', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 2, 2, 'the son of Shallum, the son of Zadok, the son of Ahitub,'),
  ('4a92937e-6cab-556d-aa4a-8b1e17a8f4a0', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 3, 3, 'the son of Amariah, the son of Azariah, the son of Meraioth,'),
  ('d6bc5624-a8fa-596a-ad77-a535374664fe', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 4, 4, 'the son of Zerahiah, the son of Uzzi, the son of Bukki,'),
  ('06a757a4-6dee-58b3-a55a-0b236c95470f', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 5, 5, 'the son of Abishua, the son of Phinehas, the son of Eleazar, the son of Aaron the chief priest;'),
  ('8aa24050-c3da-5e8e-a60a-15ebf37b22db', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 6, 6, 'this Ezra went up from Babylon: and he was a ready scribe in the law of Moses, which Yahweh, the God of Israel, had given; and the king granted him all his request, according to the hand of Yahweh his God on him.'),
  ('6b9ffbaa-6533-5bea-a558-9fd03101da14', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 7, 7, 'There went up some of the children of Israel, and of the priests, and the Levites, and the singers, and the porters, and the Nethinim, to Jerusalem, in the seventh year of Artaxerxes the king.'),
  ('c2ac084e-b576-52c6-a07b-1abb822fa872', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 8, 8, 'He came to Jerusalem in the fifth month, which was in the seventh year of the king.'),
  ('c0d7d980-fabe-5235-a547-8b678df5381b', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 9, 9, 'For on the first [day] of the first month began he to go up from Babylon; and on the first [day] of the fifth month came he to Jerusalem, according to the good hand of his God on him.'),
  ('287b8157-48e4-57a7-aa20-579b37b168f3', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 10, 10, 'For Ezra had set his heart to seek the law of Yahweh, and to do it, and to teach in Israel statutes and ordinances.'),
  ('a1636b74-8e8f-5864-a39c-94212eabffe8', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 11, 11, 'Now this is the copy of the letter that the king Artaxerxes gave to Ezra the priest, the scribe, even the scribe of the words of the commandments of Yahweh, and of his statutes to Israel:'),
  ('38c71341-ce98-5cf8-a38d-e919c2d17501', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 12, 12, 'Artaxerxes, king of kings, to Ezra the priest, the scribe of the law of the God of heaven, perfect and so forth.'),
  ('0dce7e7f-14f1-580d-a1f9-45cf22e1c436', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 13, 13, 'I make a decree, that all those of the people of Israel, and their priests and the Levites, in my realm, who are minded of their own free will to go to Jerusalem, go with you.'),
  ('7ac1b816-5e41-5bc4-ab15-4de33f5f36b6', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 14, 14, 'Because you are sent of the king and his seven counselors, to inquire concerning Judah and Jerusalem, according to the law of your God which is in your hand,'),
  ('10a58024-2ff3-5fa0-a0e5-971ac4734635', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 15, 15, 'and to carry the silver and gold, which the king and his counselors have freely offered to the God of Israel, whose habitation is in Jerusalem,'),
  ('3d9f03ae-38fd-5900-adbb-59bd014e3975', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 16, 16, 'and all the silver and gold that you shall find in all the province of Babylon, with the freewill offering of the people, and of the priests, offering willingly for the house of their God which is in Jerusalem;'),
  ('20fa5691-3390-58a3-a93a-d2c205c73e34', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 17, 17, 'therefore you shall with all diligence buy with this money bulls, rams, lambs, with their meal offerings and their drink offerings, and shall offer them on the altar of the house of your God which is in Jerusalem.'),
  ('424ab72d-6ff6-50c8-a04c-648a0b803680', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 18, 18, 'Whatever shall seem good to you and to your brothers to do with the rest of the silver and the gold, do that after the will of your God.'),
  ('bd33f381-4a63-5a68-ad16-73ac81d183d4', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 19, 19, 'The vessels that are given to you for the service of the house of your God, deliver before the God of Jerusalem.'),
  ('53345feb-0197-507f-a922-f71206090c60', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 20, 20, 'Whatever more shall be needful for the house of your God, which you shall have occasion to bestow, bestow it out of the king''s treasure house.'),
  ('3c72fcbb-4ced-5abf-a9e5-7750a38ff310', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 21, 21, 'I, even I Artaxerxes the king, do make a decree to all the treasurers who are beyond the River, that whatever Ezra the priest, the scribe of the law of the God of heaven, shall require of you, it be done with all diligence,'),
  ('c3c1931d-ecc3-59b0-a180-95e02b4ac3fa', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 22, 22, 'to one hundred talents of silver, and to one hundred measures of wheat, and to one hundred baths of wine, and to one hundred baths of oil, and salt without prescribing how much.'),
  ('97b06709-9972-5eb6-a2fa-11e94717c445', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 23, 23, 'Whatever is commanded by the God of heaven, let it be done exactly for the house of the God of heaven; for why should there be wrath against the realm of the king and his sons?'),
  ('0e107872-d64c-580c-a515-8958ab682106', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 24, 24, 'Also we inform you, that touching any of the priests and Levites, the singers, porters, Nethinim, or servants of this house of God, it shall not be lawful to impose tribute, custom, or toll, on them.'),
  ('d87897ba-02f5-5304-aebd-ddafaf7122a8', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 25, 25, 'You, Ezra, after the wisdom of your God who is in your hand, appoint magistrates and judges, who may judge all the people who are beyond the River, all such as know the laws of your God; and teach him who doesn''t know them.'),
  ('d0e9ac28-37f7-5733-a3fa-df5e904a7c80', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 26, 26, 'Whoever will not do the law of your God, and the law of the king, let judgment be executed on him with all diligence, whether it be to death, or to banishment, or to confiscation of goods, or to imprisonment.'),
  ('b6e8babb-5a0d-5314-a98c-d3d9d64bd396', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 27, 27, 'Blessed be Yahweh, the God of our fathers, who has put such a thing as this in the king''s heart, to beautify the house of Yahweh which is in Jerusalem;'),
  ('a7dfae84-629a-5192-adce-c063a1db1934', '851071bb-0879-5604-a75c-e31d1eec2c9b', NULL, 28, 28, 'and has extended loving kindness to me before the king, and his counselors, and before all the king''s mighty princes. I was strengthened according to the hand of Yahweh my God on me, and I gathered together out of Israel chief men to go up with me.'),
  ('40153f2e-01b2-5672-a36e-7f4032b96b0d', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 1, 1, 'Now these are the heads of their fathers'' [houses], and this is the genealogy of those who went up with me from Babylon, in the reign of Artaxerxes the king:'),
  ('5c5d56dc-f86a-52a7-ac15-d92ce7222505', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 2, 2, 'Of the sons of Phinehas, Gershom. Of the sons of Ithamar, Daniel. Of the sons of David, Hattush.'),
  ('d16dc51a-0e24-53e3-a486-4effc144ef14', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 3, 3, 'Of the sons of Shecaniah, of the sons of Parosh, Zechariah; and with him were reckoned by genealogy of the males one hundred fifty.'),
  ('7bae69d5-d4c7-5c4d-ac9b-639921ae8f2d', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 4, 4, 'Of the sons of Pahathmoab, Eliehoenai the son of Zerahiah; and with him two hundred males.'),
  ('b7af852a-0818-575c-a6ce-5d9b9f278ede', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 5, 5, 'Of the sons of Shecaniah, the son of Jahaziel; and with him three hundred males.'),
  ('2bc1b886-4301-5ccd-a382-418428fe3aae', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 6, 6, 'Of the sons of Adin, Ebed the son of Jonathan; and with him fifty males.'),
  ('25aaedcb-e3ad-5f4e-a68f-9b40f102a194', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 7, 7, 'Of the sons of Elam, Jeshaiah the son of Athaliah; and with him seventy males.'),
  ('0c81a8fb-5348-55e9-afc5-6ce4d05f9fbf', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 8, 8, 'Of the sons of Shephatiah, Zebadiah the son of Michael; and with him eighty males.'),
  ('7305f6c8-be85-5aa9-ac46-a1ebb181737b', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 9, 9, 'Of the sons of Joab, Obadiah the son of Jehiel; and with him two hundred and eighteen males.'),
  ('16257ac3-5df3-515e-a32f-83ad446b1283', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 10, 10, 'Of the sons of Shelomith, the son of Josiphiah; and with him one hundred sixty males.'),
  ('38c2e787-6b8a-556d-a998-1732ca32687c', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 11, 11, 'Of the sons of Bebai, Zechariah the son of Bebai; and with him twenty-eight males.'),
  ('5d132a45-d1f6-5ccf-abe6-eca1e2c5ef90', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 12, 12, 'Of the sons of Azgad, Johanan the son of Hakkatan; and with him one hundred ten males.'),
  ('63f5d6e5-463f-5961-a315-f6f3638ea210', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 13, 13, 'Of the sons of Adonikam, [who were] the last; and these are their names: Eliphelet, Jeuel, and Shemaiah; and with them sixty males.'),
  ('834970d4-b9e0-5df5-aa11-3af5bf6ef63d', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 14, 14, 'Of the sons of Bigvai, Uthai and Zabbud; and with them seventy males.'),
  ('638a2229-c562-5a94-a28e-e3ad090d04f6', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 15, 15, 'I gathered them together to the river that runs to Ahava; and there we encamped three days: and I viewed the people, and the priests, and found there none of the sons of Levi.'),
  ('a1082b33-fb22-56d6-a348-47282ae373fb', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 16, 16, 'Then sent I for Eliezer, for Ariel, for Shemaiah, and for Elnathan, and for Jarib, and for Elnathan, and for Nathan, and for Zechariah, and for Meshullam, chief men; also for Joiarib, and for Elnathan, who were teachers.'),
  ('320a0c30-4fb0-58b6-aafd-e1a99db76a4b', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 17, 17, 'I sent them forth to Iddo the chief at the place Casiphia; and I told them what they should tell Iddo, [and] his brothers the Nethinim, at the place Casiphia, that they should bring to us ministers for the house of our God.'),
  ('372aa1ee-9a81-59b9-a5d8-ab3c71ca2d1f', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 18, 18, 'According to the good hand of our God on us they brought us a man of discretion, of the sons of Mahli, the son of Levi, the son of Israel; and Sherebiah, with his sons and his brothers, eighteen;'),
  ('94354683-0e2c-5e38-a220-64ff30ace359', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 19, 19, 'and Hashabiah, and with him Jeshaiah of the sons of Merari, his brothers and their sons, twenty;'),
  ('26fe1127-c5e2-5360-a993-9cd45a0649bc', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 20, 20, 'and of the Nethinim, whom David and the princes had given for the service of the Levites, two hundred and twenty Nethinim: all of them were mentioned by name.'),
  ('d8ed2abc-2c32-5d01-adaa-a2fae4882768', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 21, 21, 'Then I proclaimed a fast there, at the river Ahava, that we might humble ourselves before our God, to seek of him a straight way for us, and for our little ones, and for all our substance.'),
  ('a17a3455-3607-541b-acb5-3eee0a0b35ff', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 22, 22, 'For I was ashamed to ask of the king a band of soldiers and horsemen to help us against the enemy in the way, because we had spoken to the king, saying, "The hand of our God is on all those who seek him, for good; but his power and his wrath is against all those who forsake him."'),
  ('2707872e-a235-5f8d-a986-719663972437', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 23, 23, 'So we fasted and begged our God for this: and he was entreated of us.'),
  ('57c3ea2e-7eee-5283-a323-d55d1d8c3b67', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 24, 24, 'Then I set apart twelve of the chiefs of the priests, even Sherebiah, Hashabiah, and ten of their brothers with them,'),
  ('aaf9966b-b57f-5111-a053-2956f159fec6', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 25, 25, 'and weighed to them the silver, and the gold, and the vessels, even the offering for the house of our God, which the king, and his counselors, and his princes, and all Israel there present, had offered:'),
  ('58b01c32-d5ec-537c-a6f2-0378702427d4', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 26, 26, 'I weighed into their hand six hundred fifty talents of silver, and silver vessels one hundred talents; of gold one hundred talents;'),
  ('8276a8d1-fce3-5219-a95f-5c28b93660c4', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 27, 27, 'and twenty bowls of gold, of one thousand darics; and two vessels of fine bright brass, precious as gold.'),
  ('8c6bf534-ca92-5151-a3d7-2e161213de54', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 28, 28, 'I said to them, "You are holy to Yahweh, and the vessels are holy; and the silver and the gold are a freewill offering to Yahweh, the God of your fathers.'),
  ('9d5e5df4-676f-5140-a4f1-b688cdc1edcd', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 29, 29, 'Watch, and keep them, until you weigh them before the chiefs of the priests and the Levites, and the princes of the fathers'' [houses] of Israel, at Jerusalem, in the rooms of the house of Yahweh."'),
  ('bec5568f-69b5-54a7-a3e1-2c1c0d6ec084', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 30, 30, 'So the priests and the Levites received the weight of the silver and the gold, and the vessels, to bring them to Jerusalem to the house of our God.'),
  ('9a9f8ca6-d2a7-5cfa-a070-c7cafc85e91e', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 31, 31, 'Then we departed from the river Ahava on the twelfth [day] of the first month, to go to Jerusalem: and the hand of our God was on us, and he delivered us from the hand of the enemy and the bandit by the way.'),
  ('b54edf1d-48dd-56bc-a827-6681479e88f5', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 32, 32, 'We came to Jerusalem, and stayed there three days.'),
  ('e6e61f0b-c967-5ca2-aeb5-09d79eb9140c', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 33, 33, 'On the fourth day the silver and the gold and the vessels were weighed in the house of our God into the hand of Meremoth the son of Uriah the priest; and with him was Eleazar the son of Phinehas; and with them was Jozabad the son of Jeshua, and Noadiah the son of Binnui, the Levite;'),
  ('3647708a-119b-56de-a6ba-3e24d2dee9be', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 34, 34, 'the whole by number and by weight: and all the weight was written at that time.'),
  ('924182b3-b1f6-519b-afb3-17e3cd392a31', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 35, 35, 'The children of the captivity, who had come out of exile, offered burnt offerings to the God of Israel, twelve bulls for all Israel, ninety-six rams, seventy-seven lambs, and twelve male goats for a sin offering: all this was a burnt offering to Yahweh.'),
  ('0a0d211a-b9d0-5991-a07b-26ccf7b8dc54', '570e47a1-236c-5ec0-abe2-faa092b38f1f', NULL, 36, 36, 'They delivered the king''s commissions to the king''s satraps, and to the governors beyond the River: and they furthered the people and the house of God.'),
  ('930e16e0-e33d-5258-a5af-46aa9505ebe3', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 1, 1, 'Now when these things were done, the princes drew near to me, saying, "The people of Israel, and the priests and the Levites, have not separated themselves from the peoples of the lands, [doing] according to their abominations, even of the Canaanites, the Hittites, the Perizzites, the Jebusites, the Ammonites, the Moabites, the Egyptians, and the Amorites.'),
  ('9e1216eb-cb34-51a7-a88f-34e951ccfd08', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 2, 2, 'For they have taken of their daughters for themselves and for their sons, so that the holy seed have mixed themselves with the peoples of the lands. Yes, the hand of the princes and rulers has been chief in this trespass."'),
  ('b436fffb-f075-5f2e-ae00-b5929609d1d8', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 3, 3, 'When I heard this thing, I tore my garment and my robe, and plucked off the hair of my head and of my beard, and sat down confounded.'),
  ('b32b3e4f-272b-5018-a0b5-152041c09c5c', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 4, 4, 'Then were assembled to me everyone who trembled at the words of the God of Israel, because of the trespass of them of the captivity; and I sat confounded until the evening offering.'),
  ('d53d2180-6990-53a4-ad0b-c1e427613afe', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 5, 5, 'At the evening offering I arose up from my humiliation, even with my garment and my robe torn; and I fell on my knees, and spread out my hands to Yahweh my God;'),
  ('a556c70b-2e72-5efd-af64-6cb4d13906ca', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 6, 6, 'and I said, "My God, I am ashamed and blush to lift up my face to you, my God; for our iniquities have increased over our head, and our guiltiness has grown up to the heavens.'),
  ('310c19ff-cdbd-5125-adc9-f31bcfbde499', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 7, 7, 'Since the days of our fathers we have been exceeding guilty to this day; and for our iniquities we, our kings, and our priests, have been delivered into the hand of the kings of the lands, to the sword, to captivity, to plunder, and to confusion of face, as it is this day.'),
  ('2add551d-16d5-552d-a8d6-a5c650e71975', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 8, 8, 'Now for a little moment grace has been shown from Yahweh our God, to leave us a remnant to escape, and to give us a nail in his holy place, that our God may lighten our eyes, and give us a little reviving in our bondage.'),
  ('b7c0adea-6f13-526a-a23a-04551325c3df', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 9, 9, 'For we are bondservants; yet our God has not forsaken us in our bondage, but has extended loving kindness to us in the sight of the kings of Persia, to give us a reviving, to set up the house of our God, and to repair its ruins, and to give us a wall in Judah and in Jerusalem.'),
  ('9c2451e8-18ee-548d-a0d7-629024a88469', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 10, 10, '"Now, our God, what shall we say after this? For we have forsaken your commandments,'),
  ('b3a1f8a0-5cdf-538a-a38a-3808b68d4c76', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 11, 11, 'which you have commanded by your servants the prophets, saying, ''The land, to which you go to possess it, is an unclean land through the uncleanness of the peoples of the lands, through their abominations, which have filled it from one end to another with their filthiness.'),
  ('91c67174-c196-5ad2-a6f8-ec3001408fb7', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 12, 12, 'Now therefore don''t give your daughters to their sons, neither take their daughters to your sons, nor seek their peace or their prosperity forever; that you may be strong, and eat the good of the land, and leave it for an inheritance to your children forever.'''),
  ('d4a6100c-a75e-5464-a8ef-3bb0aea54b89', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 13, 13, '"After all that has come on us for our evil deeds, and for our great guilt, since you, our God, have punished us less than our iniquities deserve, and have given us such a remnant,'),
  ('fb08284c-0476-59e5-a305-eafdf71889a9', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 14, 14, 'shall we again break your commandments, and join in affinity with the peoples that do these abominations? Wouldn''t you be angry with us until you had consumed us, so that there should be no remnant, nor any to escape?'),
  ('b93351b4-b786-5ae1-a039-eea87f986889', '5a24b614-691e-531d-a7c9-21fffc98f2e7', NULL, 15, 15, 'Yahweh, the God of Israel, you are righteous; for we are left a remnant that has escaped, as it is this day. Behold, we are before you in our guiltiness; for none can stand before you because of this."'),
  ('85ba99e2-d70e-5cb4-ae5a-d8bd1f309579', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 1, 1, 'Now while Ezra prayed and made confession, weeping and casting himself down before the house of God, there was gathered together to him out of Israel a very great assembly of men and women and children; for the people wept very bitterly.'),
  ('d4971b1a-6bca-5ea6-a3e0-05f4ecac5385', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 2, 2, 'Shecaniah the son of Jehiel, one of the sons of Elam, answered Ezra, "We have trespassed against our God, and have married foreign women of the peoples of the land. Yet now there is hope for Israel concerning this thing.'),
  ('f0e49e00-143f-5a5d-a968-8947ba31974f', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 3, 3, 'Now therefore let us make a covenant with our God to put away all the wives, and such as are born of them, according to the counsel of my lord, and of those who tremble at the commandment of our God. Let it be done according to the law.'),
  ('7176e44c-c3ef-5dec-a81d-806d170f1587', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 4, 4, 'Arise; for the matter belongs to you, and we are with you. Be courageous, and do it."'),
  ('1ffc0621-18f9-5707-a5c3-49af3998645c', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 5, 5, 'Then Ezra arose, and made the chiefs of the priests, the Levites, and all Israel, to swear that they would do according to this word. So they swore.'),
  ('cfd9455b-6dc4-5ac5-a89c-119ccb9994ac', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 6, 6, 'Then Ezra rose up from before the house of God, and went into the room of Jehohanan the son of Eliashib: and [when] he came there, he ate no bread, nor drank water; for he mourned because of the trespass of them of the captivity.'),
  ('9ae1e99d-e87a-55fd-a1c3-166e2485a9c4', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 7, 7, 'They made proclamation throughout Judah and Jerusalem to all the children of the captivity, that they should gather themselves together to Jerusalem;'),
  ('08faebd9-0f44-5e86-ab68-0ad4ad4d2664', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 8, 8, 'and that whoever didn''t come within three days, according to the counsel of the princes and the elders, all his substance should be forfeited, and himself separated from the assembly of the captivity.'),
  ('33b388df-b65b-56f1-af01-4b5138df7b25', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 9, 9, 'Then all the men of Judah and Benjamin gathered themselves together to Jerusalem within the three days; it was the ninth month, on the twentieth [day] of the month: and all the people sat in the broad place before the house of God, trembling because of this matter, and for the great rain.'),
  ('b1e046b1-c6e2-5356-ae25-ff3643ec2dcc', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 10, 10, 'Ezra the priest stood up, and said to them, "You have trespassed, and have married foreign women, to increase the guilt of Israel.'),
  ('03655f01-0d54-5266-aa1e-e29c1f90ea3c', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 11, 11, 'Now therefore make confession to Yahweh, the God of your fathers, and do his pleasure; and separate yourselves from the peoples of the land, and from the foreign women."'),
  ('e42da8ab-5eea-5b16-aa1b-979ee2e04de8', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 12, 12, 'Then all the assembly answered with a loud voice, "As you have said concerning us, so must we do.'),
  ('e6b1a473-4eff-5ae7-ae48-5fc152d18e2c', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 13, 13, 'But the people are many, and it is a time of much rain, and we are not able to stand outside; neither is this a work of one day or two; for we have greatly transgressed in this matter.'),
  ('4a067399-655f-5a7c-a52e-5e57f188687e', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 14, 14, 'Let now our princes be appointed for all the assembly, and let all those who are in our cities who have married foreign women come at appointed times, and with them the elders of every city, and its judges, until the fierce wrath of our God be turned from us, until this matter is resolved."'),
  ('b7715cc8-a251-5655-ab40-565503a85dd5', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 15, 15, 'Only Jonathan the son of Asahel and Jahzeiah the son of Tikvah stood up against this; and Meshullam and Shabbethai the Levite helped them.'),
  ('200990d0-7f5c-5e92-af86-edd73d46aebc', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 16, 16, 'The children of the captivity did so. Ezra the priest, [with] certain heads of fathers'' [houses], after their fathers'' houses, and all of them by their names, were set apart; and they sat down in the first day of the tenth month to examine the matter.'),
  ('6f949855-abfc-5f1d-a182-1c6e8a622b87', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 17, 17, 'They made an end with all the men who had married foreign women by the first day of the first month.'),
  ('c5143be3-fbee-50e4-ad1a-df25df40ffc1', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 18, 18, 'Among the sons of the priests there were found who had married foreign women: [namely], of the sons of Jeshua, the son of Jozadak, and his brothers, Maaseiah, and Eliezer, and Jarib, and Gedaliah.'),
  ('6bb06b11-e667-59ec-afb0-33f51b3b8d61', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 19, 19, 'They gave their hand that they would put away their wives; and being guilty, [they offered] a ram of the flock for their guilt.'),
  ('ad4fa6a4-2f8d-5ead-aa78-e0a5308f540a', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 20, 20, 'Of the sons of Immer: Hanani and Zebadiah.'),
  ('af5e0588-1c34-514d-a74e-1e1a8a237a69', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 21, 21, 'Of the sons of Harim: Maaseiah, and Elijah, and Shemaiah, and Jehiel, and Uzziah.'),
  ('5deb94ca-c222-5815-a80d-985be913ac1b', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 22, 22, 'Of the sons of Pashhur: Elioenai, Maaseiah, Ishmael, Nethanel, Jozabad, and Elasah.'),
  ('c3f19cb8-b47c-5025-a733-e4b9c205b391', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 23, 23, 'Of the Levites: Jozabad, and Shimei, and Kelaiah (the same is Kelita), Pethahiah, Judah, and Eliezer.'),
  ('6351b33a-6993-5979-a85c-e6cbd17f9d36', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 24, 24, 'Of the singers: Eliashib. Of the porters: Shallum, and Telem, and Uri.'),
  ('2bd0f3fc-daab-546d-ad5d-c7a56e8c23c0', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 25, 25, 'Of Israel: Of the sons of Parosh: Ramiah, and Izziah, and Malchijah, and Mijamin, and Eleazar, and Malchijah, and Benaiah.'),
  ('3513c770-8265-5669-a489-92957642f6a6', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 26, 26, 'Of the sons of Elam: Mattaniah, Zechariah, and Jehiel, and Abdi, and Jeremoth, and Elijah.'),
  ('ea0aaa01-0622-576a-a4d0-7d6e3f6a2784', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 27, 27, 'Of the sons of Zattu: Elioenai, Eliashib, Mattaniah, and Jeremoth, and Zabad, and Aziza.'),
  ('54801a84-3917-50cc-a84f-37a9d444ef15', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 28, 28, 'Of the sons of Bebai: Jehohanan, Hananiah, Zabbai, Athlai.'),
  ('12333e7b-2d3a-528b-a2a4-70f48d5946ff', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 29, 29, 'Of the sons of Bani: Meshullam, Malluch, and Adaiah, Jashub, and Sheal, Jeremoth.'),
  ('5725935c-dad2-57a0-a50e-dc134d9bcd44', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 30, 30, 'Of the sons of Pahathmoab: Adna, and Chelal, Benaiah, Maaseiah, Mattaniah, Bezalel, and Binnui, and Manasseh.'),
  ('13a2bcbc-6ce8-5402-a6f3-84d8c6613875', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 31, 31, '[of] the sons of Harim: Eliezer, Isshijah, Malchijah, Shemaiah, Shimeon,'),
  ('16820a7e-a7aa-514f-a267-61ca74f12655', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 32, 32, 'Benjamin, Malluch, Shemariah.'),
  ('b43a4b8f-aaf7-510b-a7b9-9da2cb0c2ee7', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 33, 33, 'Of the sons of Hashum: Mattenai, Mattattah, Zabad, Eliphelet, Jeremai, Manasseh, Shimei.'),
  ('b6923dcf-bb88-5b38-a10c-86502e88036d', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 34, 34, 'Of the sons of Bani: Maadai, Amram, and Uel,'),
  ('749f3043-6bc3-5851-a301-12d7cd066994', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 35, 35, 'Benaiah, Bedeiah, Cheluhi,'),
  ('69079f12-45bb-5063-a840-c6992abbd89f', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 36, 36, 'Vaniah, Meremoth, Eliashib,'),
  ('a6c47360-8eec-5caa-aac7-ed7e28a925a1', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 37, 37, 'Mattaniah, Mattenai, and Jaasu,'),
  ('19b5a800-175f-5631-ae98-9fc0515fd771', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 38, 38, 'and Bani, and Binnui, Shimei,'),
  ('ef3bc25a-acc7-52bc-aa45-60ce55e28bda', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 39, 39, 'and Shelemiah, and Nathan, and Adaiah,'),
  ('a98e4804-e03b-5e2e-a03c-f50f8b520cae', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 40, 40, 'Machnadebai, Shashai, Sharai,'),
  ('e74f2eef-bde4-5a1f-ac58-9ec5d018b6da', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 41, 41, 'Azarel, and Shelemiah, Shemariah,'),
  ('02a95deb-75ed-588f-ab9d-4fc2117966e3', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 42, 42, 'Shallum, Amariah, Joseph.'),
  ('a0bb3812-f892-517f-a6d8-5039f2bc1fab', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 43, 43, 'Of the sons of Nebo: Jeiel, Mattithiah, Zabad, Zebina, Iddo, and Joel, Benaiah.'),
  ('6e1e8a2f-48ab-569f-a84a-0c9dc6223f48', '2c43671a-3c8d-5a54-a595-9405bc04a34a', NULL, 44, 44, 'All these had taken foreign wives; and some of them had wives by whom they had children.'),
  ('aef9a0f5-eb38-5c69-af12-48b00f2b9ee9', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 1, 1, 'The words of Nehemiah the son of Hacaliah. Now it happened in the month Chislev, in the twentieth year, as I was in Shushan the palace,'),
  ('a971d97c-fc2d-50a8-a876-0e6afa2a7515', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 2, 2, 'that Hanani, one of my brothers, came, he and certain men out of Judah; and I asked them concerning the Jews who had escaped, who were left of the captivity, and concerning Jerusalem.'),
  ('59ab1545-3f69-51d5-a0f8-3afcae619e8f', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 3, 3, 'They said to me, "The remnant who are left of the captivity there in the province are in great affliction and reproach. The wall of Jerusalem also is broken down, and its gates are burned with fire."'),
  ('56a93a32-18cd-5820-a826-f686512afc6f', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 4, 4, 'It happened, when I heard these words, that I sat down and wept, and mourned certain days; and I fasted and prayed before the God of heaven,'),
  ('407b4d12-1d55-5642-a4ff-9c179f498cca', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 5, 5, 'and said, "I beg you, Yahweh, the God of heaven, the great and awesome God, who keeps covenant and loving kindness with those who love him and keep his commandments:'),
  ('6d1d2822-49a7-5fea-a7c1-b2c8ff655efd', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 6, 6, 'Let your ear now be attentive, and your eyes open, that you may listen to the prayer of your servant, which I pray before you at this time, day and night, for the children of Israel your servants while I confess the sins of the children of Israel, which we have sinned against you. Yes, I and my father''s house have sinned.'),
  ('c2535bee-32ba-561c-a1e6-f997134ee2e3', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 7, 7, 'We have dealt very corruptly against you, and have not kept the commandments, nor the statutes, nor the ordinances, which you commanded your servant Moses.'),
  ('4b03ab2f-13c2-5b4a-a4ac-5c0cd66f9013', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 8, 8, '"Remember, I beg you, the word that you commanded your servant Moses, saying, ''If you trespass, I will scatter you abroad among the peoples;'),
  ('d01534a3-eecb-5543-ac5e-2f5923eae3a9', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 9, 9, 'but if you return to me, and keep my commandments and do them, though your outcasts were in the uttermost part of the heavens, yet will I gather them from there, and will bring them to the place that I have chosen, to cause my name to dwell there.'''),
  ('77818a56-7fd1-54df-ad24-5155ec89f0de', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 10, 10, '"Now these are your servants and your people, whom you have redeemed by your great power, and by your strong hand.'),
  ('89596683-e9dc-5414-a62b-dc2ebe04cf9a', '3dcb3703-ab0f-5663-af57-8b4cd6305f8f', NULL, 11, 11, 'Lord, I beg you, let your ear be attentive now to the prayer of your servant, and to the prayer of your servants, who delight to fear your name; and please prosper your servant this day, and grant him mercy in the sight of this man." Now I was cup bearer to the king.'),
  ('7278d9c0-063c-59c6-ae90-6cb094a998c8', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 1, 1, 'It happened in the month Nisan, in the twentieth year of Artaxerxes the king, when wine was before him, that I took up the wine, and gave it to the king. Now I had not been [before] sad in his presence.'),
  ('1f9c388d-8a2e-5838-ae1b-d286d175280f', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 2, 2, 'The king said to me, "Why is your face sad, since you are not sick? This is nothing else but sorrow of heart." Then I was very much afraid.'),
  ('662e9c82-63f8-5836-aa3d-2c31b37b4cfd', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 3, 3, 'I said to the king, "Let the king live forever! Why shouldn''t my face be sad, when the city, the place of my fathers'' tombs, lies waste, and its gates have been consumed with fire?"'),
  ('82dd6ca4-a65d-5df0-a858-05129176df99', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 4, 4, 'Then the king said to me, "For what do you make request?" So I prayed to the God of heaven.'),
  ('42d7a2e0-8ae1-56e9-ab77-1f7f0822548d', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 5, 5, 'I said to the king, "If it pleases the king, and if your servant has found favor in your sight, that you would send me to Judah, to the city of my fathers'' tombs, that I may build it."'),
  ('3a92b78d-f17e-5375-a09d-f350b007f4ee', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 6, 6, 'The king said to me (the queen was also sitting by him), "For how long shall your journey be? And when will you return?" So it pleased the king to send me; and I set him a time.'),
  ('cec50bba-9c63-54d2-aae7-90c8a48497d4', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 7, 7, 'Moreover I said to the king, "If it pleases the king, let letters be given me to the governors beyond the River, that they may let me pass through until I come to Judah;'),
  ('1a158a40-81e9-5c53-a4ee-7138e5af6483', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 8, 8, 'and a letter to Asaph the keeper of the king''s forest, that he may give me timber to make beams for the gates of the citadel by the temple, for the wall of the city, and for the house that I shall enter into." The king granted my requests, because of the good hand of my God on me.'),
  ('6327918c-d6bb-565e-a765-3d5c00c4a6d0', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 9, 9, 'Then I came to the governors beyond the River, and gave them the king''s letters. Now the king had sent with me captains of the army and horsemen.'),
  ('8fae4500-c260-5005-ad86-79318df9de5a', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 10, 10, 'When Sanballat the Horonite, and Tobiah the servant, the Ammonite, heard of it, it grieved them exceedingly, because a man had come to seek the welfare of the children of Israel.'),
  ('452032f0-65e0-5340-ab01-4f256fc837f7', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 11, 11, 'So I came to Jerusalem, and was there three days.'),
  ('11381fd0-6ea1-5d86-a5d8-bad9a8bfed1a', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 12, 12, 'I arose in the night, I and some few men with me; neither told I any man what my God put into my heart to do for Jerusalem; neither was there any animal with me, except the animal that I rode on.'),
  ('7ec0afab-a5db-56f1-afc7-08841703da13', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 13, 13, 'I went out by night by the valley gate, even toward the jackal''s well, and to the dung gate, and viewed the walls of Jerusalem, which were broken down, and its gates were consumed with fire.'),
  ('ae9adca7-3670-5fc8-acf9-0c9ba74ee1d9', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 14, 14, 'Then I went on to the spring gate and to the king''s pool: but there was no place for the animal that was under me to pass.'),
  ('2c00da78-5ded-58f5-aacb-f309b06bc6f2', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 15, 15, 'Then went I up in the night by the brook, and viewed the wall; and I turned back, and entered by the valley gate, and so returned.'),
  ('c8ce4b64-abe1-5e8d-a112-6cc4bf677ed7', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 16, 16, 'The rulers didn''t know where I went, or what I did; neither had I as yet told it to the Jews, nor to the priests, nor to the nobles, nor to the rulers, nor to the rest who did the work.'),
  ('5d0329fd-2a43-5dd0-ab14-6a11ef48a8c1', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 17, 17, 'Then I said to them, "You see the evil case that we are in, how Jerusalem lies waste, and its gates are burned with fire. Come, let us build up the wall of Jerusalem, that we won''t be disgraced."'),
  ('28dbbca2-395b-59eb-a979-d09920d322c6', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 18, 18, 'I told them of the hand of my God which was good on me, as also of the king''s words that he had spoken to me. They said, "Let''s rise up and build." So they strengthened their hands for the good work.'),
  ('d0ec5477-cfa3-5e9f-a7e1-eeb67cee3524', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 19, 19, 'But when Sanballat the Horonite, and Tobiah the servant, the Ammonite, and Geshem the Arabian, heard it, they ridiculed us, and despised us, and said, "What is this thing that you are doing? Will you rebel against the king?"'),
  ('90d9568c-e42e-50e7-a4bc-443110b71978', 'a9223554-c27e-50bc-abf3-6fb46cf0f28c', NULL, 20, 20, 'Then answered I them, and said to them, "The God of heaven will prosper us. Therefore we, his servants, will arise and build; but you have no portion, nor right, nor memorial, in Jerusalem."'),
  ('278afcea-024b-5ec5-a856-58d50eae238c', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 1, 1, 'Then Eliashib the high priest rose up with his brothers the priests, and they built the sheep gate; they sanctified it, and set up its doors; even to the tower of Hammeah they sanctified it, to the tower of Hananel.'),
  ('9e4a602e-f034-5273-a3a7-dd8c006704e0', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 2, 2, 'Next to him built the men of Jericho. Next to them built Zaccur the son of Imri.'),
  ('b7576176-8b0d-5fe5-a412-cbf94f2fd3ac', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 3, 3, 'The fish gate did the sons of Hassenaah build; they laid its beams, and set up its doors, its bolts, and its bars.'),
  ('8c14142e-3dd6-5381-a545-7d448e854ecc', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 4, 4, 'Next to them repaired Meremoth the son of Uriah, the son of Hakkoz. Next to them repaired Meshullam the son of Berechiah, the son of Meshezabel. Next to them repaired Zadok the son of Baana.'),
  ('46571101-e058-5761-a1a2-456311fb1dea', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 5, 5, 'Next to them the Tekoites repaired; but their nobles didn''t put their necks to the work of their lord.'),
  ('ab6ae189-c1b8-5f7e-aaa7-2df04f3637d4', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 6, 6, 'The old gate repaired Joiada the son of Paseah and Meshullam the son of Besodeiah; they laid its beams, and set up its doors, and its bolts, and its bars.'),
  ('1cd6b8e2-8c77-5bb6-acbe-2a9c78ab2299', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 7, 7, 'Next to them repaired Melatiah the Gibeonite, and Jadon the Meronothite, the men of Gibeon, and of Mizpah, [that appertained] to the throne of the governor beyond the River.'),
  ('ffafc803-1f3c-5c6e-a661-c3087b48ab70', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 8, 8, 'Next to him repaired Uzziel the son of Harhaiah, goldsmiths. Next to him repaired Hananiah one of the perfumers, and they fortified Jerusalem even to the broad wall.'),
  ('ec53e47d-1fd6-5cae-acfb-50bae5aa1002', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 9, 9, 'Next to them repaired Rephaiah the son of Hur, the ruler of half the district of Jerusalem.'),
  ('7d3e9a2e-d7e0-564b-a4de-e0f11f195c1b', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 10, 10, 'Next to them repaired Jedaiah the son of Harumaph, over against his house. Next to him repaired Hattush the son of Hashabneiah.'),
  ('3e366813-2a8c-5fbc-a322-1a4e83ac7ea0', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 11, 11, 'Malchijah the son of Harim, and Hasshub the son of Pahathmoab, repaired another portion, and the tower of the furnaces.'),
  ('8b724831-6a9f-5355-aaea-874ff895aef2', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 12, 12, 'Next to him repaired Shallum the son of Hallohesh, the ruler of half the district of Jerusalem, he and his daughters.'),
  ('d06e1b1c-2994-5500-ad81-610acf77d207', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 13, 13, 'The valley gate repaired Hanun, and the inhabitants of Zanoah; they built it, and set up its doors, its bolts, and its bars, and one thousand cubits of the wall to the dung gate.'),
  ('4a64bb56-cb87-593b-a391-ddd542dfa6f3', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 14, 14, 'The dung gate repaired Malchijah the son of Rechab, the ruler of the district of Beth Haccherem; he built it, and set up its doors, its bolts, and its bars.'),
  ('0e7862ae-9888-585c-a7c3-6e219b878400', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 15, 15, 'The spring gate repaired Shallun the son of Colhozeh, the ruler of the district of Mizpah; he built it, and covered it, and set up its doors, its bolts, and its bars, and the wall of the pool of Shelah by the king''s garden, even to the stairs that go down from the city of David.'),
  ('114c21ca-5bac-5c00-abc1-a9ae93314bd8', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 16, 16, 'After him repaired Nehemiah the son of Azbuk, the ruler of half the district of Beth Zur, to the place over against the tombs of David, and to the pool that was made, and to the house of the mighty men.'),
  ('3d78a8d3-5fba-5e1e-a614-2a3ded43fc1f', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 17, 17, 'After him repaired the Levites, Rehum the son of Bani. Next to him repaired Hashabiah, the ruler of half the district of Keilah, for his district.'),
  ('2d3afe2e-68e1-544c-a584-3301e8037d9d', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 18, 18, 'After him repaired their brothers, Bavvai the son of Henadad, the ruler of half the district of Keilah.'),
  ('3f4358b5-a234-5dbf-a549-08cddad48146', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 19, 19, 'Next to him repaired Ezer the son of Jeshua, the ruler of Mizpah, another portion, over against the ascent to the armory at the turning [of the wall].'),
  ('dc14a2f0-17e2-527b-a8c7-85822073b6af', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 20, 20, 'After him Baruch the son of Zabbai earnestly repaired another portion, from the turning [of the wall] to the door of the house of Eliashib the high priest.'),
  ('f5f879d9-37f1-55ab-a994-f0c506479c25', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 21, 21, 'After him repaired Meremoth the son of Uriah the son of Hakkoz another portion, from the door of the house of Eliashib even to the end of the house of Eliashib.'),
  ('9f364b61-355e-5b3b-a5c8-f84562d3e649', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 22, 22, 'After him repaired the priests, the men of the Plain.'),
  ('d28f65fa-5ade-5872-a361-45996078a295', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 23, 23, 'After them repaired Benjamin and Hasshub over against their house. After them repaired Azariah the son of Maaseiah the son of Ananiah beside his own house.'),
  ('a80ff780-f1c9-5bf9-ab58-d018a94da6b0', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 24, 24, 'After him repaired Binnui the son of Henadad another portion, from the house of Azariah to the turning [of the wall], and to the corner.'),
  ('1ce84038-a1a0-50d2-ac5c-58f860aaf8bc', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 25, 25, 'Palal the son of Uzai [repaired] over against the turning [of the wall], and the tower that stands out from the upper house of the king, which is by the court of the guard. After him Pedaiah the son of Parosh [repaired].'),
  ('52bacc1c-7e9e-5921-ae8d-ba7be385b2ea', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 26, 26, '(Now the Nethinim lived in Ophel, to the place over against the water gate toward the east, and the tower that stands out.)'),
  ('9f5392e7-6a69-5dfe-a5b8-aa251948682a', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 27, 27, 'After him the Tekoites repaired another portion, over against the great tower that stands out, and to the wall of Ophel.'),
  ('33b48137-8f92-5364-ad6c-dc85e56d21e8', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 28, 28, 'Above the horse gate repaired the priests, everyone over against his own house.'),
  ('f937360b-bbab-58e7-ae5b-0ee570d447f4', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 29, 29, 'After them repaired Zadok the son of Immer over against his own house. After him repaired Shemaiah the son of Shecaniah, the keeper of the east gate.'),
  ('cd5b74a0-55f2-5d61-a1db-8ce5c2c97562', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 30, 30, 'After him repaired Hananiah the son of Shelemiah, and Hanun the sixth son of Zalaph, another portion. After him repaired Meshullam the son of Berechiah over against his room.'),
  ('931c0c86-c372-5f33-ad99-b1cc2373109f', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 31, 31, 'After him repaired Malchijah one of the goldsmiths to the house of the Nethinim, and of the merchants, over against the gate of Hammiphkad, and to the ascent of the corner.'),
  ('17974271-8cff-50a1-a7f5-e60d5386d307', '5d3ce6b0-5317-580e-af00-00c774936a40', NULL, 32, 32, 'Between the ascent of the corner and the sheep gate repaired the goldsmiths and the merchants.'),
  ('ba2e0a50-7f2b-514f-a06c-c31c6d9139da', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 1, 1, 'But it happened that when Sanballat heard that we were building the wall, he was angry, and took great indignation, and mocked the Jews.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('7a300032-71b6-53b8-a702-a355c10c3359', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 2, 2, 'He spoke before his brothers and the army of Samaria, and said, "What are these feeble Jews doing? Will they fortify themselves? Will they sacrifice? Will they finish in a day? Will they revive the stones out of the heaps of rubbish, since they are burned?"'),
  ('35a9dc10-5509-5599-aa27-93f25facf5f3', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 3, 3, 'Now Tobiah the Ammonite was by him, and he said, "What they are building, if a fox climbed up it, he would break down their stone wall."'),
  ('10922f19-a0bd-5730-aa04-e4abc47868e0', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 4, 4, '"Hear, our God; for we are despised; and turn back their reproach on their own head, give them up for a spoil in a land of captivity;'),
  ('94eadca8-3944-54e6-a73d-eeb76cec6a6f', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 5, 5, 'don''t cover their iniquity, and don''t let their sin be blotted out from before you; for they have insulted the builders."'),
  ('c5540184-2956-517d-a8da-d53809fe9d1a', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 6, 6, 'So we built the wall; and all the wall was joined together to half [the height] of it: for the people had a mind to work.'),
  ('c0eabbe5-1f62-52c9-a0c2-33eb74fff2f5', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 7, 7, 'But it happened that when Sanballat, Tobiah, the Arabians, the Ammonites, and the Ashdodites heard that the repairing of the walls of Jerusalem went forward, [and] that the breaches began to be stopped, then they were very angry;'),
  ('d01a420e-d3f8-5a80-a179-af9cb006887f', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 8, 8, 'and they conspired all of them together to come and fight against Jerusalem, and to cause confusion therein.'),
  ('fa56b0df-ec57-589b-acba-2d0b646daa19', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 9, 9, 'But we made our prayer to our God, and set a watch against them day and night, because of them.'),
  ('6577999d-93af-50fb-a8b0-41dba6373904', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 10, 10, 'Judah said, "The strength of the bearers of burdens is fading, and there is much rubbish; so that we are not able to build the wall."'),
  ('d711ba6c-1bd4-5f52-ae1e-c2f044653ada', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 11, 11, 'Our adversaries said, "They shall not know, neither see, until we come into the midst of them, and kill them, and cause the work to cease."'),
  ('49474a30-6d8a-5d24-aa3c-b826ff3cf447', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 12, 12, 'It happened that when the Jews who lived by them came, they said to us ten times from all places, "Wherever you turn, they will attack us."'),
  ('90156122-aad9-5934-ac3c-b0a17da11b0b', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 13, 13, 'Therefore set I in the lowest parts of the space behind the wall, in the open places, I set [there] the people after their families with their swords, their spears, and their bows.'),
  ('fdf40b46-07a9-5972-a234-694d83b5e3e9', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 14, 14, 'I looked, and rose up, and said to the nobles, and to the rulers, and to the rest of the people, "Don''t be afraid of them! Remember the Lord, who is great and awesome, and fight for your brothers, your sons, and your daughters, your wives, and your houses."'),
  ('8e7c9363-3608-53d2-a14e-9a96e2769603', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 15, 15, 'It happened, when our enemies heard that it was known to us, and God had brought their counsel to nothing, that we returned all of us to the wall, everyone to his work.'),
  ('72ab1e84-2318-5e4c-ad4a-32bfa32a77f2', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 16, 16, 'It happened from that time forth, that half of my servants worked in the work, and half of them held the spears, the shields, and the bows, and the coats of mail; and the rulers were behind all the house of Judah.'),
  ('c156542a-1a75-50cf-ae7d-413183e08a93', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 17, 17, 'They all built the wall and those who bore burdens loaded themselves; everyone with one of his hands worked in the work, and with the other held his weapon;'),
  ('db328983-85c7-58f9-ab3f-527185a4f267', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 18, 18, 'and the builders, everyone wore his sword at his side, and so built. He who sounded the trumpet was by me.'),
  ('47c831e1-f659-5d21-a730-e90f9f9bdf38', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 19, 19, 'I said to the nobles, and to the rulers and to the rest of the people, "The work is great and large, and we are separated on the wall, one far from another.'),
  ('e2b383a7-45a3-50ab-a5e0-5dd758812ac2', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 20, 20, 'Wherever you hear the sound of the trumpet, rally there to us. Our God will fight for us."'),
  ('f8ba06dc-1863-57f4-a21a-6878ca53a817', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 21, 21, 'So we worked in the work: and half of them held the spears from the rising of the morning until the stars appeared.'),
  ('d48016e1-388b-508f-acf3-a93399368f2a', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 22, 22, 'Likewise at the same time said I to the people, "Let everyone with his servant lodge within Jerusalem, that in the night they may be a guard to us, and may labor in the day."'),
  ('d542d1e1-dc14-5f0d-a7d7-851200c8ebfb', 'f7bdd948-b95c-5fce-ab9b-87754c65b0ce', NULL, 23, 23, 'So neither I, nor my brothers, nor my servants, nor the men of the guard who followed me, none of us took off our clothes. Everyone took his weapon to the water.'),
  ('784e49eb-6650-536b-a4c3-8ad719cd16e0', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 1, 1, 'Then there arose a great cry of the people and of their wives against their brothers the Jews.'),
  ('f0b859ef-ccbc-5ac2-a4a3-09078bdbc77b', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 2, 2, 'For there were that said, "We, our sons and our daughters, are many. Let us get grain, that we may eat and live."'),
  ('fcb16bc8-0007-575d-a590-d398aea24133', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 3, 3, 'Some also there were that said, "We are mortgaging our fields, and our vineyards, and our houses. Let us get grain, because of the famine."'),
  ('d76bab36-1ae5-5604-a7e0-4624e355e434', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 4, 4, 'There were also some who said, "We have borrowed money for the king''s tribute using our fields and our vineyards as collateral.'),
  ('f05a5dc0-2e67-5347-acf3-79ae6f750db5', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 5, 5, 'Yet now our flesh is as the flesh of our brothers, our children as their children. Behold, we bring into bondage our sons and our daughters to be servants, and some of our daughters have been brought into bondage. Neither is it in our power to help it; for other men have our fields and our vineyards."'),
  ('e6c162da-af2e-505f-adef-21cf1631c0a5', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 6, 6, 'I was very angry when I heard their cry and these words.'),
  ('4e7dd4c7-0c36-5ea2-aa6d-90e25ee817eb', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 7, 7, 'Then I consulted with myself, and contended with the nobles and the rulers, and said to them, "You exact usury, everyone of his brother." I held a great assembly against them.'),
  ('9473beaf-cf6c-5182-a6ef-c71c565f5e1b', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 8, 8, 'I said to them, "We, after our ability, have redeemed our brothers the Jews that were sold to the nations; and would you even sell your brothers, and should they be sold to us?" Then they held their peace, and found never a word.'),
  ('8e344948-cad7-53d5-a421-5b2cd9ce6000', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 9, 9, 'Also I said, "The thing that you do is not good. Ought you not to walk in the fear of our God, because of the reproach of the nations our enemies?'),
  ('506ab558-278a-5fd9-ae49-e33e5e836fa7', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 10, 10, 'I likewise, my brothers and my servants, lend them money and grain. Please let us stop this usury.'),
  ('d6746b25-2ba9-5446-a230-b3b29a20ccc6', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 11, 11, 'Please restore to them, even this day, their fields, their vineyards, their olive groves, and their houses, also the hundredth part of the money, and of the grain, the new wine, and the oil, that you are charging them."'),
  ('485e411f-cc1e-5ebc-a2d9-07d0d729e42f', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 12, 12, 'Then they said, "We will restore them, and will require nothing of them; so will we do, even as you say." Then I called the priests, and took an oath of them, that they would do according to this promise.'),
  ('5558e41f-6696-5caf-a849-276c8d9f147a', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 13, 13, 'Also I shook out my lap, and said, "So may God shake out every man from his house, and from his labor, that doesn''t perform this promise; even thus be he shaken out, and emptied." All the assembly said, "Amen," and praised Yahweh. The people did according to this promise.'),
  ('6704a0f8-4c64-553d-ac1b-edfe37cf4dce', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 14, 14, 'Moreover from the time that I was appointed to be their governor in the land of Judah, from the twentieth year even to the two and thirtieth year of Artaxerxes the king, [that is], twelve years, I and my brothers have not eaten the bread of the governor.'),
  ('ec5a70ab-63bb-5d85-af02-c7c07effedfb', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 15, 15, 'But the former governors who were before me were supported by the people, and took bread and wine from them, besides forty shekels of silver; yes, even their servants ruled over the people: but I didn''t do so, because of the fear of God.'),
  ('e3868a84-e59f-5864-a4af-994b183ba5d1', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 16, 16, 'Yes, also I continued in the work of this wall, neither bought we any land: and all my servants were gathered there to the work.'),
  ('457ab5a7-47fd-57e6-af41-cd37b949e9ff', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 17, 17, 'Moreover there were at my table, of the Jews and the rulers, one hundred fifty men, besides those who came to us from among the nations that were around us.'),
  ('3d218159-d646-572c-aa98-7a23d5ba6881', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 18, 18, 'Now that which was prepared for one day was one ox and six choice sheep; also fowls were prepared for me, and once in ten days store of all sorts of wine: yet for all this I didn''t demand the bread of the governor, because the bondage was heavy on this people.'),
  ('1fc58661-f45f-548f-a1fe-ed3288121f12', '80dcdf52-a310-5b19-a432-85a463815a38', NULL, 19, 19, 'Remember to me, my God, for good, all that I have done for this people.'),
  ('86909b85-8230-5c39-a778-62032bec5001', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 1, 1, 'Now it happened, when it was reported to Sanballat and Tobiah, and to Geshem the Arabian, and to the rest of our enemies, that I had built the wall, and that there was no breach left therein; (though even to that time I had not set up the doors in the gates;)'),
  ('e490fc9c-4fae-5e39-a18c-9becc1065bdf', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 2, 2, 'that Sanballat and Geshem sent to me, saying, "Come, let us meet together in [one of] the villages in the plain of Ono." But they intended to harm me.'),
  ('c636b07d-3a6f-5845-a870-8a0695a835a3', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 3, 3, 'I sent messengers to them, saying, "I am doing a great work, so that I can''t come down. Why should the work cease, while I leave it, and come down to you?"'),
  ('1e27cd1f-9e1d-539e-a16a-abfadbe90e91', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 4, 4, 'They sent to me four times after this sort; and I answered them the same way.'),
  ('7e584a08-7c52-5efb-ad77-aa6e3c1a448c', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 5, 5, 'Then Sanballat sent his servant to me the same way the fifth time with an open letter in his hand,'),
  ('8552ef0e-6c7d-58e1-af84-fa72ae13d96d', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 6, 6, 'in which was written, "It is reported among the nations, and Gashmu says it, that you and the Jews intend to rebel. Because of that, you are building the wall. You would be their king, according to these words.'),
  ('f00e0c35-b14c-59ef-aaa9-cc6758fec63b', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 7, 7, 'You have also appointed prophets to preach of you at Jerusalem, saying, ''There is a king in Judah!'' Now it will be reported to the king according to these words. Come now therefore, and let us take counsel together."'),
  ('dc2cc80d-ca18-5d36-a94f-35b9b8b1175b', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 8, 8, 'Then I sent to him, saying, "There are no such things done as you say, but you imagine them out of your own heart."'),
  ('7eb8a8a2-3f83-58f6-ac07-d609211a77b5', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 9, 9, 'For they all would have made us afraid, saying, "Their hands will be weakened from the work, that it not be done. But now, [God], strengthen my hands."'),
  ('26c90d79-d085-523c-ab37-cefb8031184b', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 10, 10, 'I went to the house of Shemaiah the son of Delaiah the son of Mehetabel, who was shut in at his home; and he said, "Let us meet together in the house of God, within the temple, and let us shut the doors of the temple; for they will come to kill you; yes, in the night will they come to kill you."'),
  ('653ea9df-69d7-5b58-ad3b-0ae4bfe95b87', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 11, 11, 'I said, "Should such a man as I flee? Who is there that, being such as I, would go into the temple to save his life? I will not go in."'),
  ('b04b355d-3857-5a10-a0e3-e96115c17dad', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 12, 12, 'I discerned, and behold, God had not sent him; but he pronounced this prophecy against me. Tobiah and Sanballat had hired him.'),
  ('9eb00485-e709-5363-ac19-2580ee40c226', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 13, 13, 'He hired so that I would be afraid, do so, and sin, and that they might have material for an evil report, that they might reproach me.'),
  ('fec1beef-5802-5084-a133-d67a4c2cc1b4', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 14, 14, '"Remember, my God, Tobiah and Sanballat according to these their works, and also the prophetess Noadiah, and the rest of the prophets, that would have put me in fear."'),
  ('1dc7c375-1ad8-5714-a597-f6ab831221ce', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 15, 15, 'So the wall was finished in the twenty-fifth [day] of [the month] Elul, in fifty-two days.'),
  ('8307bb48-726c-5831-ace2-2c6eb3434792', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 16, 16, 'It happened, when all our enemies heard [of it], that all the nations that were about us feared, and were much cast down in their own eyes; for they perceived that this work was worked of our God.'),
  ('97e2dc9b-bf3d-5f70-a466-e0ecdc157c4d', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 17, 17, 'Moreover in those days the nobles of Judah sent many letters to Tobiah, and [the letters] of Tobiah came to them.'),
  ('afb5a64c-9899-5452-ac90-76fdbd2036d7', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 18, 18, 'For there were many in Judah sworn to him, because he was the son-in-law of Shecaniah the son of Arah; and his son Jehohanan had taken the daughter of Meshullam the son of Berechiah as wife.'),
  ('067895ce-acb2-5aa3-a029-a13beb4991c3', '253f5d4d-83a6-5cf3-a886-aacf069d05d0', NULL, 19, 19, 'Also they spoke of his good deeds before me, and reported my words to him. Tobiah sent letters to put me in fear.'),
  ('f6682a5d-6468-59c6-a8bf-4c11740e4e73', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 1, 1, 'Now it happened, when the wall was built, and I had set up the doors, and the porters and the singers and the Levites were appointed,'),
  ('db7c5353-9187-58a8-a83c-50efc98bfe17', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 2, 2, 'that I put my brother Hanani, and Hananiah the governor of the castle, in charge of Jerusalem; for he was a faithful man, and feared God above many.'),
  ('217f52ee-fcc6-5ac7-a806-6f396f8d95fd', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 3, 3, 'I said to them, "Don''t let the gates of Jerusalem be opened until the sun is hot; and while they stand guard, let them shut the doors, and you bar them: and appoint watches of the inhabitants of Jerusalem, everyone in his watch, with everyone near his house."'),
  ('1e8c0baa-c0b4-5c99-a35b-66bebb7244c1', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 4, 4, 'Now the city was wide and large; but the people were few therein, and the houses were not built.'),
  ('8f45a21e-deee-549d-a889-978560d34c11', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 5, 5, 'My God put into my heart to gather together the nobles, and the rulers, and the people, that they might be reckoned by genealogy. I found the book of the genealogy of those who came up at the first, and I found written therein:'),
  ('ec016cba-a2c5-52f5-ade0-58bc1acfee39', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 6, 6, 'These are the children of the province, who went up out of the captivity of those who had been carried away, whom Nebuchadnezzar the king of Babylon had carried away, and who returned to Jerusalem and to Judah, everyone to his city;'),
  ('c238ccb1-5cbf-5096-a0da-d2af576a2521', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 7, 7, 'who came with Zerubbabel, Jeshua, Nehemiah, Azariah, Raamiah, Nahamani, Mordecai, Bilshan, Mispereth, Bigvai, Nehum, Baanah. The number of the men of the people of Israel:'),
  ('7e4b423e-199d-56ce-aff0-240dfcde632a', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 8, 8, 'The children of Parosh, two thousand one hundred seventy-two.'),
  ('e9d7966a-b21e-5646-a285-272c90452c81', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 9, 9, 'The children of Shephatiah, three hundred seventy-two.'),
  ('83c422f2-568e-5dbb-a6c1-e769f82ddaf9', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 10, 10, 'The children of Arah, six hundred fifty-two.'),
  ('dd85ea65-81ec-529f-ab95-f55520b99d02', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 11, 11, 'The children of Pahathmoab, of the children of Jeshua and Joab, two thousand eight hundred [and] eighteen.'),
  ('9db94f89-28d1-5495-aaf9-26090e0dea46', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 12, 12, 'The children of Elam, one thousand two hundred fifty-four.'),
  ('557076f9-e36b-5bdc-a1a1-46bb2712da6a', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 13, 13, 'The children of Zattu, eight hundred forty-five.'),
  ('6c339696-15fb-5775-aea3-a1e20a5001b0', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 14, 14, 'The children of Zaccai, seven hundred sixty.'),
  ('b50fdf82-38f9-525f-a92e-dc6e1624cc91', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 15, 15, 'The children of Binnui, six hundred forty-eight.'),
  ('249d9221-2263-52f5-a4ce-16f83ff39982', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 16, 16, 'The children of Bebai, six hundred twenty-eight.'),
  ('455ef473-248a-5c21-a170-fd29b5814947', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 17, 17, 'The children of Azgad, two thousand three hundred twenty-two.'),
  ('27b6ddb1-a6fc-590a-ade8-db4d95bdf338', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 18, 18, 'The children of Adonikam, six hundred sixty-seven.'),
  ('c45d55a4-9077-5c12-ae6a-c1e0d5196982', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 19, 19, 'The children of Bigvai, two thousand sixty-seven.'),
  ('3b87077b-71f0-5967-a23b-b3542aa1533d', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 20, 20, 'The children of Adin, six hundred fifty-five.'),
  ('0933cc1e-196f-5fe9-ab4f-e843f5971653', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 21, 21, 'The children of Ater, of Hezekiah, ninety-eight.'),
  ('bb37a72b-8142-5e1a-ac2b-ac2a636f8463', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 22, 22, 'The children of Hashum, three hundred Twenty-eight.'),
  ('86b016f3-cf39-5fa3-a411-bf88ac43a4ed', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 23, 23, 'The children of Bezai, three hundred twenty-four.'),
  ('4d4c3e73-5b81-5981-a94b-3602c6544fa9', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 24, 24, 'The children of Hariph, one hundred twelve.'),
  ('1477ca9c-f8d9-520f-a8c4-081791b8bad9', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 25, 25, 'The children of Gibeon, ninety-five.'),
  ('51a44cc4-ae15-57d2-a217-90e4eefe963e', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 26, 26, 'The men of Bethlehem and Netophah, one hundred eighty-eight.'),
  ('7fdc98f4-1943-5c78-a2f2-0bfab80f771e', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 27, 27, 'The men of Anathoth, one hundred twenty-eight.'),
  ('88b2e36b-258c-58c4-a62b-1b7ba9fab9a1', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 28, 28, 'The men of Beth Azmaveth, forty-two.'),
  ('253cf13f-cbd1-5798-ad38-9d6cafacbaf7', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 29, 29, 'The men of Kiriath Jearim, Chephirah, and Beeroth, seven hundred forty-three.'),
  ('e264b14b-453c-5c65-a709-b884fca24058', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 30, 30, 'The men of Ramah and Geba, six hundred twenty-one.'),
  ('e483a7dd-6c8f-5486-a85b-f69e2a7f0764', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 31, 31, 'The men of Michmas, one hundred and twenty-two.'),
  ('968d220d-1d54-51f9-ade8-678074bb1d92', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 32, 32, 'The men of Bethel and Ai, a hundred twenty-three.'),
  ('9bcc2f40-56c3-503f-ae4b-d092de765708', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 33, 33, 'The men of the other Nebo, fifty-two.'),
  ('e946f316-520c-5e38-aa18-2f7d00c8cfab', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 34, 34, 'The children of the other Elam, one thousand two hundred fifty-four.'),
  ('904c957a-945c-5d8e-a6f6-5c6259076558', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 35, 35, 'The children of Harim, three hundred twenty.'),
  ('7bbbbe8e-d64d-5609-ac66-1a0850c9ae03', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 36, 36, 'The children of Jericho, three hundred forty-five.'),
  ('f8d6e72d-7b72-5f23-aaf2-0e011b3d2c32', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 37, 37, 'The children of Lod, Hadid, and Ono, seven hundred twenty-one.'),
  ('817f7cc0-288e-5358-a905-2fb5a6457129', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 38, 38, 'The children of Senaah, three thousand nine hundred thirty.'),
  ('f3ec1419-426c-5841-aa7a-c9f35d6be6d4', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 39, 39, 'The priests: The children of Jedaiah, of the house of Jeshua, nine hundred seventy-three.'),
  ('823f5dea-ba45-52ed-abc0-36cdff086410', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 40, 40, 'The children of Immer, one thousand fifty-two.'),
  ('7ee90663-545e-55be-a074-8ad9e66cd5f9', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 41, 41, 'The children of Pashhur, one thousand two hundred forty-seven.'),
  ('757760fc-6bd2-5e87-a4f6-741cab88098a', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 42, 42, 'The children of Harim, one thousand [and] seventeen.'),
  ('d3edf77c-e763-5f3a-a9fd-22e5d7ec047f', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 43, 43, 'The Levites: the children of Jeshua, of Kadmiel, of the children of Hodevah, seventy-four.'),
  ('60b2b04c-7e47-51b4-ac01-ae63ea073e5c', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 44, 44, 'The singers: the children of Asaph, one hundred forty-eight.'),
  ('e199a747-79f2-51be-a9fe-3074c34bbef4', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 45, 45, 'The porters: the children of Shallum, the children of Ater, the children of Talmon, the children of Akkub, the children of Hatita, the children of Shobai, one hundred thirty-eight.'),
  ('4afe6855-b12c-56d8-a0f1-d5834e189c42', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 46, 46, 'The Nethinim: the children of Ziha, the children of Hasupha, the children of Tabbaoth,'),
  ('89ecb8d7-b6e9-5fbe-a868-039a04d18904', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 47, 47, 'the children of Keros, the children of Sia, the children of Padon,'),
  ('bd173d86-622a-55dc-a25a-515619f6d73f', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 48, 48, 'the children of Lebana, the children of Hagaba, the children of Salmai,'),
  ('5e545153-8ae7-5ee2-a07a-f9c0cdd4a086', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 49, 49, 'the children of Hanan, the children of Giddel, the children of Gahar,'),
  ('346faf8d-25ca-5121-a374-99a662ee5188', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 50, 50, 'the children of Reaiah, the children of Rezin, the children of Nekoda,'),
  ('052677ee-aa63-5d2f-ae0d-988c1a70a497', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 51, 51, 'the children of Gazzam, the children of Uzza, the children of Paseah.'),
  ('54da7553-7b91-5dad-a568-20632afafaa3', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 52, 52, 'The children of Besai, the children of Meunim, the children of Nephushesim,'),
  ('58b4f3f6-ba65-5eaf-ad0a-a57813136c3a', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 53, 53, 'the children of Bakbuk, the children of Hakupha, the children of Harhur,'),
  ('e20fd668-2360-5a73-abdf-29661879b1e2', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 54, 54, 'the children of Bazlith, the children of Mehida, the children of Harsha,'),
  ('3dd57191-21b8-512d-a7d5-c8fbfa928d19', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 55, 55, 'the children of Barkos, the children of Sisera, the children of Temah,'),
  ('531873a0-658f-52e1-a270-6d90dca65f6c', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 56, 56, 'the children of Neziah, the children of Hatipha.'),
  ('9fd538aa-291e-584f-a8f6-21cb5043b6f4', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 57, 57, 'The children of Solomon''s servants: the children of Sotai, the children of Sophereth, the children of Perida,'),
  ('930fad0f-b961-5a4c-ad6b-e6b05af69ee6', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 58, 58, 'the children of Jaala, the children of Darkon, the children of Giddel,'),
  ('d2496b15-6f1b-572e-a90e-4a93f4dcbf54', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 59, 59, 'the children of Shephatiah, the children of Hattil, the children of Pochereth Hazzebaim, the children of Amon.'),
  ('cedaa69d-3790-5372-aab0-e526301d1866', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 60, 60, 'All the Nethinim, and the children of Solomon''s servants, were three hundred ninety-two.'),
  ('1621769b-37f1-5040-aaa9-19d758a5249b', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 61, 61, 'These were those who went up from Tel Melah, Tel Harsha, Cherub, Addon, and Immer; but they could not show their fathers'' houses, nor their seed, whether they were of Israel:'),
  ('851a9460-d2c6-55e7-a494-47f4000a532b', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 62, 62, 'The children of Delaiah, the children of Tobiah, the children of Nekoda, six hundred forty-two.'),
  ('b9e12534-97a5-5c1a-a62c-748a26a9a563', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 63, 63, 'Of the priests: the children of Hobaiah, the children of Hakkoz, the children of Barzillai, who took a wife of the daughters of Barzillai the Gileadite, and was called after their name.'),
  ('9a949606-faee-52de-a08a-48d62932c00b', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 64, 64, 'These sought their register [among] those who were reckoned by genealogy, but it was not found: therefore were they deemed polluted and put from the priesthood.'),
  ('da9a6c23-f825-588e-ac1a-3ad25dfa3eff', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 65, 65, 'The governor said to them, that they should not eat of the most holy things, until there stood up a priest with Urim and Thummim.'),
  ('831773ef-fdd8-5ec6-a4c8-cb8fbd423713', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 66, 66, 'The whole assembly together was forty-two thousand three hundred sixty,'),
  ('b70153bd-bb4a-5d10-accf-d9660c956f9b', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 67, 67, 'besides their male servants and their female servants, of whom there were seven thousand three hundred thirty-seven: and they had two hundred forty-five singing men and singing women.'),
  ('67d63768-7c51-5d50-a549-5a059dd8b87a', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 68, 68, 'Their horses were seven hundred thirty-six; their mules, two hundred forty-five;'),
  ('22bcda44-3039-56cd-a67b-01333c4f3028', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 69, 69, '[their] camels, four hundred thirty-five; [their] donkeys, six thousand seven hundred twenty.'),
  ('828ee1ea-13e4-5857-aee4-160d6b4b184d', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 70, 70, 'Some from among the heads of fathers'' [houses] gave to the work. The governor gave to the treasury one thousand darics of gold, fifty basins, and five hundred thirty priests'' garments.'),
  ('145201bb-1745-52db-a452-fdd1229516b2', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 71, 71, 'Some of the heads of fathers'' [houses] gave into the treasury of the work twenty thousand darics of gold, and two thousand two hundred minas of silver.'),
  ('e2fae3a6-e6eb-5a03-a487-11deeaa2270a', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 72, 72, 'That which the rest of the people gave was twenty thousand darics of gold, and two thousand minas of silver, and sixty-seven priests'' garments.'),
  ('6b457296-7bf4-50b1-a6bb-444870e942d8', '9501fa0f-36d8-554e-a87d-569fa2e780a7', NULL, 73, 73, 'So the priests, and the Levites, and the porters, and the singers, and some of the people, and the Nethinim, and all Israel, lived in their cities. When the seventh month was come, the children of Israel were in their cities.'),
  ('487de5db-45e0-507b-ae30-5f36e97757ae', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 1, 1, 'All the people gathered themselves together as one man into the broad place that was before the water gate; and they spoke to Ezra the scribe to bring the book of the law of Moses, which Yahweh had commanded to Israel.'),
  ('0b9e5125-cdbf-5274-a60d-eaf83b8c6277', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 2, 2, 'Ezra the priest brought the law before the assembly, both men and women, and all who could hear with understanding, on the first day of the seventh month.'),
  ('c727335a-3946-5d10-a185-d3d42b68cecc', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 3, 3, 'He read therein before the broad place that was before the water gate from early morning until midday, in the presence of the men and the women, and of those who could understand; and the ears of all the people were [attentive] to the book of the law.'),
  ('62f3c3fa-bb6a-5bfd-a61f-bce72667de49', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 4, 4, 'Ezra the scribe stood on a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Uriah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchijah, and Hashum, and Hashbaddanah, Zechariah, [and] Meshullam.'),
  ('42ea5185-ecab-50f1-abcc-6dc76abc97fa', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 5, 5, 'Ezra opened the book in the sight of all the people; (for he was above all the people;) and when he opened it, all the people stood up:'),
  ('19fe4dee-82d7-5d74-a525-28112c5ff187', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 6, 6, 'and Ezra blessed Yahweh, the great God. All the people answered, "Amen, Amen," with the lifting up of their hands. They bowed their heads, and worshiped Yahweh with their faces to the ground.'),
  ('85375819-ec25-5418-afc7-d7d6b0a3a834', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 7, 7, 'Also Jeshua, and Bani, and Sherebiah, Jamin, Akkub, Shabbethai, Hodiah, Maaseiah, Kelita, Azariah, Jozabad, Hanan, Pelaiah, and the Levites, caused the people to understand the law: and the people [stood] in their place.'),
  ('224c4289-2664-5439-a7a2-73c8b4b8a294', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 8, 8, 'They read in the book, in the law of God, distinctly; and they gave the sense, so that they understood the reading.'),
  ('8606e0ba-346c-5296-a684-3fe44841e952', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 9, 9, 'Nehemiah, who was the governor, and Ezra the priest the scribe, and the Levites who taught the people, said to all the people, "This day is holy to Yahweh your God. Don''t mourn, nor weep." For all the people wept, when they heard the words of the law.'),
  ('aabca9eb-a76a-5250-ab37-439504aa7d33', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 10, 10, 'Then he said to them, "Go your way. Eat the fat, drink the sweet, and send portions to him for whom nothing is prepared; for this day is holy to our Lord. Don''t be grieved; for the joy of Yahweh is your strength."'),
  ('a4f05262-a8c1-5e65-abd3-3817f7809ae8', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 11, 11, 'So the Levites stilled all the people, saying, "Hold your peace, for the day is holy; neither be grieved."'),
  ('24804c7d-2a9e-53d3-a7c0-fce93c8631b4', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 12, 12, 'All the people went their way to eat, and to drink, and to send portions, and to make great mirth, because they had understood the words that were declared to them.'),
  ('9a6c6f1a-e54a-5103-a2da-4808c3533930', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 13, 13, 'On the second day were gathered together the heads of fathers'' [houses] of all the people, the priests, and the Levites, to Ezra the scribe, even to give attention to the words of the law.'),
  ('962c9403-4b56-52aa-af98-daa4004bce4f', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 14, 14, 'They found written in the law, how that Yahweh had commanded by Moses, that the children of Israel should dwell in booths in the feast of the seventh month;'),
  ('cd7b94bb-cc46-5dda-abb1-32aa114e6b79', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 15, 15, 'and that they should publish and proclaim in all their cities, and in Jerusalem, saying, "Go out to the mountain, and get olive branches, and branches of wild olive, and myrtle branches, and palm branches, and branches of thick trees, to make booths, as it is written."'),
  ('51f40905-4356-5172-ac72-3b45310273a7', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 16, 16, 'So the people went out, and brought them, and made themselves booths, everyone on the roof of his house, and in their courts, and in the courts of the house of God, and in the broad place of the water gate, and in the broad place of the gate of Ephraim.'),
  ('9c3ce7d7-8005-5b77-aed8-73eee090b6b0', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 17, 17, 'All the assembly of those who were come again out of the captivity made booths, and lived in the booths; for since the days of Jeshua the son of Nun to that day the children of Israel had not done so. There was very great gladness.'),
  ('9a73823e-ad30-5229-a1b7-2422359c862c', '46e28a58-7a8e-56c5-a9c8-b4ac0a2de8a7', NULL, 18, 18, 'Also day by day, from the first day to the last day, he read in the book of the law of God. They kept the feast seven days; and on the eighth day was a solemn assembly, according to the ordinance.'),
  ('850b67e1-4d10-575f-aeac-1ee7a4da0c49', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 1, 1, 'Now in the twenty-fourth day of this month the children of Israel were assembled with fasting, and with sackcloth, and earth on them.'),
  ('eb193430-7715-55f2-a1ae-721530f74322', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 2, 2, 'The seed of Israel separated themselves from all foreigners, and stood and confessed their sins, and the iniquities of their fathers.'),
  ('83a14cd0-c11a-5de8-aa28-dcab88769d7e', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 3, 3, 'They stood up in their place, and read in the book of the law of Yahweh their God a fourth part of the day; and [another] fourth part they confessed, and worshiped Yahweh their God.'),
  ('1d08c78f-60c4-5375-a831-b5a7fc06e013', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 4, 4, 'Then stood up on the stairs of the Levites, Jeshua, and Bani, Kadmiel, Shebaniah, Bunni, Sherebiah, Bani, [and] Chenani, and cried with a loud voice to Yahweh their God.'),
  ('a3b62b88-c473-59ea-a32e-a567f48c9f0c', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 5, 5, 'Then the Levites, Jeshua, and Kadmiel, Bani, Hashabneiah, Sherebiah, Hodiah, Shebaniah, [and] Pethahiah, said, "Stand up and bless Yahweh your God from everlasting to everlasting! Bessed be your glorious name, which is exalted above all blessing and praise!'),
  ('78dde104-dfd0-502b-a9af-4cc68ad968e4', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 6, 6, 'You are Yahweh, even you alone. You have made heaven, the heaven of heavens, with all their army, the earth and all things that are on it, the seas and all that is in them, and you preserve them all. The army of heaven worships you.'),
  ('c997e5b7-10f6-5a29-a3fc-dbd762d91038', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 7, 7, 'You are Yahweh, the God who chose Abram, and brought him out of Ur of the Chaldees, and gave him the name of Abraham,'),
  ('27eb8bb5-da26-5d71-a927-a153e8af3fb7', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 8, 8, 'and found his heart faithful before you, and made a covenant with him to give the land of the Canaanite, the Hittite, the Amorite, and the Perizzite, and the Jebusite, and the Girgashite, to give it to his seed, and have performed your words; for you are righteous.'),
  ('3ad0f260-fc66-5a76-a7f4-8e62dabeb0e8', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 9, 9, '"You saw the affliction of our fathers in Egypt, and heard their cry by the Red Sea,'),
  ('1b25d21f-492e-5cc9-a2a8-67a9e5b43b0d', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 10, 10, 'and showed signs and wonders against Pharaoh, and against all his servants, and against all the people of his land; for you knew that they dealt proudly against them, and made a name for yourself, as it is this day.'),
  ('096cacfc-5813-5e9c-a32a-f06e46c3db7d', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 11, 11, 'You divided the sea before them, so that they went through the midst of the sea on the dry land; and you cast their pursuers into the depths, as a stone into the mighty waters.'),
  ('38f535fb-c08c-5eff-a481-26697767e83b', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 12, 12, 'Moreover, in a pillar of cloud you led them by day; and in a pillar of fire by night, to give them light in the way in which they should go.'),
  ('476c7514-3284-559d-a7fe-34e08a5906c6', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 13, 13, '"You came down also on Mount Sinai, and spoke with them from heaven, and gave them right ordinances and true laws, good statutes and commandments,'),
  ('7a92f623-eb71-584d-a282-d6a5fce4a971', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 14, 14, 'and made known to them your holy Sabbath, and commanded them commandments, and statutes, and a law, by Moses your servant,'),
  ('e0eff065-8d11-51c9-a1ef-b61d72ebe606', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 15, 15, 'and gave them bread from the sky for their hunger, and brought forth water for them out of the rock for their thirst, and commanded them that they should go in to possess the land which you had sworn to give them.'),
  ('f67e886a-5309-503e-a5fd-13448bf21498', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 16, 16, '"But they and our fathers dealt proudly and hardened their neck, didn''t listen to your commandments,'),
  ('c358e509-b64f-536e-a344-e8aef87a232a', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 17, 17, 'and refused to obey, neither were they mindful of your wonders that you did among them, but hardened their neck, and in their rebellion appointed a captain to return to their bondage. But you are a God ready to pardon, gracious and merciful, slow to anger, and abundant in loving kindness, and didn''t forsake them.'),
  ('36a30d8e-586f-5d45-a1af-e6451297bc6b', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 18, 18, 'Yes, when they had made them a molten calf, and said, ''This is your God who brought you up out of Egypt,'' and had committed awful blasphemies;'),
  ('03fe394e-1aa8-5de7-aecc-b073adf47c46', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 19, 19, 'yet you in your manifold mercies didn''t forsake them in the wilderness: the pillar of cloud didn''t depart from over them by day, to lead them in the way; neither the pillar of fire by night, to show them light, and the way in which they should go.'),
  ('48e34ee0-c57d-5636-a88d-14e970532f54', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 20, 20, 'You gave also your good Spirit to instruct them, and didn''t withhold your manna from their mouth, and gave them water for their thirst.'),
  ('88a85994-38b1-5e59-a1e6-6269b9b114f9', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 21, 21, '"Yes, forty years you sustained them in the wilderness. They lacked nothing. Their clothes didn''t grow old, and their feet didn''t swell.'),
  ('1524f00f-313e-5b26-a249-3b553e58b89a', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 22, 22, 'Moreover you gave them kingdoms and peoples, which you allotted according to their portions. So they possessed the land of Sihon, even the land of the king of Heshbon, and the land of Og king of Bashan.'),
  ('661a822b-9fd5-5021-ae9f-b9585dd5a295', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 23, 23, 'You also multiplied their children as the stars of the sky, and brought them into the land concerning which you said to their fathers, that they should go in to possess it.'),
  ('9969122b-2018-5918-a468-f49370240b3b', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 24, 24, '"So the children went in and possessed the land, and you subdued before them the inhabitants of the land, the Canaanites, and gave them into their hands, with their kings, and the peoples of the land, that they might do with them as they pleased.'),
  ('9c7e8c0a-3366-5b75-a8c5-af10e9b4ad0e', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 25, 25, 'They took fortified cities, and a rich land, and possessed houses full of all good things, cisterns dug out, vineyards, and olive groves, and fruit trees in abundance. So they ate, were filled, became fat, and delighted themselves in your great goodness.'),
  ('e0f000d9-0992-5bdd-a6a4-0e4e7458b922', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 26, 26, '"Nevertheless they were disobedient, and rebelled against you, and cast your law behind their back, and killed your prophets that testified against them to turn them again to you, and they committed awful blasphemies.'),
  ('190e3c3c-8e5c-583d-a807-74198c215fb0', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 27, 27, 'Therefore you delivered them into the hand of their adversaries, who distressed them. In the time of their trouble, when they cried to you, you heard from heaven; and according to your manifold mercies you gave them saviors who saved them out of the hand of their adversaries.'),
  ('e532c7ff-0177-5f19-ad85-e58d7240159c', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 28, 28, 'But after they had rest, they did evil again before you; therefore left you them in the hand of their enemies, so that they had the dominion over them; yet when they returned, and cried to you, you heard from heaven; and many times you delivered them according to your mercies,'),
  ('efce0b7c-3d70-5c8d-a3f7-11cb4c13a106', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 29, 29, 'and testified against them, that you might bring them again to your law. Yet they dealt proudly, and didn''t listen to your commandments, but sinned against your ordinances, (which if a man does, he shall live in them), turned their backs, stiffened their neck, and would not hear.'),
  ('81cb1f18-e741-5dcd-a8ed-f41995f9cd83', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 30, 30, 'Yet many years you put up with them, and testified against them by your Spirit through your prophets. Yet would they not give ear. Therefore you gave them into the hand of the peoples of the lands.'),
  ('07039058-01dd-558f-ad22-5e0e0cf47701', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 31, 31, '"Nevertheless in your manifold mercies you did not make a full end of them, nor forsake them; for you are a gracious and merciful God.'),
  ('7977294a-d97b-5f45-a496-c71489e8e40b', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 32, 32, 'Now therefore, our God, the great, the mighty, and the awesome God, who keeps covenant and loving kindness, don''t let all the travail seem little before you, that has come on us, on our kings, on our princes, and on our priests, and on our prophets, and on our fathers, and on all your people, since the time of the kings of Assyria to this day.'),
  ('984f25ce-02a7-5878-ac57-f41eb32e0745', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 33, 33, 'However you are just in all that is come on us; for you have dealt truly, but we have done wickedly;'),
  ('b12640cf-b5f1-5f4c-a0d5-a0b9f397e212', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 34, 34, 'neither have our kings, our princes, our priests, nor our fathers, kept your law, nor listened to your commandments and your testimonies with which you testified against them.'),
  ('88c0ea8e-b34c-518c-aa34-668885530543', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 35, 35, 'For they have not served you in their kingdom, and in your great goodness that you gave them, and in the large and rich land which you gave before them, neither did they turn from their wicked works.'),
  ('792de86c-1568-500b-a88c-2d5ef0d40584', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 36, 36, '"Behold, we are servants this day, and as for the land that you gave to our fathers to eat its fruit and its good, behold, we are servants in it.'),
  ('fc913037-acce-5444-a500-d0e2779a571f', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 37, 37, 'It yields much increase to the kings whom you have set over us because of our sins: also they have power over our bodies, and over our livestock, at their pleasure, and we are in great distress.'),
  ('2832eb2f-6429-5983-a677-f860d89f5864', '7fede171-c5a5-5ab1-a2d8-ae913b4d0afd', NULL, 38, 38, 'Yet for all this, we make a sure covenant, and write it; and our princes, our Levites, [and] our priests, seal to it."'),
  ('7e96605c-28f4-51cd-aa35-dc8b1d481b24', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 1, 1, 'Now those who sealed were: Nehemiah the governor, the son of Hacaliah, and Zedekiah,'),
  ('4fbc6b34-4e85-5654-a20f-4dbecbcc6ff8', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 2, 2, 'Seraiah, Azariah, Jeremiah,'),
  ('eb236ca6-1eb8-52e4-a815-84acb6f819c6', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 3, 3, 'Pashhur, Amariah, Malchijah,'),
  ('8affea29-1f5c-5634-a452-b16f6abc042f', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 4, 4, 'Hattush, Shebaniah, Malluch,'),
  ('d76ba01c-2749-5109-a7ee-b85dd987b01f', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 5, 5, 'Harim, Meremoth, Obadiah,'),
  ('5b225949-bfd7-5d2c-a42c-621a5043512b', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 6, 6, 'Daniel, Ginnethon, Baruch,'),
  ('073b2c16-0212-52fa-afde-59ee9968681f', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 7, 7, 'Meshullam, Abijah, Mijamin,'),
  ('65934c32-da26-5720-a20d-3dee505c055a', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 8, 8, 'Maaziah, Bilgai, Shemaiah; these were the priests.'),
  ('bef30916-b56d-5886-aa53-8e06e230aee9', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 9, 9, 'The Levites: namely, Jeshua the son of Azaniah, Binnui of the sons of Henadad, Kadmiel;'),
  ('40b8830e-3250-5af8-a628-633401d079b4', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 10, 10, 'and their brothers, Shebaniah, Hodiah, Kelita, Pelaiah, Hanan,'),
  ('01d7bf34-fff2-529d-af18-89308c31395f', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 11, 11, 'Mica, Rehob, Hashabiah,'),
  ('20c59f80-b8ae-5007-ab8a-dc44c1e36f38', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 12, 12, 'Zaccur, Sherebiah, Shebaniah,'),
  ('23ca9436-0ea5-547f-aba2-f16b82977539', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 13, 13, 'Hodiah, Bani, Beninu.'),
  ('bd5f6e30-ad8f-5e60-aa41-c8a074ee3bfb', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 14, 14, 'The chiefs of the people: Parosh, Pahathmoab, Elam, Zattu, Bani,'),
  ('79723dbf-273f-5ee4-aba7-453f55016695', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 15, 15, 'Bunni, Azgad, Bebai,'),
  ('9f6869ce-40d4-5ad1-a537-214ff579a470', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 16, 16, 'Adonijah, Bigvai, Adin,'),
  ('93eb0c0d-f048-573f-a4dc-a18f592534d7', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 17, 17, 'Ater, Hezekiah, Azzur,'),
  ('5b40cbe7-425b-563f-aac0-ed0868903490', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 18, 18, 'Hodiah, Hashum, Bezai,'),
  ('bb8e85cf-e8f4-5395-a68e-8f23e089024b', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 19, 19, 'Hariph, Anathoth, Nobai,'),
  ('b56248c0-1120-5fa3-afa0-463995df89eb', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 20, 20, 'Magpiash, Meshullam, Hezir,'),
  ('5310bb42-f454-5117-aa1c-63f542cf1b05', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 21, 21, 'Meshezabel, Zadok, Jaddua,'),
  ('08ebee08-21f7-5e4b-a17f-2bf39c1d244b', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 22, 22, 'Pelatiah, Hanan, Anaiah,'),
  ('eefb1f73-880b-5d2a-a87c-e76eff102172', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 23, 23, 'Hoshea, Hananiah, Hasshub,'),
  ('24c6208b-7c25-50dc-aa9b-d5bc5a1f9357', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 24, 24, 'Hallohesh, Pilha, Shobek,'),
  ('dfe9ee37-297d-5ace-a5f1-bb2bacb773c3', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 25, 25, 'Rehum, Hashabnah, Maaseiah,'),
  ('08ca11a3-ca20-5117-a4d0-b1cdbe39c80c', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 26, 26, 'and Ahiah, Hanan, Anan,'),
  ('80800f2c-68c3-52e1-a78b-9b0f672498fe', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 27, 27, 'Malluch, Harim, Baanah.'),
  ('4ee7e736-6e52-5242-a872-0a7514f5e51b', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 28, 28, 'The rest of the people, the priests, the Levites, the porters, the singers, the Nethinim, and all those who had separated themselves from the peoples of the lands to the law of God, their wives, their sons, and their daughters, everyone who had knowledge, and understanding--'),
  ('36b60c6d-a7bb-5f06-a78c-180bdfc7851c', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 29, 29, 'they joined with their brothers, their nobles, and entered into a curse, and into an oath, to walk in God''s law, which was given by Moses the servant of God, and to observe and do all the commandments of Yahweh our Lord, and his ordinances and his statutes;'),
  ('33e50e3e-3a35-57ea-a8c3-4208af6f244f', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 30, 30, 'and that we would not give our daughters to the peoples of the land, nor take their daughters for our sons;'),
  ('8b4a7e39-14fc-521a-a221-9d1a4753ef0d', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 31, 31, 'and if the peoples of the land bring wares or any grain on the Sabbath day to sell, that we would not buy of them on the Sabbath, or on a holy day; and that we would forego the seventh year, and the exaction of every debt.'),
  ('59f42028-4696-58bd-ab47-25b637e17c1e', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 32, 32, 'Also we made ordinances for ourselves, to charge ourselves yearly with the third part of a shekel for the service of the house of our God;'),
  ('61686fe7-51ba-5488-aa1e-6a22fdd193c2', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 33, 33, 'for the show bread, and for the continual meal offering, and for the continual burnt offering, for the Sabbaths, for the new moons, for the set feasts, and for the holy things, and for the sin offerings to make atonement for Israel, and for all the work of the house of our God.'),
  ('402ef866-2a6c-51a2-a3cd-b89e7e464f90', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 34, 34, 'We cast lots, the priests, the Levites, and the people, for the wood offering, to bring it into the house of our God, according to our fathers'' houses, at times appointed, year by year, to burn on the altar of Yahweh our God, as it is written in the law;'),
  ('b4142cca-ff86-5fa7-ac2e-7637e5dc4b1d', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 35, 35, 'and to bring the first fruits of our ground, and the first fruits of all fruit of all kinds of trees, year by year, to the house of Yahweh;'),
  ('b09806eb-b576-5b54-ad10-b64618facaea', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 36, 36, 'also the firstborn of our sons, and of our livestock, as it is written in the law, and the firstborn of our herds and of our flocks, to bring to the house of our God, to the priests who minister in the house of our God;'),
  ('56215ae4-8902-5576-ad2f-dd67f7582c56', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 37, 37, 'and that we should bring the first fruits of our dough, and our wave offerings, and the fruit of all kinds of trees, the new wine and the oil, to the priests, to the rooms of the house of our God; and the tithes of our ground to the Levites; for they, the Levites, take the tithes in all the cities of our tillage.'),
  ('c2117328-bac6-5910-a7ed-c10c70d02703', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 38, 38, 'The priest the son of Aaron shall be with the Levites, when the Levites take tithes: and the Levites shall bring up the tithe of the tithes to the house of our God, to the rooms, into the treasure house.'),
  ('102bb142-1fb5-58be-a145-2fc547513ae7', '82efac08-4e91-5810-a3ea-0a229359a8b6', NULL, 39, 39, 'For the children of Israel and the children of Levi shall bring the wave offering of the grain, of the new wine, and of the oil, to the rooms, where are the vessels of the sanctuary, and the priests who minister, and the porters, and the singers. We will not forsake the house of our God.'),
  ('5d544094-6fe6-513f-a4d5-ecab92bda9c2', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 1, 1, 'The princes of the people lived in Jerusalem: the rest of the people also cast lots, to bring one of ten to dwell in Jerusalem the holy city, and nine parts in the [other] cities.'),
  ('52a5d9d7-115b-5b30-a79b-34f9160771b5', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 2, 2, 'The people blessed all the men who willingly offered themselves to dwell in Jerusalem.'),
  ('01397603-d6e5-5f41-a687-d94a6ffc8254', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 3, 3, 'Now these are the chiefs of the province who lived in Jerusalem: but in the cities of Judah lived everyone in his possession in their cities, [to wit], Israel, the priests, and the Levites, and the Nethinim, and the children of Solomon''s servants.'),
  ('56365185-c7c2-5da3-aa40-85fc01bd0de5', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 4, 4, 'In Jerusalem lived certain of the children of Judah, and of the children of Benjamin. Of the children of Judah: Athaiah the son of Uzziah, the son of Zechariah, the son of Amariah, the son of Shephatiah, the son of Mahalalel, of the children of Perez;'),
  ('270b5e83-57e1-5d31-a484-d3e593afe857', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 5, 5, 'and Maaseiah the son of Baruch, the son of Colhozeh, the son of Hazaiah, the son of Adaiah, the son of Joiarib, the son of Zechariah, the son of the Shilonite.'),
  ('e5e76cf6-1cb6-566c-adf1-0eb7bc289f47', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 6, 6, 'All the sons of Perez who lived in Jerusalem were four hundred sixty-eight valiant men.'),
  ('89126dfc-f3ca-5027-a20e-6208fc566dac', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 7, 7, 'These are the sons of Benjamin: Sallu the son of Meshullam, the son of Joed, the son of Pedaiah, the son of Kolaiah, the son of Maaseiah, the son of Ithiel, the son of Jeshaiah.'),
  ('4cb71a5a-a33d-564b-a4c7-0108c347a28f', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 8, 8, 'After him Gabbai, Sallai, nine hundred twenty-eight.'),
  ('7a8849f8-6552-5b99-ac25-7a0af13c9d19', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 9, 9, 'Joel the son of Zichri was their overseer; and Judah the son of Hassenuah was second over the city.'),
  ('c878ce75-1c7e-5cf3-adf3-04fb473e704b', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 10, 10, 'Of the priests: Jedaiah the son of Joiarib, Jachin,'),
  ('76016895-db2a-5c9d-a4e1-4051ae7bd77e', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 11, 11, 'Seraiah the son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, the ruler of the house of God,'),
  ('dfda796d-f54a-5b83-afae-2d16f884757e', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 12, 12, 'and their brothers who did the work of the house, eight hundred twenty-two; and Adaiah the son of Jeroham, the son of Pelaliah, the son of Amzi, the son of Zechariah, the son of Pashhur, the son of Malchijah,'),
  ('036cb2b0-4f01-553c-af59-ee6ced6a768f', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 13, 13, 'and his brothers, chiefs of fathers'' [houses], two hundred forty-two; and Amashsai the son of Azarel, the son of Ahzai, the son of Meshillemoth, the son of Immer,'),
  ('3dcc5002-ac9d-5a25-abd2-ecbb60e914c2', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 14, 14, 'and their brothers, mighty men of valor, one hundred twenty-eight; and their overseer was Zabdiel, the son of Haggedolim.'),
  ('164ed899-fdce-50b2-ad95-8d516c32b3ad', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 15, 15, 'Of the Levites: Shemaiah the son of Hasshub, the son of Azrikam, the son of Hashabiah, the son of Bunni;'),
  ('bd14c2b7-4244-51c5-a5f0-614762771cdc', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 16, 16, 'and Shabbethai and Jozabad, of the chiefs of the Levites, who had the oversight of the outward business of the house of God;'),
  ('23d12481-c9c1-5aa3-a47a-2e7a4f910fd2', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 17, 17, 'and Mattaniah the son of Mica, the son of Zabdi, the son of Asaph, who was the chief to begin the thanksgiving in prayer, and Bakbukiah, the second among his brothers; and Abda the son of Shammua, the son of Galal, the son of Jeduthun.'),
  ('988b19fa-f3fb-5be1-a872-598a47b95a43', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 18, 18, 'All the Levites in the holy city were two hundred eighty-four.'),
  ('3ac94c9a-1904-558d-a0da-502e2a070b90', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 19, 19, 'Moreover the porters, Akkub, Talmon, and their brothers, who kept watch at the gates, were one hundred seventy-two.'),
  ('27e41eb1-6252-514a-ae89-7ec654d81972', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 20, 20, 'The residue of Israel, of the priests, the Levites, were in all the cities of Judah, everyone in his inheritance.'),
  ('3fcc1b45-8b09-51fb-aea6-6fdfffbccffb', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 21, 21, 'But the Nethinim lived in Ophel: and Ziha and Gishpa were over the Nethinim.'),
  ('c2117fec-3ec2-566e-ace3-432ece1be03e', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 22, 22, 'The overseer also of the Levites at Jerusalem was Uzzi the son of Bani, the son of Hashabiah, the son of Mattaniah, the son of Mica, of the sons of Asaph, the singers, over the business of the house of God.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('6294e71c-3cff-5094-ad9a-1849b3b8865a', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 23, 23, 'For there was a commandment from the king concerning them, and a settled provision for the singers, as every day required.'),
  ('ad626fa7-6dc4-5d23-a1a6-74abb7356c6d', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 24, 24, 'Pethahiah the son of Meshezabel, of the children of Zerah the son of Judah, was at the king''s hand in all matters concerning the people.'),
  ('8feea7e5-e2dd-5d21-aedc-d3cfbb40ce90', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 25, 25, 'As for the villages, with their fields, some of the children of Judah lived in Kiriath Arba and its towns, and in Dibon and its towns, and in Jekabzeel and its villages,'),
  ('510ada3e-5d47-5393-a9dc-fceee799195e', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 26, 26, 'and in Jeshua, and in Moladah, and Beth Pelet,'),
  ('155020e3-6062-51dd-a52b-e538c99520e6', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 27, 27, 'and in Hazar Shual, and in Beersheba and its towns,'),
  ('efeaa4fa-6b09-5257-a5e7-d22a0695be56', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 28, 28, 'and in Ziklag, and in Meconah and in its towns,'),
  ('a34ec556-2955-585d-aaa5-ebd770faad54', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 29, 29, 'and in En Rimmon, and in Zorah, and in Jarmuth,'),
  ('1454fcf3-20f0-5a6b-a828-73229e9920da', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 30, 30, 'Zanoah, Adullam, and their villages, Lachish and its fields, Azekah and its towns. So they encamped from Beersheba to the valley of Hinnom.'),
  ('f2c85a3b-2c32-5a9f-a30f-0b7caf34bd22', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 31, 31, 'The children of Benjamin also [lived] from Geba [onward], at Michmash and Aija, and at Bethel and its towns,'),
  ('6d309821-e98d-563e-ae28-4c1aef96b2be', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 32, 32, 'at Anathoth, Nob, Ananiah,'),
  ('608fa4b5-f9e8-52cf-a5d6-0a9888a969a2', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 33, 33, 'Hazor, Ramah, Gittaim,'),
  ('39da7561-7ad4-5437-a3a4-16828bed1f83', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 34, 34, 'Hadid, Zeboim, Neballat,'),
  ('502e343a-b03a-5c5d-ac83-bb8f36508e80', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 35, 35, 'Lod, and Ono, the valley of craftsmen.'),
  ('76379fc0-73e1-54f1-ac9d-31a72036b802', 'b8ef0a3c-9764-571c-a61a-a06dfafed2c8', NULL, 36, 36, 'Of the Levites, certain divisions in Judah [were joined] to Benjamin.'),
  ('c82f4f84-0e55-52a6-a35d-00f1ae44b1df', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 1, 1, 'Now these are the priests and the Levites who went up with Zerubbabel the son of Shealtiel, and Jeshua: Seraiah, Jeremiah, Ezra,'),
  ('f6c3ec1f-0764-536a-a719-fc5c554b2d0b', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 2, 2, 'Amariah, Malluch, Hattush,'),
  ('fa8f55bb-3787-5fbc-a3fe-c60e5ad30591', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 3, 3, 'Shecaniah, Rehum, Meremoth,'),
  ('662cbace-9545-523e-a0af-8eea9836a5ba', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 4, 4, 'Iddo, Ginnethoi, Abijah,'),
  ('ba2a1e9b-b93f-534e-abee-db49ff1e289f', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 5, 5, 'Mijamin, Maadiah, Bilgah,'),
  ('ef47095d-0788-5b19-a150-80541c9eaf4c', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 6, 6, 'Shemaiah, and Joiarib, Jedaiah.'),
  ('0de994a8-896a-509e-a0e2-5974bbad28d5', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 7, 7, 'Sallu, Amok, Hilkiah, Jedaiah. These were the chiefs of the priests and of their brothers in the days of Jeshua.'),
  ('7ab43364-2ed0-56ec-a408-4a790792ad81', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 8, 8, 'Moreover the Levites: Jeshua, Binnui, Kadmiel, Sherebiah, Judah, [and] Mattaniah, who was over the thanksgiving, he and his brothers.'),
  ('f927b5ab-ce0e-52f6-af81-1ab5ddda46a7', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 9, 9, 'Also Bakbukiah and Unno, their brothers, were over against them according to their offices.'),
  ('ea3a1cd3-e156-5884-a5b3-dda6ffbafa06', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 10, 10, 'Jeshua became the father of Joiakim, and Joiakim became the father of Eliashib, and Eliashib became the father of Joiada,'),
  ('c2f4dd52-88ed-576b-adde-93c00f794eb8', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 11, 11, 'and Joiada became the father of Jonathan, and Jonathan became the father of Jaddua.'),
  ('07e22d71-4923-590a-a485-8034b9c4c499', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 12, 12, 'In the days of Joiakim were priests, heads of fathers'' [houses]: of Seraiah, Meraiah; of Jeremiah, Hananiah;'),
  ('9f8886c0-bc3c-52a3-ac62-853f30482369', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 13, 13, 'of Ezra, Meshullam; of Amariah, Jehohanan;'),
  ('2fec8822-ae36-5659-a67c-447e74a66d03', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 14, 14, 'of Malluchi, Jonathan; of Shebaniah, Joseph;'),
  ('fdf2132c-820f-5743-a941-12af51b52787', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 15, 15, 'of Harim, Adna; of Meraioth, Helkai;'),
  ('62513ea3-5e80-5789-a370-d83fb2dc6e6c', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 16, 16, 'of Iddo, Zechariah; of Ginnethon, Meshullam;'),
  ('fd72fd92-1af9-565d-a99b-a82b005e0bda', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 17, 17, 'of Abijah, Zichri; of Miniamin, of Moadiah, Piltai;'),
  ('9c81dbf0-a255-5082-a023-948beb8620df', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 18, 18, 'of Bilgah, Shammua; of Shemaiah, Jehonathan;'),
  ('c1fd4403-9eef-5dc9-a1c3-3ba6996bf25c', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 19, 19, 'and of Joiarib, Mattenai; of Jedaiah, Uzzi;'),
  ('7b5ec293-9f12-571d-ad48-6e4ba8d58fcb', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 20, 20, 'of Sallai, Kallai; of Amok, Eber;'),
  ('45fbecea-dbae-552f-a187-df7f9282bc82', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 21, 21, 'of Hilkiah, Hashabiah; of Jedaiah, Nethanel.'),
  ('4c12b781-b5e8-58f9-ab9b-5e1ac67223a3', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 22, 22, 'As for the Levites, in the days of Eliashib, Joiada, and Johanan, and Jaddua, there were recorded the heads of fathers'' [houses]; also the priests, in the reign of Darius the Persian.'),
  ('4d018c70-f338-51e6-a0e4-d3431e4529b7', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 23, 23, 'The sons of Levi, heads of fathers'' [houses], were written in the book of the chronicles, even until the days of Johanan the son of Eliashib.'),
  ('a2c80d79-78ad-5d28-a35a-6cff70c2fdba', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 24, 24, 'The chiefs of the Levites: Hashabiah, Sherebiah, and Jeshua the son of Kadmiel, with their brothers over against them, to praise and give thanks, according to the commandment of David the man of God, watch next to watch.'),
  ('c7a62205-8597-568d-af90-28352c291513', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 25, 25, 'Mattaniah, and Bakbukiah, Obadiah, Meshullam, Talmon, Akkub, were porters keeping the watch at the storehouses of the gates.'),
  ('05b76b53-8799-5caa-a7d8-81114e7b010e', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 26, 26, 'These were in the days of Joiakim the son of Jeshua, the son of Jozadak, and in the days of Nehemiah the governor, and of Ezra the priest the scribe.'),
  ('ee35e1f9-2cbb-519e-ad6a-9864743b145c', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 27, 27, 'At the dedication of the wall of Jerusalem they sought the Levites out of all their places, to bring them to Jerusalem, to keep the dedication with gladness, both with giving thanks, and with singing, with cymbals, stringed instruments, and with harps.'),
  ('c23805dc-0eb7-5d1d-a905-9e7628eac895', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 28, 28, 'The sons of the singers gathered themselves together, both out of the plain around Jerusalem, and from the villages of the Netophathites;'),
  ('6a8017fe-718f-5e56-a240-a715fc91ad74', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 29, 29, 'also from Beth Gilgal, and out of the fields of Geba and Azmaveth: for the singers had built them villages around Jerusalem.'),
  ('2cd7a55c-63e8-55b6-aefe-9599631a70f3', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 30, 30, 'The priests and the Levites purified themselves; and they purified the people, and the gates, and the wall.'),
  ('4251a3d6-a0b8-5fd5-a554-011d64960719', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 31, 31, 'Then I brought up the princes of Judah on the wall, and appointed two great companies who gave thanks and went in procession. [One went] on the right hand on the wall toward the dung gate;'),
  ('1f499cc0-e02d-57c5-a9a6-6c18bd83a2d0', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 32, 32, 'and after them went Hoshaiah, and half of the princes of Judah,'),
  ('ccf5ee47-f9f9-5537-a315-c994663d6826', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 33, 33, 'and Azariah, Ezra, and Meshullam,'),
  ('c2d23c2f-5682-5f7b-a9a9-0bfc7a229347', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 34, 34, 'Judah, and Benjamin, and Shemaiah, and Jeremiah,'),
  ('57c897e7-bdc7-5b72-a1d1-187a81279abd', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 35, 35, 'and certain of the priests'' sons with trumpets: Zechariah the son of Jonathan, the son of Shemaiah, the son of Mattaniah, the son of Micaiah, the son of Zaccur, the son of Asaph;'),
  ('418616e9-b6ba-5339-a5a6-5f7040fe19cf', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 36, 36, 'and his brothers, Shemaiah, and Azarel, Milalai, Gilalai, Maai, Nethanel, and Judah, Hanani, with the musical instruments of David the man of God; and Ezra the scribe was before them.'),
  ('20210c8e-5a93-5f27-abaa-0d7de4b5e8ec', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 37, 37, 'By the spring gate, and straight before them, they went up by the stairs of the city of David, at the ascent of the wall, above the house of David, even to the water gate eastward.'),
  ('838e24d9-3c31-59b8-a8fc-26d97eedf945', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 38, 38, 'The other company of those who gave thanks went to meet them, and I after them, with the half of the people, on the wall, above the tower of the furnaces, even to the broad wall,'),
  ('14c99ead-a45c-5de2-a798-d15e91db18b5', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 39, 39, 'and above the gate of Ephraim, and by the old gate, and by the fish gate, and the tower of Hananel, and the tower of Hammeah, even to the sheep gate: and they stood still in the gate of the guard.'),
  ('ffb4715b-d2de-5433-a948-656648546b26', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 40, 40, 'So stood the two companies of those who gave thanks in the house of God, and I, and the half of the rulers with me;'),
  ('cc7bbafd-ed4d-5339-a474-133d768b6d8e', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 41, 41, 'and the priests, Eliakim, Maaseiah, Miniamin, Micaiah, Elioenai, Zechariah, and Hananiah, with trumpets;'),
  ('4d36e7b6-46c3-5b75-ac22-379395ad1131', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 42, 42, 'and Maaseiah, and Shemaiah, and Eleazar, and Uzzi, and Jehohanan, and Malchijah, and Elam, and Ezer. The singers sang loud, with Jezrahiah their overseer.'),
  ('361bb350-ef94-5e7a-af95-ca82e12db4af', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 43, 43, 'They offered great sacrifices that day, and rejoiced; for God had made them rejoice with great joy; and the women also and the children rejoiced: so that the joy of Jerusalem was heard even afar off.'),
  ('24fa6783-044e-52ca-acc8-256b42dd3474', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 44, 44, 'On that day were men appointed over the rooms for the treasures, for the wave offerings, for the first fruits, and for the tithes, to gather into them, according to the fields of the cities, the portions appointed by the law for the priests and Levites: for Judah rejoiced for the priests and for the Levites who waited.'),
  ('69ae6d52-db82-5a7e-a9d7-09893412ef8b', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 45, 45, 'They performed the duty of their God, and the duty of the purification, and [so did] the singers and the porters, according to the commandment of David, and of Solomon his son.'),
  ('560a6e37-f817-514d-a174-102f66ac08b6', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 46, 46, 'For in the days of David and Asaph of old there was a chief of the singers, and songs of praise and thanksgiving to God.'),
  ('493be463-cee0-57d7-ad10-72726ce44238', 'cbc2e6a0-6a22-51ec-a495-c38f2d07e94c', NULL, 47, 47, 'All Israel in the days of Zerubbabel, and in the days of Nehemiah, gave the portions of the singers and the porters, as every day required: and they set apart [that which was] for the Levites; and the Levites set apart [that which was] for the sons of Aaron.'),
  ('20136af4-40e2-5a8e-a060-e8b5d02e954d', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 1, 1, 'On that day they read in the book of Moses in the audience of the people; and therein was found written, that an Ammonite and a Moabite should not enter into the assembly of God forever,'),
  ('a7f5ff4d-60e4-5aa2-ad7f-392e27825bd8', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 2, 2, 'because they didn''t meet the children of Israel with bread and with water, but hired Balaam against them, to curse them: however our God turned the curse into a blessing.'),
  ('4d862454-09f2-50ac-a21a-6f18989debdf', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 3, 3, 'It came to pass, when they had heard the law, that they separated from Israel all the mixed multitude.'),
  ('207d3000-67f2-53f0-ac4f-6306991abeec', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 4, 4, 'Now before this, Eliashib the priest, who was appointed over the rooms of the house of our God, being allied to Tobiah,'),
  ('cfaea388-3c2c-5e7e-abde-e29932b6f39e', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 5, 5, 'had prepared for him a great room, where before they laid the meal offerings, the frankincense, and the vessels, and the tithes of the grain, the new wine, and the oil, which were given by commandment to the Levites, and the singers, and the porters; and the wave offerings for the priests.'),
  ('8209ec56-3162-55dc-a046-1e802329d6f0', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 6, 6, 'But in all this [time] I was not at Jerusalem; for in the two and thirtieth year of Artaxerxes king of Babylon I went to the king: and after certain days asked I leave of the king,'),
  ('becbcd5b-46fb-5118-a14e-2f58990181a9', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 7, 7, 'and I came to Jerusalem, and understood the evil that Eliashib had done for Tobiah, in preparing him a room in the courts of the house of God.'),
  ('6a23936a-42bf-5ae5-a890-5842f1a404ec', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 8, 8, 'It grieved me severely: therefore I cast forth all the household stuff of Tobiah out of the room.'),
  ('cc320299-3059-5382-a32c-b678b508bea6', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 9, 9, 'Then I commanded, and they cleansed the rooms: and there brought I again the vessels of the house of God, with the meal offerings and the frankincense.'),
  ('8e1c81fd-d25a-5124-abb6-b8805fac8b51', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 10, 10, 'I perceived that the portions of the Levites had not been given them; so that the Levites and the singers, who did the work, had fled everyone to his field.'),
  ('550ed570-a6bb-5a1e-a532-01c1358633ff', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 11, 11, 'Then I contended with the rulers, and said, "Why is the house of God forsaken?" I gathered them together, and set them in their place.'),
  ('75eec17f-8c69-5db5-a60e-7120f4cc30df', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 12, 12, 'Then brought all Judah the tithe of the grain and the new wine and the oil to the treasuries.'),
  ('16dad21f-d566-5984-ab5c-a516fc77a6bc', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 13, 13, 'I made treasurers over the treasuries, Shelemiah the priest, and Zadok the scribe, and of the Levites, Pedaiah: and next to them was Hanan the son of Zaccur, the son of Mattaniah; for they were counted faithful, and their business was to distribute to their brothers.'),
  ('5390fe4a-3be4-59f7-a94c-3517f81df5c5', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 14, 14, 'Remember me, my God, concerning this, and don''t wipe out my good deeds that I have done for the house of my God, and for its observances.'),
  ('ed30e139-9fe1-5e43-a576-11a0f8e93832', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 15, 15, 'In those days saw I in Judah some men treading winepresses on the Sabbath, and bringing in sheaves, and loading donkeys [therewith]; as also wine, grapes, and figs, and all kinds of burdens, which they brought into Jerusalem on the Sabbath day: and I testified [against them] in the day in which they sold food.'),
  ('24b76148-66e1-5b68-aa3a-93ecfd9c7e7d', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 16, 16, 'There lived men of Tyre also therein, who brought in fish, and all kinds of wares, and sold on the Sabbath to the children of Judah, and in Jerusalem.'),
  ('6689e0bb-e1a5-50df-a3ce-72e6ca8ba60e', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 17, 17, 'Then I contended with the nobles of Judah, and said to them, "What evil thing is this that you do, and profane the Sabbath day?'),
  ('5be99049-aded-509c-a13b-3110f28a02c8', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 18, 18, 'Didn''t your fathers do thus, and didn''t our God bring all this evil on us, and on this city? Yet you bring more wrath on Israel by profaning the Sabbath."'),
  ('cb2ee809-aa90-57ff-a7e0-6558397b85e4', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 19, 19, 'It came to pass that, when the gates of Jerusalem began to be dark before the Sabbath, I commanded that the doors should be shut, and commanded that they should not be opened until after the Sabbath. I set some of my servants over the gates, that no burden should be brought in on the Sabbath day.'),
  ('0bbd145d-3698-581e-a76e-9de0d4bf2e8e', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 20, 20, 'So the merchants and sellers of all kinds of wares lodged outside of Jerusalem once or twice.'),
  ('2627b799-e9ae-58e1-a64c-d720657ba2a0', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 21, 21, 'Then I testified against them, and said to them, "Why do you stay around the wall? If you do so again, I will lay hands on you." From that time on, they didn''t come on the Sabbath.'),
  ('043ce32a-7fe4-5c23-a9d0-5c7f76969ede', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 22, 22, 'I commanded the Levites that they should purify themselves, and that they should come and keep the gates, to sanctify the Sabbath day. Remember to me, my God, this also, and spare me according to the greatness of your loving kindness.'),
  ('ffe9e3d8-1ec2-57bc-a964-72beed131b4a', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 23, 23, 'In those days also saw I the Jews who had married women of Ashdod, of Ammon, [and] of Moab:'),
  ('a7160dda-f330-581b-a53e-4233c6eec57a', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 24, 24, 'and their children spoke half in the speech of Ashdod, and could not speak in the Jews'' language, but according to the language of each people.'),
  ('4787d879-a53c-5e56-a80b-9bd2b0324803', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 25, 25, 'I contended with them, and cursed them, and struck certain of them, and plucked off their hair, and made them swear by God, [saying], "You shall not give your daughters to their sons, nor take their daughters for your sons, or for yourselves.'),
  ('1c1fb644-bf0f-559f-aead-4c5ece778378', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 26, 26, 'Didn''t Solomon king of Israel sin by these things? Yet among many nations was there no king like him, and he was beloved of his God, and God made him king over all Israel. Nevertheless foreign women caused even him to sin.'),
  ('299f4c3d-1bf0-53f3-a45b-b61546fc5c1f', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 27, 27, 'Shall we then listen to you to do all this great evil, to trespass against our God in marrying foreign women?"'),
  ('675d0f83-86f3-52fb-ace6-2bf45a7808d3', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 28, 28, 'One of the sons of Joiada, the son of Eliashib the high priest, was son-in-law to Sanballat the Horonite: therefore I chased him from me.'),
  ('4feeea84-6ea6-541d-a50b-8049cf8227fb', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 29, 29, 'Remember them, my God, because they have defiled the priesthood, and the covenant of the priesthood, and of the Levites.'),
  ('472078a6-5933-5544-a0ad-6d0c459250e5', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 30, 30, 'Thus I cleansed them from all foreigners, and appointed duties for the priests and for the Levites, everyone in his work;'),
  ('cf4f1a43-da8d-585e-a7f8-cebb330f3514', '80b9942e-b251-5683-a7c7-b859c385a3f2', NULL, 31, 31, 'and for the wood offering, at times appointed, and for the first fruits. Remember me, my God, for good.'),
  ('59472b7f-fd31-5b65-ad2f-7fd11b330d2e', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 1, 1, 'Now it happened in the days of Ahasuerus (this is Ahasuerus who reigned from India even to Ethiopia, over one hundred twenty-seven provinces),'),
  ('2a79e8fe-31c2-5ddd-a821-581abb645126', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 2, 2, 'that in those days, when the King Ahasuerus sat on the throne of his kingdom, which was in Shushan the palace,'),
  ('6078d01b-33bb-59d3-a355-a70e702874ce', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 3, 3, 'in the third year of his reign, he made a feast for all his princes and his servants; the power of Persia and Media, the nobles and princes of the provinces, being before him.'),
  ('a9ebd366-e859-5e18-ab0a-e4b9717841da', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 4, 4, 'He displayed the riches of his glorious kingdom and the honor of his excellent majesty many days, even one hundred eighty days.'),
  ('3c78056a-3c23-5073-a0e7-bccbe6c81393', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 5, 5, 'When these days were fulfilled, the king made a seven day feast for all the people who were present in Shushan the palace, both great and small, in the court of the garden of the king''s palace.'),
  ('5969c994-5d2e-51d6-a583-5f8dbce1062c', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 6, 6, 'There were hangings of white, green, and blue material, fastened with cords of fine linen and purple to silver rings and marble pillars. The couches were of gold and silver, on a pavement of red, white, yellow, and black marble.'),
  ('86dc6d4c-8de5-5584-a232-aa1d0376bc12', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 7, 7, 'They gave them drinks in golden vessels of various kinds, including royal wine in abundance, according to the bounty of the king.'),
  ('0b1093f3-f15c-5007-afdc-7ec2a4699ff9', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 8, 8, 'In accordance with the law, the drinking was not compulsory; for so the king had instructed all the officials of his house, that they should do according to every man''s pleasure.'),
  ('93c437e1-3e95-51e1-a147-3dfc4eff0a36', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 9, 9, 'Also Vashti the queen made a feast for the women in the royal house which belonged to King Ahasuerus.'),
  ('db1a845d-925d-503e-a6f7-5da24c6557d3', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 10, 10, 'On the seventh day, when the heart of the king was merry with wine, he commanded Mehuman, Biztha, Harbona, Bigtha, and Abagtha, Zethar, and Carcass, the seven eunuchs who served in the presence of Ahasuerus the king,'),
  ('4591ecac-6a93-5bfd-add8-9eabf9362ff6', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 11, 11, 'to bring Vashti the queen before the king with the royal crown, to show the people and the princes her beauty; for she was beautiful.'),
  ('5641e62c-d89a-5187-a09f-ebafa3461d33', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 12, 12, 'But the queen Vashti refused to come at the king''s commandment by the eunuchs. Therefore the king was very angry, and his anger burned in him.'),
  ('1ab2fbd1-f75c-5297-a53b-4f9d56741898', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 13, 13, 'Then the king said to the wise men, who knew the times, (for it was the king''s custom to consult those who knew law and judgment;'),
  ('e714d222-4440-5f17-ac0d-9cc3103aed66', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 14, 14, 'and the next to him were Carshena, Shethar, Admatha, Tarshish, Meres, Marsena, and Memucan, the seven princes of Persia and Media, who saw the king''s face, and sat first in the kingdom),'),
  ('9a4ee338-987a-5998-a585-2fae898fe5c1', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 15, 15, '"What shall we do to the queen Vashti according to law, because she has not done the bidding of the King Ahasuerus by the eunuchs?"'),
  ('aecb521c-6327-50d4-a2f0-4ba04466b94d', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 16, 16, 'Memucan answered before the king and the princes, "Vashti the queen has not done wrong to just the king, but also to all the princes, and to all the people who are in all the provinces of the King Ahasuerus.'),
  ('d6365b39-b679-5f7a-a678-c40086e4edbb', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 17, 17, 'For this deed of the queen will become known to all women, causing them to show contempt for their husbands, when it is reported, ''King Ahasuerus commanded Vashti the queen to be brought in before him, but she didn''t come.'''),
  ('5f457e08-c63c-5c7a-ae2f-cca26ffa31ee', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 18, 18, 'Today, the princesses of Persia and Media who have heard of the queen''s deed will tell all the king''s princes. This will cause much contempt and wrath.'),
  ('91da0f5a-4c93-50ce-a398-04cc7d328cea', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 19, 19, '"If it please the king, let a royal commandment go from him, and let it be written among the laws of the Persians and the Medes, so that it cannot be altered, that Vashti may never again come before King Ahasuerus; and let the king give her royal estate to another who is better than she.'),
  ('211583b2-fcee-5af9-a221-457db5a047bf', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 20, 20, 'When the king''s decree which he shall make is published throughout all his kingdom (for it is great), all the wives will give their husbands honor, both great and small."'),
  ('17990c0b-2a15-5eae-acf9-83670bd0301a', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 21, 21, 'This advice pleased the king and the princes, and the king did according to the word of Memucan:'),
  ('7fd91823-ea9b-5eca-a70c-c6d2b6543574', '56d51d37-1a49-573c-a93e-bd48b5e4d536', NULL, 22, 22, 'for he sent letters into all the king''s provinces, into every province according to its writing, and to every people in their language, that every man should rule his own house, speaking in the language of his own people.'),
  ('7284d9da-f211-591d-a68d-6adbbde68489', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 1, 1, 'After these things, when the wrath of King Ahasuerus was pacified, he remembered Vashti, and what she had done, and what was decreed against her.'),
  ('62d2cab0-f706-5197-af76-b49b0db4be0b', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 2, 2, 'Then the king''s servants who served him said, "Let beautiful young virgins be sought for the king.'),
  ('a7bc3b73-e665-54f3-af03-26835d6c5a48', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 3, 3, 'Let the king appoint officers in all the provinces of his kingdom, that they may gather together all the beautiful young virgins to the citadel of Susa, to the women''s house, to the custody of Hegai the king''s eunuch, keeper of the women. Let cosmetics be given them;'),
  ('fb3817d9-8af2-5150-a6b8-a12d23111170', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 4, 4, 'and let the maiden who pleases the king be queen instead of Vashti." The thing pleased the king, and he did so.'),
  ('305792ce-753c-5895-a650-945188e8d9af', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 5, 5, 'There was a certain Jew in the citadel of Susa, whose name was Mordecai, the son of Jair, the son of Shimei, the son of Kish, a Benjamite,'),
  ('ad579414-8fbf-58ec-aa15-36947a731cf8', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 6, 6, 'who had been carried away from Jerusalem with the captives who had been carried away with Jeconiah king of Judah, whom Nebuchadnezzar the king of Babylon had carried away.'),
  ('42831bc8-cef7-572a-ad04-2fd17411ddf2', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 7, 7, 'He brought up Hadassah, that is, Esther, his uncle''s daughter; for she had neither father nor mother. The maiden was fair and beautiful; and when her father and mother were dead, Mordecai took her for his own daughter.'),
  ('b0fe3134-bd90-5c95-adc4-8214b7893c9e', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 8, 8, 'So it happened, when the king''s commandment and his decree was heard, and when many maidens were gathered together to the citadel of Susa, to the custody of Hegai, that Esther was taken into the king''s house, to the custody of Hegai, keeper of the women.'),
  ('7204ee33-0c3c-52f3-a54d-c6026360d9f6', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 9, 9, 'The maiden pleased him, and she obtained kindness from him. He quickly gave her cosmetics and her portions of food, and the seven choice maidens who were to be given her out of the king''s house. He moved her and her maidens to the best place in the women''s house.'),
  ('a6c7a838-022a-5176-a3a9-85614a91151c', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 10, 10, 'Esther had not made known her people nor her relatives, because Mordecai had instructed her that she should not make it known.'),
  ('3134f501-ff89-5a33-a015-d58a076ff0fa', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 11, 11, 'Mordecai walked every day in front of the court of the women''s house, to find out how Esther did, and what would become of her.'),
  ('1c61fe03-2891-5dda-a2db-f03b9f7d483d', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 12, 12, 'Each young woman''s turn came to go in to King Ahasuerus after her purification for twelve months (for so were the days of their purification accomplished, six months with oil of myrrh, and six months with sweet fragrances and with preparations for beautifying women).'),
  ('35e53778-e498-548e-af05-3f1159b84b91', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 13, 13, 'The young woman then came to the king like this: whatever she desired was given her to go with her out of the women''s house to the king''s house.'),
  ('8613a3c8-2b53-53bd-a26c-dc1c8a95cde9', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 14, 14, 'In the evening she went, and on the next day she returned into the second women''s house, to the custody of Shaashgaz, the king''s eunuch, who kept the concubines. She came in to the king no more, unless the king delighted in her, and she was called by name.'),
  ('0f9300ac-48b9-5fe2-afc7-01aa1c2795df', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 15, 15, 'Now when the turn of Esther, the daughter of Abihail the uncle of Mordecai, who had taken her for his daughter, came to go in to the king, she required nothing but what Hegai the king''s eunuch, the keeper of the women, advised. Esther obtained favor in the sight of all those who looked at her.'),
  ('aa9502d8-62dc-5207-a8e1-5fad9ab879cb', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 16, 16, 'So Esther was taken to King Ahasuerus into his royal house in the tenth month, which is the month Tebeth, in the seventh year of his reign.'),
  ('8caa5b54-ab46-5d72-a0f2-589e8de9db8e', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 17, 17, 'The king loved Esther more than all the women, and she obtained favor and kindness in his sight more than all the virgins; so that he set the royal crown on her head, and made her queen instead of Vashti.'),
  ('312e93fa-c4f1-5624-a33f-ed56dfbefdce', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 18, 18, 'Then the king made a great feast for all his princes and his servants, even Esther''s feast; and he proclaimed a holiday in the provinces, and gave gifts according to the king''s bounty.'),
  ('ab914c1d-674f-5313-a409-1d4335405163', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 19, 19, 'When the virgins were gathered together the second time, Mordecai was sitting in the king''s gate.'),
  ('d6a4e048-1006-5848-a1aa-d8df9fdc165d', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 20, 20, 'Esther had not yet made known her relatives nor her people, as Mordecai had commanded her; for Esther obeyed Mordecai, like she did when she was brought up by him.'),
  ('99828caf-2bc7-5a8a-a496-e136cb755853', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 21, 21, 'In those days, while Mordecai was sitting in the king''s gate, two of the king''s eunuchs, Bigthan and Teresh, who were doorkeepers, were angry, and sought to lay hands on the King Ahasuerus.'),
  ('0428022c-6284-5630-a291-ccebcbbc46aa', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 22, 22, 'This thing became known to Mordecai, who informed Esther the queen; and Esther informed the king in Mordecai''s name.'),
  ('61d0eada-09d4-5998-ad24-648d8e48d359', '306bd5cd-43eb-5b20-a15f-552dd76ec014', NULL, 23, 23, 'When this matter was investigated, and it was found to be so, they were both hanged on a tree; and it was written in the book of the chronicles in the king''s presence.'),
  ('0535c843-52b4-5392-ae6a-2ee60087f19a', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 1, 1, 'After these things King Ahasuerus promoted Haman the son of Hammedatha the Agagite, and advanced him, and set his seat above all the princes who were with him.'),
  ('ed92fa7f-7c6a-530e-a66a-2a52c956281c', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 2, 2, 'All the king''s servants who were in the king''s gate bowed down, and paid homage to Haman; for the king had so commanded concerning him. But Mordecai didn''t bow down or pay him homage.'),
  ('001883b2-6173-5b89-ad2d-5b592d11e74e', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 3, 3, 'Then the king''s servants, who were in the king''s gate, said to Mordecai, "Why do you disobey the king''s commandment?"'),
  ('925a3a22-70c7-5e37-a858-66710282145c', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 4, 4, 'Now it came to pass, when they spoke daily to him, and he didn''t listen to them, that they told Haman, to see whether Mordecai''s reason would stand; for he had told them that he was a Jew.'),
  ('ed8d4e87-2e23-57ad-a206-ff07741c7642', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 5, 5, 'When Haman saw that Mordecai didn''t bow down, nor pay him homage, Haman was full of wrath.'),
  ('0131c21f-b2fb-5441-aa9c-6cd42d85bbcb', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 6, 6, 'But he scorned the thought of laying hands on Mordecai alone, for they had made known to him Mordecai''s people. Therefore Haman sought to destroy all the Jews who were throughout the whole kingdom of Ahasuerus, even Mordecai''s people.'),
  ('cd4ea415-cf41-5eaf-a3b7-1986c1f73132', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 7, 7, 'In the first month, which is the month Nisan, in the twelfth year of King Ahasuerus, they cast Pur, that is, the lot, before Haman from day to day, and from month to month, and chose the twelfth month, which is the month Adar.'),
  ('3afb2250-d2fc-5d8e-a97d-6a983e46b415', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 8, 8, 'Haman said to King Ahasuerus, "There is a certain people scattered abroad and dispersed among the peoples in all the provinces of your kingdom, and their laws are different than other people''s. They don''t keep the king''s laws. Therefore it is not for the king''s profit to allow them to remain.'),
  ('4e99ded8-7602-58d1-ab0b-8dfa34e24538', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 9, 9, 'If it pleases the king, let it be written that they be destroyed; and I will pay ten thousand talents of silver into the hands of those who are in charge of the king''s business, to bring it into the king''s treasuries."'),
  ('68d71cdf-34ee-54fd-a0a0-301e37dab4c8', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 10, 10, 'The king took his ring from his hand, and gave it to Haman the son of Hammedatha the Agagite, the Jews'' enemy.'),
  ('adebe915-16ad-51a2-a437-2e90713e8451', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 11, 11, 'The king said to Haman, "The silver is given to you, the people also, to do with them as it seems good to you."'),
  ('577c9fe9-13c8-5f3b-aefb-4e517ba021dd', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 12, 12, 'Then the king''s scribes were called in on the first month, on the thirteenth day of the month; and all that Haman commanded was written to the king''s satraps, and to the governors who were over every province, and to the princes of every people, to every province according its writing, and to every people in their language. It was written in the name of King Ahasuerus, and it was sealed with the king''s ring.'),
  ('f88ae07b-af47-53dc-a2be-a907ea673968', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 13, 13, 'Letters were sent by couriers into all the king''s provinces, to destroy, to kill, and to cause to perish, all Jews, both young and old, little children and women, in one day, even on the thirteenth day of the twelfth month, which is the month Adar, and to plunder their possessions.'),
  ('bf31e226-c03b-5d86-a864-f9c432147ad5', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 14, 14, 'A copy of the letter, that the decree should be given out in every province, was published to all the peoples, that they should be ready against that day.'),
  ('8277be70-c0a2-57a5-ac77-18e016c24ce3', '1473abf8-8370-5310-ac0f-e33d387eb308', NULL, 15, 15, 'The couriers went forth in haste by the king''s commandment, and the decree was given out in the citadel of Susa. The king and Haman sat down to drink; but the city of Shushan was perplexed.'),
  ('e57e0bea-8983-5551-a0e7-5175dcb3aad8', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 1, 1, 'Now when Mordecai found out all that was done, Mordecai tore his clothes, and put on sackcloth with ashes, and went out into the midst of the city, and wailed loudly and a bitterly.'),
  ('edca4955-2cbc-5d50-a9f4-c0e0d86843d1', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 2, 2, 'He came even before the king''s gate, for no one is allowed inside the king''s gate clothed with sackcloth.'),
  ('69320d69-28a2-5c1d-aea4-c68b699cc057', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 3, 3, 'In every province, wherever the king''s commandment and his decree came, there was great mourning among the Jews, and fasting, and weeping, and wailing; and many lay in sackcloth and ashes.'),
  ('9724c134-1d5a-5d2f-ae75-0e83b5900a9d', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 4, 4, 'Esther''s maidens and her eunuchs came and told her this, and the queen was exceedingly grieved. She sent clothing to Mordecai, to replace his sackcloth; but he didn''t receive it.'),
  ('ef9d925e-f71c-5398-a132-e0b3ebf191c4', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 5, 5, 'Then Esther called for Hathach, one of the king''s eunuchs, whom he had appointed to attend her, and commanded him to go to Mordecai, to find out what this was, and why it was.'),
  ('53e8eeea-a92e-52d0-afc0-d2d4b5ae65a5', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 6, 6, 'So Hathach went out to Mordecai, to city square which was before the king''s gate.'),
  ('aed844c8-79c4-51f3-a4bb-d98a5c1fe241', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 7, 7, 'Mordecai told him of all that had happened to him, and the exact sum of the money that Haman had promised to pay to the king''s treasuries for the destruction of the Jews.'),
  ('00f8279c-df48-5b14-a300-d35d5c061844', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 8, 8, 'He also gave him the copy of the writing of the decree that was given out in Shushan to destroy them, to show it to Esther, and to declare it to her, and to urge her to go in to the king, to make supplication to him, and to make request before him, for her people.'),
  ('18939318-90ec-594d-a003-b852c503025a', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 9, 9, 'Hathach came and told Esther the words of Mordecai.'),
  ('f5c09cf5-46ee-5af4-a570-d997caaad208', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 10, 10, 'Then Esther spoke to Hathach, and gave him a message to Mordecai:'),
  ('eede5022-64a7-5c4d-a888-ab70a4851a06', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 11, 11, '"All the king''s servants, and the people of the king''s provinces, know, that whoever, whether man or woman, comes to the king into the inner court without being called, there is one law for him, that he be put to death, except those to whom the king might hold out the golden scepter, that he may live. I have not been called to come in to the king these thirty days."'),
  ('65f79b33-70a0-5e6a-ab8f-81c5d54bf2c5', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 12, 12, 'They told to Mordecai Esther''s words.'),
  ('683388b6-da57-513f-afcb-5f0c85febc0a', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 13, 13, 'Then Mordecai asked them return answer to Esther, "Don''t think to yourself that you will escape in the king''s house any more than all the Jews.'),
  ('9d7b93af-2b52-5edb-a0d2-c7c2f424a1df', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 14, 14, 'For if you remain silent now, then relief and deliverance will come to the Jews from another place, but you and your father''s house will perish. Who knows if you haven''t come to the kingdom for such a time as this?"'),
  ('18332f7f-96b4-5ea9-aad6-1dd4e1ad712e', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 15, 15, 'Then Esther asked them to answer Mordecai,'),
  ('5ce4ee0b-d74f-590d-a695-0a058ab33801', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 16, 16, '"Go, gather together all the Jews who are present in Shushan, and fast for me, and neither eat nor drink three days, night or day. I and my maidens will also fast the same way. Then I will go in to the king, which is against the law; and if I perish, I perish."'),
  ('e7920cf0-9f52-592e-aff8-bfd8889869a2', '10c13297-7c24-5630-a35e-4915c85d8838', NULL, 17, 17, 'So Mordecai went his way, and did according to all that Esther had commanded him.'),
  ('91332e00-e09f-5e09-ae29-73bc50eb999e', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 1, 1, 'Now it happened on the third day that Esther put on her royal clothing, and stood in the inner court of the king''s house, next to the king''s house. The king sat on his royal throne in the royal house, next to the entrance of the house.'),
  ('8c40345a-2bd5-54e7-a9c1-2ef9ee85b7c1', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 2, 2, 'When the king saw Esther the queen standing in the court, she obtained favor in his sight; and the king held out to Esther the golden scepter that was in his hand. So Esther came near, and touched the top of the scepter.'),
  ('82bbcfdf-7715-5662-a1d7-258b50a80f79', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 3, 3, 'Then the king asked her, "What would you like, queen Esther? What is your request? It shall be given you even to the half of the kingdom."'),
  ('3d0525ec-8dd0-56e9-a3af-11e433faa855', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 4, 4, 'Esther said, "If it seems good to the king, let the king and Haman come today to the banquet that I have prepared for him."'),
  ('171775ed-5092-51cb-ab5b-be44f9052544', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 5, 5, 'Then the king said, "Bring Haman quickly, so that it may be done as Esther has said." So the king and Haman came to the banquet that Esther had prepared.'),
  ('2906a31b-a1bd-5db4-aa97-fcc73f6edd56', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 6, 6, 'The king said to Esther at the banquet of wine, "What is your petition? It shall be granted you. What is your request? Even to the half of the kingdom it shall be performed."'),
  ('3d67548c-d050-55af-ad1d-d64a04c6fc8e', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 7, 7, 'Then Esther answered and said, "My petition and my request is this.'),
  ('9ceae79d-ee75-5831-abbb-1f3257d5cd4f', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 8, 8, 'If I have found favor in the sight of the king, and if it please the king to grant my petition and to perform my request, let the king and Haman come to the banquet that I will prepare for them, and I will do tomorrow as the king has said."'),
  ('13960a8c-79da-5a66-a31c-4feb77150045', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 9, 9, 'Then Haman went out that day joyful and glad of heart, but when Haman saw Mordecai in the king''s gate, that he didn''t stand up nor move for him, he was filled with wrath against Mordecai.'),
  ('0d02176e-e72a-5e96-af71-098ac72cbeb5', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 10, 10, 'Nevertheless Haman restrained himself, and went home. There, he sent and called for his friends and Zeresh his wife.'),
  ('855a991d-9075-5d91-aa03-74d957b376ae', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 11, 11, 'Haman recounted to them the glory of his riches, the multitude of his children, all the things in which the king had promoted him, and how he had advanced him above the princes and servants of the king.'),
  ('86729684-f80e-5a7f-ae8f-7c8185e9ab90', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 12, 12, 'Haman also said, "Yes, Esther the queen let no man come in with the king to the banquet that she had prepared but myself; and tomorrow I am also invited by her together with the king.'),
  ('0308d9be-6c02-5981-a8bf-13e4671d55dd', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 13, 13, 'Yet all this avails me nothing, so long as I see Mordecai the Jew sitting at the king''s gate."'),
  ('7b797ae8-8460-56fe-ab72-dd7544b66974', '230e6682-84f3-5671-a635-c946d5cd5ac0', NULL, 14, 14, 'Then Zeresh his wife and all his friends said to him, "Let a gallows be made fifty cubits high, and in the morning speak to the king about hanging Mordecai on it. Then go in merrily with the king to the banquet." This pleased Haman, so he had the gallows made.'),
  ('efbb098c-8f5b-52e0-a13b-b111fb46fa3b', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 1, 1, 'On that night, the king couldn''t sleep. He commanded the book of records of the chronicles to be brought, and they were read to the king.'),
  ('88f77bda-a916-522c-acc3-860f04067da2', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 2, 2, 'It was found written that Mordecai had told of Bigthana and Teresh, two of the king''s eunuchs, who were doorkeepers, who had tried to lay hands on the King Ahasuerus.'),
  ('150067d0-273d-5082-a2f5-5d5719526840', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 3, 3, 'The king said, "What honor and dignity has been bestowed on Mordecai for this?" Then the king''s servants who attended him said, "Nothing has been done for him."'),
  ('772deab1-7eac-5f0f-a08b-fac91afaefbc', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 4, 4, 'The king said, "Who is in the court?" Now Haman had come into the outer court of the king''s house, to speak to the king about hanging Mordecai on the gallows that he had prepared for him.'),
  ('a7c01bad-2fd5-5b5d-ae27-45dce33cd460', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 5, 5, 'The king''s servants said to him, "Behold, Haman stands in the court." The king said, "Let him come in."'),
  ('c7001962-c1fc-507a-abfa-3c65571eb270', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 6, 6, 'So Haman came in. The king said to him, "What shall be done to the man whom the king delights to honor?" Now Haman said in his heart, "Who would the king delight to honor more than myself?"'),
  ('21c63942-c27d-5715-adbc-db5ca7931b9f', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 7, 7, 'Haman said to the king, "For the man whom the king delights to honor,'),
  ('60229a2c-cc35-5d12-a568-559d004190fa', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 8, 8, 'let royal clothing be brought which the king uses to wear, and the horse that the king rides on, and on the head of which a crown royal is set.'),
  ('b8293593-4c80-5d58-a3d7-451c8c59017a', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 9, 9, 'Let the clothing and the horse be delivered to the hand of one of the king''s most noble princes, that they may array the man whom the king delights to honor with them, and have him ride on horseback through the city square, and proclaim before him, ''Thus shall it be done to the man whom the king delights to honor!''"'),
  ('d7143103-4c7f-59a9-a911-60c20d94815f', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 10, 10, 'Then the king said to Haman, "Hurry and take the clothing and the horse, as you have said, and do this for Mordecai the Jew, who sits at the king''s gate. Let nothing fail of all that you have spoken."'),
  ('e12de33e-9349-5871-abb7-2096211c7d24', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 11, 11, 'Then Haman took the clothing and the horse, and arrayed Mordecai, and had him ride through the city square, and proclaimed before him, "Thus shall it be done to the man whom the king delights to honor!"'),
  ('abcdeacd-614b-5ec6-a808-bbd227f1fedd', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 12, 12, 'Mordecai came back to the king''s gate, but Haman hurried to his house, mourning and having his head covered.'),
  ('90210033-91c7-5e70-a187-f77152f4c0c8', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 13, 13, 'Haman recounted to Zeresh his wife and all his friends everything that had happened to him. Then his wise men and Zeresh his wife said to him, "If Mordecai, before whom you have begun to fall, is of Jewish descent, you will not prevail against him, but you will surely fall before him."'),
  ('ecdbc9db-6e0a-546b-abb8-68c42d7aed0a', '2f2d5212-c27a-5483-a1c5-3f1482270e30', NULL, 14, 14, 'While they were yet talking with him, the king''s eunuchs came, and hurried to bring Haman to the banquet that Esther had prepared.'),
  ('e8d9241d-dad7-54c3-ac78-588060cc996b', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 1, 1, 'So the king and Haman came to banquet with Esther the queen.'),
  ('df34ba25-b262-50fa-a217-39ac7436250a', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 2, 2, 'The king said again to Esther on the second day at the banquet of wine, "What is your petition, queen Esther? It shall be granted you. What is your request? Even to the half of the kingdom it shall be performed."'),
  ('43bc3d8d-8c55-5358-a387-3478c6fbaa76', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 3, 3, 'Then Esther the queen answered, "If I have found favor in your sight, O king, and if it please the king, let my life be given me at my petition, and my people at my request.'),
  ('6415c0f9-e0d8-5319-a765-f746945798a5', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 4, 4, 'For we are sold, I and my people, to be destroyed, to be slain, and to perish. But if we had been sold for bondservants and bondmaids, I would have held my peace, although the adversary could not have compensated for the king''s loss."'),
  ('0f5d07aa-161e-5584-a23f-9a85fd2f74dc', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 5, 5, 'Then King Ahasuerus said to Esther the queen, "Who is he, and where is he who dared presume in his heart to do so?"'),
  ('08183ae7-b736-533a-a65b-0c902db0e840', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 6, 6, 'Esther said, "An adversary and an enemy, even this wicked Haman!" Then Haman was afraid before the king and the queen.'),
  ('edcb2471-1b72-52f2-aa44-2102f707ac46', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 7, 7, 'The king arose in his wrath from the banquet of wine and went into the palace garden. Haman stood up to make request for his life to Esther the queen; for he saw that there was evil determined against him by the king.'),
  ('36e2b761-8caf-53e1-ad44-f5685e9d07db', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 8, 8, 'Then the king returned out of the palace garden into the place of the banquet of wine; and Haman had fallen on the couch where Esther was. Then the king said, "Will he even assault the queen in front of me in the house?" As the word went out of the king''s mouth, they covered Haman''s face.'),
  ('72f11332-4cfb-5ab0-acac-904104caf649', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 9, 9, 'Then Harbonah, one of the eunuchs who were with the king said, "Behold, the gallows fifty cubits high, which Haman has made for Mordecai, who spoke good for the king, is standing at Haman''s house." The king said, "Hang him on it!"'),
  ('09afbd10-48d9-5925-a051-ef921009ba49', 'd6693e48-525c-50d9-a954-28bbab683cc1', NULL, 10, 10, 'So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king''s wrath pacified.'),
  ('82b5fb08-402e-5afb-aefe-374c27a37422', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 1, 1, 'On that day, King Ahasuerus gave the house of Haman, the Jews'' enemy, to Esther the queen. Mordecai came before the king; for Esther had told what he was to her.'),
  ('70f3fc7d-bca6-5833-aa0a-808c113e333f', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 2, 2, 'The king took off his ring, which he had taken from Haman, and gave it to Mordecai. Esther set Mordecai over the house of Haman.'),
  ('dab406a2-ddf9-5e0a-a087-541777d76f3a', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 3, 3, 'Esther spoke yet again before the king, and fell down at his feet, and begged him with tears to put away the mischief of Haman the Agagite, and his device that he had devised against the Jews.'),
  ('ae6c313d-d9ad-5e68-ac8f-b89437b8b52c', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 4, 4, 'Then the king held out to Esther the golden scepter. So Esther arose, and stood before the king.'),
  ('89678573-5b6a-5a92-a915-cb354b47cb28', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 5, 5, 'She said, "If it pleases the king, and if I have found favor in his sight, and the thing seem right to the king, and I am pleasing in his eyes, let it be written to reverse the letters devised by Haman, the son of Hammedatha the Agagite, which he wrote to destroy the Jews who are in all the king''s provinces.'),
  ('c2a1391f-ea18-5c8d-acde-93d4aff701a2', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 6, 6, 'For how can I endure to see the evil that would come to my people? How can I endure to see the destruction of my relatives?"'),
  ('af2db002-c777-570a-a2a6-8c48874167a1', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 7, 7, 'Then King Ahasuerus said to Esther the queen and to Mordecai the Jew, "See, I have given Esther the house of Haman, and him they have hanged on the gallows, because he laid his hand on the Jews.'),
  ('bf77ce28-cf12-5a73-a089-c8ad59f463f3', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 8, 8, 'Write also to the Jews, as it pleases you, in the king''s name, and seal it with the king''s ring; for the writing which is written in the king''s name, and sealed with the king''s ring, may not be reversed by any man."'),
  ('da5eb011-b181-5202-a685-8fb4fcf4fdfc', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 9, 9, 'Then the king''s scribes were called at that time, in the third month Sivan, on the twenty-third day of the month; and it was written according to all that Mordecai commanded to the Jews, and to the satraps, and the governors and princes of the provinces which are from India to Ethiopia, one hundred twenty-seven provinces, to every province according to its writing, and to every people in their language, and to the Jews in their writing, and in their language.'),
  ('7867700f-b353-54e4-a8c1-55825223f70c', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 10, 10, 'He wrote in the name of King Ahasuerus, and sealed it with the king''s ring, and sent letters by courier on horseback, riding on royal horses that were bread from swift steeds.'),
  ('ff72c39a-92f6-51fe-a724-633a5aee3e4b', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 11, 11, 'In those letters, the king granted the Jews who were in every city to gather themselves together, and to defend their life, to destroy, to kill, and to cause to perish, all the power of the people and province that would assault them, their little ones and women, and to plunder their possessions,'),
  ('404ed141-f42a-5034-a107-2a766e012aa9', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 12, 12, 'on one day in all the provinces of King Ahasuerus, on the thirteenth day of the twelfth month, which is the month Adar.'),
  ('3ac477b8-c4aa-56ee-a29f-ed2b7b092907', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 13, 13, 'A copy of the letter, that the decree should be given out in every province, was published to all the peoples, that the Jews should be ready for that day to avenge themselves on their enemies.'),
  ('1e9a510a-0dec-5b37-ab5a-c31cdae228a1', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 14, 14, 'So the couriers who rode on royal horses went out, hastened and pressed on by the king''s commandment. The decree was given out in the citadel of Susa.'),
  ('f3b6818a-4ea9-5c5e-aa02-e1883bffcb16', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 15, 15, 'Mordecai went out of the presence of the king in royal clothing of blue and white, and with a great crown of gold, and with a robe of fine linen and purple; and the city of Susa shouted and was glad.'),
  ('07640a5d-bf49-5305-a94b-d48597a3fd46', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 16, 16, 'The Jews had light, gladness, joy, and honor.'),
  ('0e853e12-c1df-5568-a3a6-a94f29234c10', 'f8888442-1106-55c0-aadf-540b19d57f0b', NULL, 17, 17, 'In every province, and in every city, wherever the king''s commandment and his decree came, the Jews had gladness, joy, a feast, and a good day. Many from among the peoples of the land became Jews; for the fear of the Jews was fallen on them.'),
  ('7454aa89-a648-568f-a880-bd370d930fe4', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 1, 1, 'Now in the twelfth month, which is the month Adar, on the thirteenth day of the month, when the king''s commandment and his decree drew near to be put in execution, on the day that the enemies of the Jews hoped to conquer them, (but it was turned out the opposite happened, that the Jews conquered those who hated them),'),
  ('30b8a9df-85ad-5efc-a6cb-f061bcb2fbc0', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 2, 2, 'the Jews gathered themselves together in their cities throughout all the provinces of the King Ahasuerus, to lay hands on those who wanted to harm them. No one could withstand them, because the fear of them had fallen on all the people.'),
  ('9934e3d0-9e7b-5822-a7f1-f7a109bd62cb', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 3, 3, 'All the princes of the provinces, the satraps, the governors, and those who did the king''s business helped the Jews, because the fear of Mordecai had fallen on them.'),
  ('ad7b9819-bd60-5156-a58c-55805dbf46da', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 4, 4, 'For Mordecai was great in the king''s house, and his fame went out throughout all the provinces; for the man Mordecai grew greater and greater.'),
  ('b0bf542a-c7ad-5c83-acba-2548855b868e', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 5, 5, 'The Jews struck all their enemies with the stroke of the sword, and with slaughter and destruction, and did what they wanted to those who hated them.'),
  ('a91b9b73-527f-5ee6-a784-b19781d8be93', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 6, 6, 'In the citadel of Susa, the Jews killed and destroyed five hundred men.'),
  ('e0c26eec-e5f0-550c-a833-697d0dafe7b3', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 7, 7, 'They killed Parshandatha, Dalphon, Aspatha,'),
  ('056580a8-2f9e-5168-a48f-bb0415e791ca', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 8, 8, 'Poratha, Adalia, Aridatha,'),
  ('f513552f-bc0e-5f72-a0d3-d4ca65ba97ed', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 9, 9, 'Parmashta, Arisai, Aridai, and Vaizatha,'),
  ('dcb1b74d-f77f-5b37-ab7a-485c9919b8af', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 10, 10, 'the ten sons of Haman the son of Hammedatha, the Jew''s enemy, but they didn''t lay their hand on the plunder.'),
  ('2b029253-f5cf-5de4-a624-eaeec4e58790', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 11, 11, 'On that day, the number of those who were slain in the citadel of Susa was brought before the king.'),
  ('2784103d-79db-52da-a4a9-81e0b50b9f50', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 12, 12, 'The king said to Esther the queen, "The Jews have slain and destroyed five hundred men in the citadel of Susa, including the ten sons of Haman; what then have they done in the rest of the king''s provinces! Now what is your petition? It shall be granted you. What is your further request? It shall be done."'),
  ('038fc1de-4942-5ab5-aa4a-6d7d56b34629', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 13, 13, 'Then Esther said, "If it pleases the king, let it be granted to the Jews who are in Shushan to do tomorrow also according to this day''s decree, and let Haman''s ten sons be hanged on the gallows."'),
  ('caed9ab9-003b-5eb5-ae7d-b473dce74253', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 14, 14, 'The king commanded this to be done. A decree was given out in Shushan; and they hanged Haman''s ten sons.'),
  ('37a2ad55-1c66-5ddf-adbe-5cb0f5ea06cb', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 15, 15, 'The Jews who were in Shushan gathered themselves together on the fourteenth day also of the month Adar, and killed three hundred men in Shushan; but they didn''t lay their hand on the spoil.'),
  ('66295475-7dc9-51f8-aafc-cee1de560cdc', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 16, 16, 'The other Jews who were in the king''s provinces gathered themselves together, defended their lives, had rest from their enemies, and killed seventy-five thousand of those who hated them; but they didn''t lay their hand on the plunder.'),
  ('6f3640d9-38df-57ba-af27-215ebfbad68c', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 17, 17, 'This was done on the thirteenth day of the month Adar; and on the fourteenth day of that month they rested and made it a day of feasting and gladness.'),
  ('b8184279-c0ca-5ff8-ae3f-1133323b7e78', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 18, 18, 'But the Jews who were in Shushan assembled together on the thirteenth and on the fourteenth days of the month; and on the fifteenth day of that month, they rested, and made it a day of feasting and gladness.'),
  ('671aa786-49d2-5ea7-a840-e1733d9e3ae0', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 19, 19, 'Therefore the Jews of the villages, who live in the unwalled towns, make the fourteenth day of the month Adar a day of gladness and feasting, a good day, and a day of sending presents of food to one another.'),
  ('a2abe5a6-484a-5bfd-a7c7-013176f6920a', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 20, 20, 'Mordecai wrote these things, and sent letters to all the Jews who were in all the provinces of the king Ahasuerus, both near and far,'),
  ('d2cea2cc-fb0f-5320-a7cb-be0501474d10', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 21, 21, 'to enjoin them that they should keep the fourteenth and fifteenth days of the month Adar yearly,'),
  ('ed200443-a9de-5413-a063-5c6d1d3b48cb', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 22, 22, 'as the days in which the Jews had rest from their enemies, and the month which was turned to them from sorrow to gladness, and from mourning into a good day; that they should make them days of feasting and gladness, and of sending presents of food to one another, and gifts to the needy.'),
  ('aba6c71f-3586-5514-ad7c-1c46d9c0b5ab', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 23, 23, 'The Jews accepted the custom that they had begun, as Mordecai had written to them;'),
  ('4195715d-8aa3-5e60-ab52-401d6f59a587', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 24, 24, 'because Haman the son of Hammedatha, the Agagite, the enemy of all the Jews, had plotted against the Jews to destroy them, and had cast "Pur," that is the lot, to consume them, and to destroy them;'),
  ('cf61fddb-f807-5512-a34c-fe383946714c', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 25, 25, 'but when this became known to the king, he commanded by letters that his wicked device, which he had devised against the Jews, should return on his own head, and that he and his sons should be hanged on the gallows.'),
  ('4533942c-d6d4-5c39-af2e-f9dce055e16a', 'f333f5c4-95b4-55a1-a42f-f36d3048c6aa', NULL, 26, 26, 'Therefore they called these days "Purim," from the word "Pur." Therefore because of all the words of this letter, and of that which they had seen concerning this matter, and that which had come to them,')
